/// The source-language typing rule that rejected an expression.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TypeReason {
    /// A primitive operation received a non-`Int` operand.
    OperatorOperand,
    /// An anonymous function was used without an expected function type.
    FunctionNeedsContext,
    /// An application function position did not have a function type.
    NotApplicable,
    /// An application argument did not match the function domain.
    Argument,
    /// An annotated binding initializer did not match its annotation.
    BindingInitializer,
    /// A global function body did not match its declared result type.
    DefinitionResult,
    /// An equational interface did not expose one function domain.
    EquationInterfaceNotFunction,
    /// A recursive member is not initialized directly by an anonymous function.
    UnsafeRecursiveInitializer,
    /// A recursive data member is not rooted at its declared constructor.
    UnsafeRecursiveRoot,
    /// A recursive occurrence crosses a forcing or transporting form.
    UnguardedRecursiveUse,
    /// A constructor occurrence or pattern disagrees with its declaration.
    ConstructorMismatch,
    /// A pattern constructor belongs to a different nominal declaration.
    ConstructorOwner,
    /// A pattern form disagrees with its expected type.
    PatternMismatch,
    /// Equational clauses consume different or impossible arrow arities.
    EquationArity,
    /// A local binding pattern is semantically refutable.
    RefutableBinding,
    /// A single anonymous or operational domain pattern can fail.
    RefutableFunctionDomain,
    /// A case group leaves a concrete value uncovered.
    NonExhaustive,
    /// A case can never be selected after preceding cases.
    RedundantCase,
    /// First-order inference would construct an infinite type.
    InfiniteType,
    /// Inference left a result type undetermined.
    AmbiguousType,
    /// A recursive use requires distinct instantiations.
    PolymorphicRecursion,
    /// A module newtype representation reaches itself through newtype declarations.
    NewtypeRecursiveRepresentation,
    /// A local nominal identity occurs in the outward computation.
    LocalNominalEscape,
    /// A resource-owned rigid identity occurs outside its acquisition.
    ResourceEscape,
    /// Stored resource dependency proof is not available in this increment.
    /// An effect-row union has no unqualified principal result.
    AmbiguousEffectRow,
    /// A row substitution contains an instance excluded from its tail.
    EffectRowExclusion,
    /// A handler body does not request the exact handled instance.
    MissingHandledEffect,
    /// The target lacks a declared single endomorphic publication API.
    HookApi,
    /// Handler clauses do not cover each operation exactly once.
    HandlerCoverage,
    /// A handler operation pattern can fail.
    RefutableHandlerPattern,
    /// A resume form occurs outside an operation clause.
    ResumeOutsideClause,
    /// A clause can complete without consuming its resume capability.
    ResumeNotConsumed,
    /// One control-flow path consumes a resume capability more than once.
    ResumeAlreadyConsumed,
    /// A nested scope attempts to capture a resume capability.
    ResumeCapture,
    /// Discard lacks proof that its captured segment has no live obligations.
    DiscardUnsafe,
    /// Cleanup would require an interpreter removed by abandonment.
    CleanupContext,
}

/// Projects source computation arrows onto the predecessor pure-Core type
/// grammar used while this checkpoint checks bodies but does not retain Core.
/// Source schemes and expression rows remain unchanged; effect Core lowering
/// owns the corresponding computation nodes in the next checkpoint.
fn pure_core_type_with_budget(ty: &Type, budget: &mut TypeWorkBudget) -> Result<Type, ()> {
    charge_type_cells(ty, budget)?;
    pure_core_type_from_precharged(ty)
}

fn pure_core_type_from_precharged(ty: &Type) -> Result<Type, ()> {
    enum Task<'a> {
        Visit(&'a Type),
        Sequence(std::slice::Iter<'a, Type>),
        Tuple(usize),
        Application,
        Function,
        Forall(Box<[(TypeVariableId, Kind)]>),
    }

    let mut work = vec![Task::Visit(ty)];
    let mut rebuilt = OwnedTypeBuffer(Vec::new());
    while let Some(task) = work.pop() {
        match task {
            Task::Visit(Type::Bytes) => rebuilt.push(Type::Bytes),
            Task::Visit(Type::String) => rebuilt.push(Type::String),
            Task::Visit(Type::Int) => rebuilt.push(Type::Int),
            Task::Visit(Type::Bool) => rebuilt.push(Type::Bool),
            Task::Visit(Type::Unit) => rebuilt.push(Type::Unit),
            Task::Visit(Type::Nominal(identity)) => rebuilt.push(Type::Nominal(*identity)),
            Task::Visit(Type::ResourceApply(_, _)) => return Err(()),
            Task::Visit(Type::Variable(identity)) => rebuilt.push(Type::Variable(*identity)),
            Task::Visit(Type::Inference(identity)) => rebuilt.push(Type::Inference(*identity)),
            Task::Visit(Type::Tuple(elements)) => {
                work.push(Task::Tuple(elements.len()));
                work.push(Task::Sequence(elements.iter()));
            }
            Task::Visit(Type::Application(function, argument)) => {
                work.push(Task::Application);
                work.push(Task::Visit(argument));
                work.push(Task::Visit(function));
            }
            Task::Visit(Type::Function(domain, codomain)) => {
                work.push(Task::Function);
                work.push(Task::Visit(codomain));
                work.push(Task::Visit(domain));
            }
            Task::Visit(Type::EffectfulFunction(domain, codomain)) => {
                work.push(Task::Function);
                work.push(Task::Visit(codomain.value()));
                work.push(Task::Visit(domain));
            }
            Task::Visit(Type::Forall(parameters, body)) => {
                work.push(Task::Forall(parameters.clone()));
                work.push(Task::Visit(body));
            }
            Task::Sequence(mut remaining) => {
                if let Some(next) = remaining.next() {
                    work.push(Task::Sequence(remaining));
                    work.push(Task::Visit(next));
                }
            }
            Task::Tuple(count) => {
                let elements = rebuilt.split_off(rebuilt.len() - count);
                rebuilt.push(Type::Tuple(elements.into_boxed_slice()));
            }
            Task::Application => {
                let argument = IterativeTypeOwner::new(rebuilt.pop().ok_or(())?);
                let function = IterativeTypeOwner::new(rebuilt.pop().ok_or(())?);
                rebuilt.push(Type::Application(
                    Box::new(function.into_inner()),
                    Box::new(argument.into_inner()),
                ));
            }
            Task::Function => {
                let codomain = IterativeTypeOwner::new(rebuilt.pop().ok_or(())?);
                let domain = IterativeTypeOwner::new(rebuilt.pop().ok_or(())?);
                rebuilt.push(Type::Function(
                    Box::new(domain.into_inner()),
                    Box::new(codomain.into_inner()),
                ));
            }
            Task::Forall(parameters) => {
                let body = IterativeTypeOwner::new(rebuilt.pop().ok_or(())?);
                rebuilt.push(Type::Forall(parameters, Box::new(body.into_inner())));
            }
        }
    }
    if rebuilt.len() == 1 {
        rebuilt.pop().ok_or(())
    } else {
        Err(())
    }
}

fn project_type_from_precharged<F: CoreLoweringFamily>(
    ty: &Type,
    budget: &mut TypeWorkBudget,
) -> Result<Type, ()> {
    if F::ALLOWS_EFFECTFUL_TYPES {
        clone_type_with_budget(ty, budget)
    } else {
        pure_core_type_from_precharged(ty)
    }
}

fn pure_core_type_parameters_with_budget(
    parameters: &[(TypeVariableId, Kind)],
    budget: &mut TypeWorkBudget,
) -> Result<Vec<(TypeVariableId, Kind)>, ()> {
    let retained = parameters
        .iter()
        .filter(|(_, kind)| !matches!(kind, Kind::EffectRow))
        .count();
    budget.charge(retained)?;
    let mut core = Vec::new();
    core.try_reserve_exact(retained).map_err(|_| ())?;
    for (identity, kind) in parameters {
        if matches!(kind, Kind::EffectRow) {
            continue;
        }
        core.push((*identity, clone_kind_with_budget(kind, budget)?));
    }
    Ok(core)
}

fn requires_pure_core_projection(
    ty: &Type,
    mut budget: Option<&mut TypeWorkBudget>,
) -> Result<bool, ()> {
    fn schedule<'a>(
        work: &mut Vec<&'a Type>,
        ty: &'a Type,
        budget: &mut Option<&mut TypeWorkBudget>,
    ) -> Result<(), ()> {
        if let Some(budget) = budget.as_deref_mut() {
            budget.charge(1)?;
        }
        work.try_reserve(1).map_err(|_| ())?;
        work.push(ty);
        Ok(())
    }

    let mut work = Vec::new();
    schedule(&mut work, ty, &mut budget)?;
    while let Some(current) = work.pop() {
        match current {
            Type::EffectfulFunction(_, _) | Type::ResourceApply(_, _) => return Ok(true),
            Type::Tuple(elements) => {
                for element in elements {
                    schedule(&mut work, element, &mut budget)?;
                }
            }
            Type::Application(function, argument) | Type::Function(function, argument) => {
                schedule(&mut work, argument, &mut budget)?;
                schedule(&mut work, function, &mut budget)?;
            }
            Type::Forall(parameters, body) => {
                if parameters
                    .iter()
                    .any(|(_, kind)| matches!(kind, Kind::EffectRow))
                {
                    return Ok(true);
                }
                schedule(&mut work, body, &mut budget)?;
            }
            Type::Bytes
            | Type::String
            | Type::Int
            | Type::Bool
            | Type::Unit
            | Type::Nominal(_)
            | Type::Variable(_)
            | Type::Inference(_) => {}
        }
    }
    Ok(false)
}

pub(crate) struct TypeSourceMessage<'a> {
    pub(crate) message: crate::message::Message<'a>,
    pub(crate) relationship: &'static str,
    pub(crate) fact: Option<(&'static str, &'a str)>,
    pub(crate) fact_kind: &'static str,
    pub(crate) minimum_related: usize,
}

impl TypeReason {
    pub(crate) fn source_message<'a>(
        self,
        expected: Option<&'a str>,
        witness: Option<&'a str>,
    ) -> Option<TypeSourceMessage<'a>> {
        use crate::message::Message;
        let uncovered = witness.map(|value| ("uncovered_value", value));
        let (message, relationship, fact) = match self {
            Self::EffectRowExclusion => (
                Message::effect_row_exclusion(),
                "excluded_effect_requirement",
                None,
            ),
            Self::HookApi => (Message::hook_api(), "hook_api", None),
            Self::MissingHandledEffect => {
                (Message::missing_handled_effect(), "handled_effect", None)
            }
            Self::LocalNominalEscape => {
                (Message::local_nominal_escape(), "escaping_dependency", None)
            }
            Self::ResourceEscape => (Message::resource_escape(), "escaping_dependency", None),
            Self::UnsafeRecursiveInitializer => (
                Message::recursion_initializer(),
                "recursive_initializer",
                None,
            ),
            Self::UnsafeRecursiveRoot => (Message::recursion_root(), "recursive_initializer", None),
            Self::NewtypeRecursiveRepresentation => (
                Message::newtype_representation_cycle(),
                "cycle_closing_occurrence",
                None,
            ),
            Self::CleanupContext => (Message::cleanup_context(), "discard", None),
            Self::InfiniteType => (Message::type_infinite(), "infinite_type", None),
            Self::AmbiguousType => (Message::type_ambiguous(), "ambiguous_type", None),
            Self::UnguardedRecursiveUse => {
                (Message::recursion_unguarded_use(), "recursive_use", None)
            }
            Self::ResumeNotConsumed => (
                Message::continuation_not_consumed(),
                "continuation_usage",
                None,
            ),
            Self::ResumeAlreadyConsumed => (
                Message::continuation_already_consumed(),
                "continuation_usage",
                None,
            ),
            Self::ResumeCapture => (
                Message::continuation_capture(),
                "continuation_capture",
                None,
            ),
            Self::PatternMismatch => (
                Message::pattern_type_mismatch(expected?),
                "pattern",
                Some(("expected_type", expected?)),
            ),
            Self::ConstructorMismatch => {
                (Message::pattern_constructor_payload(), "constructor", None)
            }
            Self::ConstructorOwner => (Message::pattern_constructor_owner(), "pattern", None),
            Self::RefutableBinding => (
                Message::pattern_refutable_binding(witness?),
                "binding_pattern",
                uncovered,
            ),
            Self::RefutableFunctionDomain => (
                Message::pattern_refutable_function(witness?),
                "function_pattern",
                uncovered,
            ),
            Self::RefutableHandlerPattern => (
                Message::pattern_refutable_handler(witness?),
                "handler_pattern",
                uncovered,
            ),
            Self::NonExhaustive => match witness {
                Some(value) => (
                    Message::coverage_non_exhaustive(value),
                    "coverage",
                    uncovered,
                ),
                None => (Message::coverage_empty_match(), "coverage", None),
            },
            Self::RedundantCase => (Message::coverage_redundant_case(), "case", None),
            _ => return None,
        };
        Some(TypeSourceMessage {
            message,
            relationship,
            fact,
            fact_kind: "code",
            minimum_related: match self {
                Self::UnsafeRecursiveInitializer
                | Self::UnsafeRecursiveRoot
                | Self::CleanupContext => 2,
                Self::NewtypeRecursiveRepresentation
                | Self::LocalNominalEscape
                | Self::ResourceEscape => 1,
                _ => 0,
            },
        })
    }

    pub(crate) fn source_related_message(
        self,
        index: usize,
    ) -> Option<(crate::message::Message<'static>, &'static str)> {
        use crate::message::Message;
        Some(match (self, index) {
            (Self::EffectRowExclusion, 0) => {
                (Message::effect_row_exclusion_contract(), "expected_type")
            }
            (Self::LocalNominalEscape, 0) => {
                (Message::local_nominal_scope(), "local_nominal_scope")
            }
            (Self::ResourceEscape, 0) => (Message::resource_acquisition(), "resource_acquisition"),
            (Self::UnsafeRecursiveInitializer | Self::UnsafeRecursiveRoot, 0) => {
                (Message::recursion_group(), "recursive_group")
            }
            (Self::UnsafeRecursiveInitializer | Self::UnsafeRecursiveRoot, 1) => {
                (Message::recursion_member_annotation(), "member_annotation")
            }
            (Self::NewtypeRecursiveRepresentation, _) => {
                (Message::newtype_cycle_member(), "representation_cycle")
            }
            (Self::CleanupContext, 0) => (Message::cleanup_required_action(), "cleanup_action"),
            (Self::CleanupContext, 1) => {
                (Message::cleanup_abandoned_handler(), "abandoned_handler")
            }
            _ => return None,
        })
    }

    pub(crate) fn message<'a>(
        self,
        expected: &'a str,
        found: &'a str,
    ) -> Option<crate::message::Message<'a>> {
        use crate::message::Message;
        Some(match self {
            Self::BindingInitializer => Message::binding_initializer(expected, found),
            Self::DefinitionResult => Message::type_definition_result(expected, found),
            Self::OperatorOperand => Message::type_operator_operand(found),
            Self::Argument => Message::type_argument(expected, found),
            Self::PolymorphicRecursion => Message::type_polymorphic_recursion(expected, found),
            Self::NotApplicable => Message::type_not_applicable(found),
            Self::EquationInterfaceNotFunction => Message::type_equation_signature(found),
            _ => return None,
        })
    }

    pub(crate) fn primary_message(
        self,
        found: &str,
    ) -> Option<(crate::message::Message<'_>, &'static str)> {
        use crate::message::Message;
        if self == Self::BindingInitializer {
            return Some((Message::initializer(found), "initializer"));
        }
        let relationship = match self {
            Self::DefinitionResult => "definition_result",
            Self::OperatorOperand => "operator_operand",
            Self::Argument => "argument",
            Self::PolymorphicRecursion => "recursive_argument",
            Self::NotApplicable => "application_function",
            Self::EquationInterfaceNotFunction => "equation_signature",
            _ => return None,
        };
        Some((Message::type_found(found), relationship))
    }

    pub(crate) fn related_message(
        self,
        index: usize,
        expected: &str,
    ) -> Option<(crate::message::Message<'_>, &'static str, Option<&str>)> {
        use crate::message::Message;
        Some(match (self, index) {
            (Self::BindingInitializer, 0) => (
                Message::binding_annotation(expected),
                "binding_annotation",
                Some(expected),
            ),
            (Self::DefinitionResult, 0) => (
                Message::type_result_annotation(expected),
                "result_annotation",
                Some(expected),
            ),
            (Self::OperatorOperand, 0) => (
                Message::type_operator_requirement(),
                "operator_requirement",
                Some(expected),
            ),
            (Self::Argument, 0) => (
                Message::type_function_domain(expected),
                "function_domain",
                Some(expected),
            ),
            (Self::Argument, 1) | (Self::NotApplicable, 0) => {
                (Message::type_application(), "application", None)
            }
            (Self::EquationInterfaceNotFunction, 0) => {
                (Message::type_equation_head(), "equation_head", None)
            }
            _ => return None,
        })
    }
}

impl fmt::Display for TypeReason {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::OperatorOperand => formatter.write_str("type.operator-operand"),
            Self::FunctionNeedsContext => formatter.write_str("type.function-needs-context"),
            Self::NotApplicable => formatter.write_str("type.not-applicable"),
            Self::Argument => formatter.write_str("type.argument"),
            Self::BindingInitializer => formatter.write_str("type.binding-initializer"),
            Self::DefinitionResult => formatter.write_str("type.definition-result"),
            Self::EquationInterfaceNotFunction => {
                formatter.write_str("type.equation-interface-not-function")
            }
            Self::UnsafeRecursiveInitializer => formatter.write_str("recursion.unsafe-initializer"),
            Self::UnsafeRecursiveRoot => formatter.write_str("recursion.unsafe-root"),
            Self::UnguardedRecursiveUse => formatter.write_str("recursion.unguarded-use"),
            Self::ConstructorMismatch => formatter.write_str("pattern.constructor-payload"),
            Self::ConstructorOwner => formatter.write_str("pattern.constructor-owner"),
            Self::PatternMismatch => formatter.write_str("pattern.type-mismatch"),
            Self::EquationArity => formatter.write_str("equation.arity"),
            Self::RefutableBinding => formatter.write_str("pattern.refutable-binding"),
            Self::RefutableFunctionDomain => {
                formatter.write_str("pattern.refutable-function-domain")
            }
            Self::NonExhaustive => formatter.write_str("coverage.non-exhaustive"),
            Self::RedundantCase => formatter.write_str("coverage.redundant-case"),
            Self::InfiniteType => formatter.write_str("type.infinite"),
            Self::AmbiguousType => formatter.write_str("type.ambiguous"),
            Self::PolymorphicRecursion => formatter.write_str("type.polymorphic-recursion"),
            Self::NewtypeRecursiveRepresentation => {
                formatter.write_str("newtype.recursive-representation")
            }
            Self::LocalNominalEscape => formatter.write_str("type.local-nominal-escape"),
            Self::ResourceEscape => formatter.write_str("type.resource-escape"),
            Self::AmbiguousEffectRow => formatter.write_str("effect.row-union-ambiguous"),
            Self::EffectRowExclusion => formatter.write_str("effect.row-exclusion"),
            Self::MissingHandledEffect => formatter.write_str("effect.handler-missing-input"),
            Self::HookApi => formatter.write_str("type.hook-api"),
            Self::HandlerCoverage => formatter.write_str("effect.handler-coverage"),
            Self::RefutableHandlerPattern => {
                formatter.write_str("effect.handler-refutable-pattern")
            }
            Self::ResumeOutsideClause => formatter.write_str("effect.resume-outside-clause"),
            Self::ResumeNotConsumed => formatter.write_str("effect.resume-not-consumed"),
            Self::ResumeAlreadyConsumed => formatter.write_str("effect.resume-already-consumed"),
            Self::ResumeCapture => formatter.write_str("effect.resume-capture"),
            Self::DiscardUnsafe => formatter.write_str("effect.discard-unsafe"),
            Self::CleanupContext => formatter.write_str("effect.cleanup-context"),
        }
    }
}

/// A structural mismatch produced by the general checking rule.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TypeMismatch {
    span: Span,
    expected: Box<Type>,
    found: Box<Type>,
    expected_display: String,
    found_display: String,
}

impl TypeMismatch {
    pub(crate) fn display_types(&self) -> (&str, &str) {
        (&self.expected_display, &self.found_display)
    }

    pub(crate) fn message(&self) -> crate::message::Message<'_> {
        crate::message::Message::type_mismatch(&self.expected_display, &self.found_display)
    }

    /// Returns the expression that did not check.
    #[must_use]
    pub const fn span(&self) -> Span {
        self.span
    }

    /// Returns the required structural type.
    #[must_use]
    pub const fn expected(&self) -> &Type {
        &self.expected
    }

    /// Returns the synthesized structural type.
    #[must_use]
    pub const fn found(&self) -> &Type {
        &self.found
    }
}

impl Drop for TypeMismatch {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(self.expected.as_mut(), Type::Unit));
        discard_type_iteratively(std::mem::replace(self.found.as_mut(), Type::Unit));
    }
}

/// A compiler-owned elaboration failure, distinct from rejected Ash source.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ElaborationFailure {
    /// Core construction could not represent the requested node.
    Core(BuildError),
    /// The explicit elaboration work stack lost an invariant.
    InvalidState,
    /// Kind validation failed during elaboration, retaining its original cause.
    Kind {
        /// Original kind-checking cause and source location.
        context: crate::kind::KindFailureContext,
        /// The elaboration use that exposed the failure, when available.
        span: Option<Span>,
    },
    /// Effect syntax reached a checkpoint that still retains only pure Core.
    EffectCoreUnavailable,
    /// Controlled foreign calls await provider-phase admission.
    ForeignPrivilegeUnavailable,
    /// Pattern coverage exceeded its deterministic compiler resource budget.
    CoverageResourceExhausted(UsefulnessError),
    /// Cumulative inference and type construction exceeded its work budget.
    TypeResourceExhausted,
    /// Graph-wide interface and constraint processing exceeded its work budget.
    ConstraintResourceExhausted,
}

impl ElaborationFailure {
    pub(crate) fn diagnostic_message(
        &self,
    ) -> Option<(
        crate::message::Message<'static>,
        &'static str,
        &'static str,
        &'static str,
    )> {
        use crate::message::Message;
        Some(match self {
            Self::Core(cause) => {
                let (message, cause) = cause.diagnostic_message();
                (message, "cause", "core-build-failure", cause)
            }
            Self::CoverageResourceExhausted(cause) => {
                let (message, resource) = cause.diagnostic_message();
                (message, "resource", "resource", resource)
            }
            Self::TypeResourceExhausted => (
                Message::compiler_type_resources(),
                "resource",
                "resource",
                "type-work",
            ),
            Self::ConstraintResourceExhausted => (
                Message::compiler_constraint_resources(),
                "resource",
                "resource",
                "constraint-work",
            ),
            Self::ForeignPrivilegeUnavailable => (
                Message::foreign_privilege_unavailable(),
                "cause",
                "elaboration-failure",
                "foreign-privilege-unavailable",
            ),
            Self::EffectCoreUnavailable => (
                Message::effect_core_unavailable(),
                "cause",
                "elaboration-failure",
                "effect-core-unavailable",
            ),
            Self::InvalidState => (
                Message::elaboration_invalid_state(),
                "cause",
                "elaboration-failure",
                "invalid-state",
            ),
            Self::Kind { context, .. } => (
                context.message(),
                "kind_cause",
                "kind-internal-cause",
                context.name(),
            ),
        })
    }

    /// Returns the stable reason code owned by this elaboration failure.
    #[must_use]
    pub const fn reason_code(&self) -> &'static str {
        match self {
            Self::Core(_) => "internal.core-build",
            Self::InvalidState | Self::Kind { .. } => "type.internal",
            Self::EffectCoreUnavailable => "effect.core-unavailable",
            Self::ForeignPrivilegeUnavailable => "foreign.privilege-unavailable",
            Self::CoverageResourceExhausted(_) => "internal.resource.coverage",
            Self::TypeResourceExhausted => "internal.resource.type-work",
            Self::ConstraintResourceExhausted => "internal.resource.constraint-work",
        }
    }
}

impl fmt::Display for ElaborationFailure {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Core(error) => write!(formatter, "typed Core construction failed: {error}"),
            Self::InvalidState | Self::Kind { .. } => {
                formatter.write_str("typed elaboration state is inconsistent")
            }
            Self::ForeignPrivilegeUnavailable => {
                formatter.write_str("controlled foreign calls require provider-phase admission")
            }
            Self::EffectCoreUnavailable => {
                formatter.write_str("effect syntax requires the effect Core checkpoint")
            }
            Self::CoverageResourceExhausted(_) => {
                formatter.write_str("pattern coverage resource limit exceeded")
            }
            Self::TypeResourceExhausted => formatter.write_str("type work resource limit exceeded"),
            Self::ConstraintResourceExhausted => {
                formatter.write_str("interface and constraint work resource limit exceeded")
            }
        }
    }
}

impl Error for ElaborationFailure {}

impl From<BuildError> for ElaborationFailure {
    fn from(error: BuildError) -> Self {
        if error == BuildError::TypeWorkExceeded {
            Self::TypeResourceExhausted
        } else {
            Self::Core(error)
        }
    }
}

/// A source type diagnostic with phase-owned context for presentation.
/// Common fields remain available through dereferencing; localized reporting
/// must retain this owner rather than copying only the common diagnostic.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TypeDiagnostic {
    diagnostic: Diagnostic<TypeReason>,
    context: TypeDiagnosticContext,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TypeDiagnosticContext {
    Plain,
    FunctionNeedsContext(Option<SynthesisCause>),
    EquationArity(EquationArityCause),
    HandlerCoverage(HandlerCoverageCause),
    CompletionOutside(CompletionOperation),
    EffectRow(EffectRowCause),
    DiscardUnsafe(Option<crate::core::capture::CompletionOwner>),
    PolymorphicRecursion([Option<RecursionLabel>; 2]),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RecursionLabel {
    Function,
    Application,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum EffectRowCause {
    Union,
    InfiniteFunction,
    FunctionMismatch,
    FunctionOutsideDeclared,
    CleanupInference,
    CleanupOutsideExpected,
    DiscardCleanup,
    CleanupRequirement,
    Removal,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HandlerCoverageCause {
    ArgumentCount,
    OperationOwner,
    ClauseCount,
    OperationIndex,
    DuplicateOperation,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CompletionOperation {
    Resume,
    Discard,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum EquationArityCause {
    PatternCount,
    DeclaredArrows,
}

impl From<Diagnostic<TypeReason>> for TypeDiagnostic {
    fn from(diagnostic: Diagnostic<TypeReason>) -> Self {
        Self {
            diagnostic,
            context: TypeDiagnosticContext::Plain,
        }
    }
}

impl std::ops::Deref for TypeDiagnostic {
    type Target = Diagnostic<TypeReason>;
    fn deref(&self) -> &Self::Target {
        &self.diagnostic
    }
}

impl std::ops::DerefMut for TypeDiagnostic {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.diagnostic
    }
}

impl TypeDiagnostic {
    pub(crate) fn comparison_minimum_related(&self) -> usize {
        match self.context {
            TypeDiagnosticContext::PolymorphicRecursion(labels) => labels.iter().flatten().count(),
            _ => 1,
        }
    }

    pub(crate) fn comparison_related_message<'a>(
        &self,
        index: usize,
        expected: &'a str,
    ) -> Option<(crate::message::Message<'a>, &'static str, Option<&'a str>)> {
        if self.reason != TypeReason::PolymorphicRecursion {
            return self.reason.related_message(index, expected);
        }
        let TypeDiagnosticContext::PolymorphicRecursion(labels) = self.context else {
            return None;
        };
        use crate::message::Message;
        Some(match labels.get(index).copied().flatten()? {
            RecursionLabel::Function => (
                Message::recursive_function(),
                "recursive_function",
                Some(expected),
            ),
            RecursionLabel::Application => (Message::recursive_application(), "application", None),
        })
    }

    pub(crate) fn source_message(&self) -> Option<TypeSourceMessage<'_>> {
        if self.reason == TypeReason::DiscardUnsafe {
            let TypeDiagnosticContext::DiscardUnsafe(owner) = self.context else {
                return None;
            };
            use crate::{core::capture::CompletionOwner, message::Message};
            let (message, kind) = match owner {
                None => (Message::discard_unknown(), "unknown"),
                Some(CompletionOwner::Clause(_)) => (Message::discard_clause(), "clause"),
                Some(CompletionOwner::Cleanup(_)) => (Message::discard_cleanup(), "cleanup"),
            };
            return Some(TypeSourceMessage {
                message,
                relationship: "discard",
                fact: Some(("completion_owner", kind)),
                fact_kind: "completion-owner",
                minimum_related: 1 + usize::from(owner.is_some()),
            });
        }
        if self.reason == TypeReason::AmbiguousEffectRow {
            let TypeDiagnosticContext::EffectRow(cause) = self.context else {
                return None;
            };
            let (message, failure) = match cause {
                EffectRowCause::Union => (crate::message::Message::effect_row_union(), "union"),
                EffectRowCause::CleanupRequirement => (
                    crate::message::Message::effect_row_cleanup_requirement(),
                    "cleanup-requirement",
                ),
                EffectRowCause::Removal => {
                    (crate::message::Message::effect_row_removal(), "removal")
                }
                EffectRowCause::InfiniteFunction => (
                    crate::message::Message::effect_row_infinite_function(),
                    "infinite-function",
                ),
                EffectRowCause::FunctionMismatch => (
                    crate::message::Message::effect_row_function_mismatch(),
                    "function-mismatch",
                ),
                EffectRowCause::FunctionOutsideDeclared => (
                    crate::message::Message::effect_row_function_outside_declared(),
                    "function-outside-declared",
                ),
                EffectRowCause::CleanupInference => (
                    crate::message::Message::effect_row_cleanup_inference(),
                    "cleanup-inference",
                ),
                EffectRowCause::CleanupOutsideExpected => (
                    crate::message::Message::effect_row_cleanup_outside_expected(),
                    "cleanup-outside-expected",
                ),
                EffectRowCause::DiscardCleanup => (
                    crate::message::Message::effect_row_discard_cleanup(),
                    "discard-cleanup",
                ),
            };
            return Some(TypeSourceMessage {
                message,
                relationship: "effect_row",
                fact: Some(("row_failure", failure)),
                fact_kind: "effect-row-failure",
                minimum_related: 0,
            });
        }
        if self.reason == TypeReason::HandlerCoverage {
            let TypeDiagnosticContext::HandlerCoverage(cause) = self.context else {
                return None;
            };
            use crate::message::Message;
            let (message, failure) = match cause {
                HandlerCoverageCause::ArgumentCount => {
                    (Message::handler_argument_count(), "argument-count")
                }
                HandlerCoverageCause::OperationOwner => {
                    (Message::handler_operation_owner(), "operation-owner")
                }
                HandlerCoverageCause::ClauseCount => {
                    (Message::handler_clause_count(), "clause-count")
                }
                HandlerCoverageCause::OperationIndex => {
                    (Message::handler_operation_index(), "operation-index")
                }
                HandlerCoverageCause::DuplicateOperation => (
                    Message::handler_duplicate_operation(),
                    "duplicate-operation",
                ),
            };
            return Some(TypeSourceMessage {
                message,
                relationship: "handler_coverage",
                fact: Some(("coverage_failure", failure)),
                fact_kind: "handler-coverage-failure",
                minimum_related: 0,
            });
        }
        if self.reason == TypeReason::ResumeOutsideClause {
            let TypeDiagnosticContext::CompletionOutside(operation) = self.context else {
                return None;
            };
            let keyword = match operation {
                CompletionOperation::Resume => "resume",
                CompletionOperation::Discard => "discard",
            };
            return Some(TypeSourceMessage {
                message: crate::message::Message::resolve_continuation_outside(keyword),
                relationship: "continuation_use",
                fact: Some(("operation", keyword)),
                fact_kind: "keyword",
                minimum_related: 0,
            });
        }
        if self.reason == TypeReason::EquationArity {
            let TypeDiagnosticContext::EquationArity(cause) = self.context else {
                return None;
            };
            let (message, requirement) = match cause {
                EquationArityCause::PatternCount => (
                    crate::message::Message::equation_pattern_count(),
                    "pattern-count",
                ),
                EquationArityCause::DeclaredArrows => (
                    crate::message::Message::equation_declared_arrows(),
                    "declared-arrows",
                ),
            };
            return Some(TypeSourceMessage {
                message,
                relationship: "equation_group",
                fact: Some(("arity_requirement", requirement)),
                fact_kind: "equation-arity-requirement",
                minimum_related: 0,
            });
        }
        if self.reason != TypeReason::FunctionNeedsContext {
            return self
                .reason
                .source_message(self.expected.as_deref(), self.found.as_deref());
        }
        let TypeDiagnosticContext::FunctionNeedsContext(cause) = self.context else {
            return None;
        };
        let context = match cause {
            None => "expected-function",
            Some(SynthesisCause::Binding(_) | SynthesisCause::NestedBinding(_)) => "binding",
            Some(SynthesisCause::ProgramResult(_)) => "program-result",
            Some(SynthesisCause::Application { .. }) => "application",
            Some(SynthesisCause::Operator(_)) => "operator",
        };
        Some(TypeSourceMessage {
            message: crate::message::Message::function_needs_context(),
            relationship: "anonymous_function",
            fact: Some(("required_context", context)),
            fact_kind: "synthesis-context",
            minimum_related: usize::from(cause.is_some()),
        })
    }

    pub(crate) fn source_related_message(
        &self,
        index: usize,
    ) -> Option<(crate::message::Message<'static>, &'static str)> {
        if self.reason == TypeReason::DiscardUnsafe {
            let TypeDiagnosticContext::DiscardUnsafe(owner) = self.context else {
                return None;
            };
            use crate::{core::capture::CompletionOwner, message::Message};
            return match (index, owner) {
                (0, _) => Some((Message::discard_request(), "capturing_request")),
                (1, Some(CompletionOwner::Clause(_))) => {
                    Some((Message::discard_clause_owner(), "completion_clause"))
                }
                (1, Some(CompletionOwner::Cleanup(_))) => {
                    Some((Message::discard_cleanup_owner(), "cleanup_action"))
                }
                _ => None,
            };
        }
        if self.reason != TypeReason::FunctionNeedsContext {
            return self.reason.source_related_message(index);
        }
        if index != 0 {
            return None;
        }
        let TypeDiagnosticContext::FunctionNeedsContext(Some(cause)) = self.context else {
            return None;
        };
        use crate::message::Message;
        Some(match cause {
            SynthesisCause::Binding(_) | SynthesisCause::NestedBinding(_) => {
                (Message::function_context_binding(), "binding")
            }
            SynthesisCause::ProgramResult(_) => {
                (Message::function_context_result(), "program_result")
            }
            SynthesisCause::Application { .. } => {
                (Message::function_context_application(), "application")
            }
            SynthesisCause::Operator(_) => (Message::function_context_operator(), "operator"),
        })
    }
}

/// A source diagnostic, general checking mismatch, or compiler failure.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum TypeError {
    /// A categorized Ash source rejection.
    Source(Box<TypeDiagnostic>),
    /// A categorized interface or implementation source rejection.
    Interface(Box<crate::interface::InterfaceDiagnostic>),
    /// The general checking rule found structurally unequal types.
    Mismatch(TypeMismatch),
    /// Typed elaboration could not preserve its compiler invariants.
    Internal(ElaborationFailure),
}

impl TypeError {
    fn source(diagnostic: Diagnostic<TypeReason>) -> Self {
        Self::Source(Box::new(diagnostic.into()))
    }

    fn interface(diagnostic: Diagnostic<InterfaceReason>) -> Self {
        Self::Interface(Box::new(diagnostic.into()))
    }

    fn interface_arity(
        diagnostic: Diagnostic<InterfaceReason>,
        expected: usize,
        found: usize,
    ) -> Self {
        Self::Interface(Box::new(
            crate::interface::InterfaceDiagnostic::with_argument_counts(
                diagnostic, expected, found,
            ),
        ))
    }
}

impl fmt::Display for TypeError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Source(diagnostic) => formatter.write_str(&diagnostic.render_plain()),
            Self::Interface(diagnostic) => formatter.write_str(&diagnostic.render_plain()),
            Self::Mismatch(mismatch) => write!(
                formatter,
                "type mismatch: expected {}, found {}",
                mismatch.expected_display, mismatch.found_display
            ),
            Self::Internal(failure) => failure.fmt(formatter),
        }
    }
}

impl Error for TypeError {}

impl From<BuildError> for TypeError {
    fn from(error: BuildError) -> Self {
        Self::Internal(error.into())
    }
}

impl From<UsefulnessError> for TypeError {
    fn from(cause: UsefulnessError) -> Self {
        Self::Internal(ElaborationFailure::CoverageResourceExhausted(cause))
    }
}

/// Monomorphic types assigned to resolved binder identities.
#[derive(Debug, Default, Eq, PartialEq)]
pub struct TypeContext {
    binders: HashMap<BinderId, TypeFact>,
}

#[cfg(test)]
thread_local! {
    static TYPE_CONTEXT_CLONES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

impl Clone for TypeContext {
    fn clone(&self) -> Self {
        #[cfg(test)]
        TYPE_CONTEXT_CLONES.with(|clones| clones.set(clones.get() + 1));
        Self {
            binders: self.binders.clone(),
        }
    }
}

impl Drop for TypeContext {
    fn drop(&mut self) {
        for (_, mut fact) in self.binders.drain() {
            discard_type_iteratively(std::mem::replace(&mut fact.ty, Type::Unit));
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct TypeFact {
    ty: Type,
    provenance: TypeProvenance,
    quantified: Box<[(TypeVariableId, Kind)]>,
}

type KindedTypeParameters = Box<[(TypeVariableId, Kind)]>;

fn discard_type_fact(mut fact: TypeFact) {
    discard_type_iteratively(std::mem::replace(&mut fact.ty, Type::Unit));
}

#[derive(Debug)]
struct LoweredInterfaceMethod {
    interface: InterfaceId,
    parameters: Box<[TypeVariableId]>,
    type_parameters: Box<[(TypeVariableId, Kind)]>,
    value_type: Type,
    declaration_span: Span,
}

#[derive(Debug)]
struct LoweredInterface {
    methods: Box<[MethodId]>,
    determination: Option<Box<[usize]>>,
}

impl Drop for LoweredInterfaceMethod {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(&mut self.value_type, Type::Unit));
    }
}

#[derive(Debug)]
struct LoweredRequirementMethod {
    method: MethodId,
    application: InterfaceApplication,
    ty: Type,
}

impl Drop for LoweredRequirementMethod {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(&mut self.ty, Type::Unit));
    }
}

#[derive(Debug)]
struct LoweredRequirement {
    owner: MethodEvidenceOwner,
    id: RequirementId,
    methods: Box<[LoweredRequirementMethod]>,
}

#[derive(Debug)]
struct LoweredScheme {
    source_type_parameters: Option<Box<[(TypeVariableId, Kind)]>>,
    type_parameters: Box<[(TypeVariableId, Kind)]>,
    requirements: Box<[LoweredRequirement]>,
    value_type: Type,
    core_scheme: Type,
}

impl LoweredScheme {
    fn source_binder_parameters(&self) -> Option<&[(TypeVariableId, Kind)]> {
        self.source_type_parameters.as_deref()
    }

    fn binder_parameters(&self) -> &[(TypeVariableId, Kind)] {
        &self.type_parameters
    }
}

impl Drop for LoweredScheme {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(&mut self.value_type, Type::Unit));
        discard_type_iteratively(std::mem::replace(&mut self.core_scheme, Type::Unit));
    }
}

#[derive(Debug)]
struct LoweredImplementationMethod {
    binder: BinderId,
    head_type_parameter_count: usize,
    application: InterfaceApplication,
    scheme: LoweredScheme,
    span: Span,
}

#[derive(Debug)]
struct ActiveEvidenceBinder {
    binder: BinderId,
    application: InterfaceApplication,
    ty: Type,
}

impl Drop for ActiveEvidenceBinder {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(&mut self.ty, Type::Unit));
    }
}

#[derive(Debug)]
struct LoweredEvidenceMethod {
    method: MethodId,
    node: NodeId,
    ty: Type,
    producer: PolymorphicEvidenceProducer,
    adapter_application: Option<InterfaceApplication>,
}

#[derive(Clone, Copy, Debug)]
enum PolymorphicEvidenceProducer {
    Lexical {
        source: crate::interface::LexicalEvidenceId,
        selection_node: crate::interface::EvidenceNodeId,
        binder: BinderId,
    },
    Abstract {
        requirement: RequirementId,
        selection_node: crate::interface::EvidenceNodeId,
        binder: BinderId,
    },
    Adapter {
        implementation: ImplMethodId,
        selection_node: crate::interface::EvidenceNodeId,
    },
}

impl Drop for LoweredEvidenceMethod {
    fn drop(&mut self) {
        discard_type_iteratively(std::mem::replace(&mut self.ty, Type::Unit));
    }
}

struct ScopedEvidenceBinder {
    owner: MethodEvidenceOwner,
    requirement: RequirementId,
    method: MethodId,
    application: InterfaceApplication,
    binder: TypedBinder,
}

#[derive(Debug)]
struct EvidenceLowering {
    lexical_binders: HashMap<(crate::interface::LexicalEvidenceId, MethodId), ActiveEvidenceBinder>,
    interfaces: HashMap<InterfaceId, LoweredInterface>,
    interface_methods: HashMap<MethodId, LoweredInterfaceMethod>,
    global_schemes: HashMap<BinderId, LoweredScheme>,
    implementation_methods: HashMap<ImplMethodId, LoweredImplementationMethod>,
    active_binders: HashMap<(RequirementId, MethodId), ActiveEvidenceBinder>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum TypeProvenance {
    Built {
        nodes: Arc<[TypeProvenanceNode]>,
        root: usize,
    },
    Resolved(ResolvedTypeProvenance),
    Function {
        span: Option<Span>,
        parts: Arc<(TypeProvenance, TypeProvenance)>,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TypeProvenanceNode {
    Fact(Option<Span>),
    Application {
        span: Option<Span>,
        function: usize,
        argument: usize,
    },
    Function {
        span: Option<Span>,
        domain: usize,
        codomain: usize,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProvenancedType {
    ty: Type,
    provenance: TypeProvenance,
}

impl TypeProvenance {
    fn atom(span: Option<Span>) -> Self {
        Self::Built {
            nodes: Arc::from([TypeProvenanceNode::Fact(span)]),
            root: 0,
        }
    }

    fn unknown(ty: &Type) -> Self {
        Self::uniform(ty, None)
    }

    fn at_span(ty: &Type, span: Span) -> Self {
        Self::uniform(ty, Some(span))
    }

    fn uniform(ty: &Type, span: Option<Span>) -> Self {
        let mut tasks = vec![(ty, false)];
        let mut nodes = Vec::new();
        let mut roots = Vec::new();
        while let Some((current, visited)) = tasks.pop() {
            match current {
                Type::Function(domain, codomain) if !visited => {
                    tasks.push((current, true));
                    tasks.push((codomain, false));
                    tasks.push((domain, false));
                }
                Type::Function(_, _) => {
                    let codomain = roots.pop().unwrap_or(0);
                    let domain = roots.pop().unwrap_or(0);
                    nodes.push(TypeProvenanceNode::Function {
                        span,
                        domain,
                        codomain,
                    });
                    roots.push(nodes.len() - 1);
                }
                Type::EffectfulFunction(domain, codomain) if !visited => {
                    tasks.push((current, true));
                    tasks.push((codomain.value(), false));
                    tasks.push((domain, false));
                }
                Type::EffectfulFunction(_, _) => {
                    let codomain = roots.pop().unwrap_or(0);
                    let domain = roots.pop().unwrap_or(0);
                    nodes.push(TypeProvenanceNode::Function {
                        span,
                        domain,
                        codomain,
                    });
                    roots.push(nodes.len() - 1);
                }
                Type::Application(function, argument) if !visited => {
                    tasks.push((current, true));
                    tasks.push((argument, false));
                    tasks.push((function, false));
                }
                Type::Application(_, _) => {
                    let argument = roots.pop().unwrap_or(0);
                    let function = roots.pop().unwrap_or(0);
                    nodes.push(TypeProvenanceNode::Application {
                        span,
                        function,
                        argument,
                    });
                    roots.push(nodes.len() - 1);
                }
                Type::Bytes
                | Type::String
                | Type::Int
                | Type::Bool
                | Type::Unit
                | Type::Tuple(_)
                | Type::Nominal(_)
                | Type::Variable(_)
                | Type::Inference(_)
                | Type::Forall(_, _)
                | Type::ResourceApply(_, _) => {
                    nodes.push(TypeProvenanceNode::Fact(span));
                    roots.push(nodes.len() - 1);
                }
            }
        }
        let root = roots.pop().unwrap_or(0);
        Self::Built {
            nodes: nodes.into(),
            root,
        }
    }

    fn span(&self) -> Option<Span> {
        match self {
            Self::Built { nodes, root } => match nodes.get(*root) {
                Some(
                    TypeProvenanceNode::Fact(span)
                    | TypeProvenanceNode::Application { span, .. }
                    | TypeProvenanceNode::Function { span, .. },
                ) => *span,
                None => None,
            },
            Self::Resolved(resolved) => resolved.span(),
            Self::Function { span, .. } => *span,
        }
    }

    fn aligns(&self, ty: &Type) -> bool {
        #[derive(Clone, Copy)]
        enum Cursor<'a> {
            Built(&'a [TypeProvenanceNode], usize),
            Resolved(&'a ResolvedTypeProvenance, usize),
            Provenance(&'a TypeProvenance),
        }
        enum Value<'a> {
            Type(&'a Type),
            Argument(&'a crate::types::KindedArgument),
            Row(&'a EffectRow),
        }
        let mut work = vec![(Value::Type(ty), Cursor::Provenance(self))];
        while let Some((value, cursor)) = work.pop() {
            let value = match value {
                Value::Argument(crate::types::KindedArgument::TypeArg(ty)) => Value::Type(ty),
                Value::Argument(crate::types::KindedArgument::RowArg(row)) => Value::Row(row),
                other => other,
            };
            let current = match value {
                Value::Type(ty) => ty,
                Value::Row(row) => {
                    let Cursor::Resolved(resolved, node) = cursor else {
                        return false;
                    };
                    let Some(ResolvedTypeProvenanceNode::Row { argument_roots, .. }) =
                        resolved.nodes().get(node)
                    else {
                        return false;
                    };
                    let arguments = row
                        .known()
                        .iter()
                        .chain(row.tail().into_iter().flat_map(|tail| tail.lacks()))
                        .flat_map(|instance| instance.arguments());
                    if arguments.clone().count() != argument_roots.len() {
                        return false;
                    }
                    work.extend(arguments.zip(argument_roots.iter().copied()).map(
                        |(argument, root)| {
                            (Value::Argument(argument), Cursor::Resolved(resolved, root))
                        },
                    ));
                    continue;
                }
                Value::Argument(_) => unreachable!(),
            };
            let cursor = match cursor {
                Cursor::Provenance(Self::Built { nodes, root }) => Cursor::Built(nodes, *root),
                Cursor::Provenance(Self::Resolved(resolved)) => {
                    Cursor::Resolved(resolved, resolved.root())
                }
                Cursor::Provenance(Self::Function { parts, .. }) => {
                    let Some(function) = current.function_view() else {
                        return false;
                    };
                    work.push((Value::Type(function.value()), Cursor::Provenance(&parts.1)));
                    work.push((Value::Type(function.domain()), Cursor::Provenance(&parts.0)));
                    continue;
                }
                cursor => cursor,
            };
            match cursor {
                Cursor::Built(nodes, node) => match (current, nodes.get(node)) {
                    (
                        Type::Bytes
                        | Type::String
                        | Type::Int
                        | Type::Bool
                        | Type::Unit
                        | Type::Tuple(_)
                        | Type::Nominal(_)
                        | Type::Variable(_)
                        | Type::Inference(_)
                        | Type::Forall(_, _)
                        | Type::ResourceApply(_, _),
                        Some(TypeProvenanceNode::Fact(_)),
                    ) => {}
                    (
                        Type::Application(function, argument),
                        Some(TypeProvenanceNode::Application {
                            function: function_node,
                            argument: argument_node,
                            ..
                        }),
                    ) => {
                        work.push((Value::Type(argument), Cursor::Built(nodes, *argument_node)));
                        work.push((Value::Type(function), Cursor::Built(nodes, *function_node)));
                    }
                    (
                        Type::Function(_, _) | Type::EffectfulFunction(_, _),
                        Some(TypeProvenanceNode::Function {
                            domain, codomain, ..
                        }),
                    ) => {
                        let function = current.function_view().expect("physical function");
                        work.push((
                            Value::Type(function.value()),
                            Cursor::Built(nodes, *codomain),
                        ));
                        work.push((
                            Value::Type(function.domain()),
                            Cursor::Built(nodes, *domain),
                        ));
                    }
                    _ => return false,
                },
                Cursor::Resolved(resolved, node) => {
                    match (current, resolved.nodes().get(node)) {
                        (
                            Type::Function(domain, codomain),
                            Some(ResolvedTypeProvenanceNode::Function {
                                domain: domain_node,
                                codomain: codomain_node,
                                effect_arguments,
                                ..
                            }),
                        ) if effect_arguments.is_empty() => {
                            work.push((
                                Value::Type(codomain),
                                Cursor::Resolved(resolved, *codomain_node),
                            ));
                            work.push((
                                Value::Type(domain),
                                Cursor::Resolved(resolved, *domain_node),
                            ));
                        }
                        (
                            Type::EffectfulFunction(domain, codomain),
                            Some(ResolvedTypeProvenanceNode::Function {
                                domain: domain_node,
                                codomain: codomain_node,
                                effect_arguments,
                                ..
                            }),
                        ) if codomain.effect_argument_count() == effect_arguments.len() => {
                            work.extend(
                                codomain
                                    .effect_arguments()
                                    .zip(effect_arguments.iter().copied())
                                    .map(|(argument, root)| {
                                        (
                                            Value::Argument(argument),
                                            Cursor::Resolved(resolved, root),
                                        )
                                    }),
                            );
                            work.push((
                                Value::Type(codomain.value()),
                                Cursor::Resolved(resolved, *codomain_node),
                            ));
                            work.push((
                                Value::Type(domain),
                                Cursor::Resolved(resolved, *domain_node),
                            ));
                        }
                        (
                            Type::ResourceApply(resource, arguments),
                            Some(ResolvedTypeProvenanceNode::Resource {
                                resource: source,
                                arguments: roots,
                                ..
                            }),
                        ) if resource == source && arguments.len() == roots.len() => {
                            work.extend(arguments.iter().zip(roots.iter().copied()).map(
                                |(argument, root)| {
                                    (Value::Argument(argument), Cursor::Resolved(resolved, root))
                                },
                            ));
                        }
                        (
                            Type::Application(function, argument),
                            Some(ResolvedTypeProvenanceNode::Application {
                                function: function_node,
                                argument: argument_node,
                                ..
                            }),
                        ) => {
                            work.push((
                                Value::Type(argument),
                                Cursor::Resolved(resolved, *argument_node),
                            ));
                            work.push((
                                Value::Type(function),
                                Cursor::Resolved(resolved, *function_node),
                            ));
                        }
                        (
                            Type::Bytes
                            | Type::String
                            | Type::Int
                            | Type::Bool
                            | Type::Unit
                            | Type::Nominal(_)
                            | Type::Variable(_)
                            | Type::Inference(_),
                            Some(ResolvedTypeProvenanceNode::Fact(_)),
                        ) => {}
                        (
                            Type::Tuple(elements),
                            Some(ResolvedTypeProvenanceNode::Tuple {
                                elements: roots, ..
                            }),
                        ) if elements.len() == roots.len() => {
                            work.extend(elements.iter().zip(roots.iter().copied()).map(
                                |(ty, root)| (Value::Type(ty), Cursor::Resolved(resolved, root)),
                            ));
                        }
                        _ => return false,
                    }
                }
                Cursor::Provenance(_) => unreachable!(),
            }
        }
        true
    }

    fn child(&self, node: usize) -> Result<Self, TypeError> {
        match self {
            Self::Built { nodes, .. } if nodes.get(node).is_some() => Ok(Self::Built {
                nodes: Arc::clone(nodes),
                root: node,
            }),
            _ => Err(invalid_state()),
        }
    }

    fn function_parts(&self, ty: &Type) -> Result<(Self, Self), TypeError> {
        if ty.function_view().is_none() {
            return Err(invalid_state());
        }
        match self {
            Self::Built { nodes, root } => {
                let Some(TypeProvenanceNode::Function {
                    domain, codomain, ..
                }) = nodes.get(*root)
                else {
                    return Err(invalid_state());
                };
                Ok((self.child(*domain)?, self.child(*codomain)?))
            }
            Self::Resolved(resolved) => resolved
                .function_parts()
                .map(|(domain, codomain)| (Self::Resolved(domain), Self::Resolved(codomain)))
                .ok_or_else(invalid_state),
            Self::Function { parts, .. } => Ok((parts.0.clone(), parts.1.clone())),
        }
    }
}

impl ProvenancedType {
    #[cfg(test)]
    fn unknown(ty: Type) -> Self {
        let provenance = TypeProvenance::unknown(&ty);
        Self { ty, provenance }
    }

    fn from_resolved_with_budget(
        resolved: &ResolvedType,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, TypeError> {
        charge_type_cells(&resolved.ty, budget)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        budget
            .charge(1)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        Ok(Self {
            ty: zonk_type(&resolved.ty, &HashMap::new()),
            provenance: TypeProvenance::Resolved(resolved.provenance.clone()),
        })
    }

    fn function_with_budget(
        domain: Self,
        codomain: Self,
        span: Option<Span>,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, TypeError> {
        let domain = ProvenancedTypeOwner::new(domain);
        let codomain = ProvenancedTypeOwner::new(codomain);
        if !domain.provenance.aligns(&domain.ty) || !codomain.provenance.aligns(&codomain.ty) {
            return Err(invalid_state());
        }
        budget
            .charge(2)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        let domain = domain.into_inner();
        let codomain = codomain.into_inner();
        Ok(Self {
            ty: Type::Function(Box::new(domain.ty), Box::new(codomain.ty)),
            provenance: TypeProvenance::Function {
                span,
                parts: Arc::new((domain.provenance, codomain.provenance)),
            },
        })
    }

    fn function_computation_with_budget(
        domain: Self,
        codomain: Self,
        effects: EffectRow,
        span: Option<Span>,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, TypeError> {
        let mut function = Self::function_with_budget(domain, codomain, span, budget)?;
        let Type::Function(domain, value) = function.ty else {
            return Err(invalid_state());
        };
        function.ty = Type::function_computation(*domain, ComputationType::new(*value, effects));
        Ok(function)
    }

    fn into_function_parts(self) -> Result<(Self, Self), TypeError> {
        let value = ProvenancedTypeOwner::new(self);
        let (domain_provenance, codomain_provenance) =
            value.provenance.function_parts(&value.ty)?;
        let value = value.into_inner();
        let (domain, codomain) = match value.ty {
            Type::Function(domain, codomain) => (domain, codomain),
            Type::EffectfulFunction(domain, computation) => {
                let crate::types::ComputationType { value, effects } = *computation;
                drop(effects);
                (domain, Box::new(value))
            }
            ty => {
                discard_type_iteratively(ty);
                return Err(invalid_state());
            }
        };
        Ok((
            Self {
                ty: *domain,
                provenance: domain_provenance,
            },
            Self {
                ty: *codomain,
                provenance: codomain_provenance,
            },
        ))
    }
}

impl TypeContext {
    /// Creates an empty typing context.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Adds or replaces one resolved binder type.
    ///
    /// This prepares caller-owned context metadata. Public elaboration entry
    /// points validate and charge the complete context before cloning it.
    pub fn insert(&mut self, binder: BinderId, ty: Type) {
        let provenance = TypeProvenance::unknown(&ty);
        if let Some(displaced) = self.binders.insert(
            binder,
            TypeFact {
                ty,
                provenance,
                quantified: Box::new([]),
            },
        ) {
            discard_type_fact(displaced);
        }
    }

    /// Returns the monotype assigned to a resolved binder.
    #[must_use]
    pub fn lookup(&self, binder: BinderId) -> Option<&Type> {
        self.binders.get(&binder).map(|fact| &fact.ty)
    }

    fn insert_with_provenance(
        &mut self,
        binder: BinderId,
        ty: Type,
        provenance: TypeProvenance,
    ) -> Result<bool, TypeError> {
        let ty = IterativeTypeOwner::new(ty);
        if !provenance.aligns(&ty) {
            return Err(invalid_state());
        }
        let displaced = self.binders.insert(
            binder,
            TypeFact {
                ty: ty.into_inner(),
                provenance,
                quantified: Box::new([]),
            },
        );
        if let Some(displaced) = displaced {
            discard_type_fact(displaced);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn remove_and_discard(&mut self, binder: BinderId) -> bool {
        let Some(fact) = self.binders.remove(&binder) else {
            return false;
        };
        discard_type_fact(fact);
        true
    }

    fn fact(&self, binder: BinderId) -> Option<&TypeFact> {
        self.binders.get(&binder)
    }

    fn set_quantified(
        &mut self,
        binder: BinderId,
        quantified: Box<[(TypeVariableId, Kind)]>,
    ) -> Result<(), TypeError> {
        let fact = self.binders.get_mut(&binder).ok_or_else(invalid_state)?;
        fact.quantified = quantified;
        Ok(())
    }
}

/// A typed Core node returned by a synthesis or checking rule.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TypedNode {
    /// Core identity allocated for the expression.
    pub node: NodeId,
    /// Structural result type.
    pub ty: Type,
    /// Least effect row requested while evaluating this expression.
    pub effects: EffectRow,
    provenance: TypeProvenance,
}

impl TypedNode {
    /// Consumes a typed result and dismantles its structural type without
    /// following the host call stack.
    ///
    /// Use this when a potentially deep result is not transferred into a Core
    /// program or a [`crate::driver::Observation`].
    pub fn discard_iteratively(self) {
        discard_typed_node(self);
    }
}

struct ProvenancedTypeOwner(Option<ProvenancedType>);

impl ProvenancedTypeOwner {
    fn new(value: ProvenancedType) -> Self {
        Self(Some(value))
    }

    fn into_inner(mut self) -> ProvenancedType {
        self.0.take().expect("provenanced type transfers once")
    }

    fn replace_type(&mut self, ty: Type) {
        replace_type_iteratively(
            &mut self.0.as_mut().expect("provenanced type remains live").ty,
            ty,
        );
    }

    fn set_provenance(&mut self, provenance: TypeProvenance) {
        self.0
            .as_mut()
            .expect("provenanced type remains live")
            .provenance = provenance;
    }
}

impl Deref for ProvenancedTypeOwner {
    type Target = ProvenancedType;

    fn deref(&self) -> &Self::Target {
        self.0.as_ref().expect("provenanced type remains live")
    }
}

impl Drop for ProvenancedTypeOwner {
    fn drop(&mut self) {
        if let Some(value) = self.0.take() {
            discard_provenanced_type(value);
        }
    }
}

struct TypedNodeOwner(Option<TypedNode>);

fn take_type_iteratively(ty: &mut Type) -> IterativeTypeOwner {
    IterativeTypeOwner::new(std::mem::replace(ty, Type::Unit))
}

impl TypedNodeOwner {
    fn new(value: TypedNode) -> Self {
        Self(Some(value))
    }

    fn into_inner(mut self) -> TypedNode {
        self.0.take().expect("typed node transfers once")
    }

    fn set_node(&mut self, node: NodeId) {
        self.0.as_mut().expect("typed node remains live").node = node;
    }

    fn replace_type(&mut self, ty: Type) {
        replace_type_iteratively(
            &mut self.0.as_mut().expect("typed node remains live").ty,
            ty,
        );
    }

    fn take_type(&mut self) -> IterativeTypeOwner {
        take_type_iteratively(&mut self.0.as_mut().expect("typed node remains live").ty)
    }

    fn set_provenance(&mut self, provenance: TypeProvenance) {
        self.0.as_mut().expect("typed node remains live").provenance = provenance;
    }

    fn replace_effects(&mut self, effects: EffectRow) {
        self.0.as_mut().expect("typed node remains live").effects = effects;
    }
}

impl Deref for TypedNodeOwner {
    type Target = TypedNode;

    fn deref(&self) -> &Self::Target {
        self.0.as_ref().expect("typed node remains live")
    }
}

impl Drop for TypedNodeOwner {
    fn drop(&mut self) {
        if let Some(value) = self.0.take() {
            discard_typed_node(value);
        }
    }
}

