impl Drop for CheckedTypeVariableBuffer {
    fn drop(&mut self) {
        while let Some(parameter) = self.0.pop() {
            let crate::resolved::ResolvedTypeVariable { origin, .. } = parameter;
            discard_origin_iteratively(origin);
        }
    }
}

