fn discard_provenanced_type(provenanced: ProvenancedType) {
    discard_type_iteratively(provenanced.ty);
    drop(provenanced.provenance);
}

fn discard_typed_node(node: TypedNode) {
    discard_type_iteratively(node.ty);
    drop(node.effects);
    drop(node.provenance);
}

fn discard_match_progress(progress: Box<MatchProgress<'_>>) {
    let MatchProgress {
        scrutinee,
        matrix,
        result_type,
        ..
    } = *progress;
    discard_typed_node(scrutinee);
    for row in matrix {
        for pattern in row {
            pattern.discard_iteratively();
        }
    }
    if let Some((ty, provenance, _)) = result_type {
        discard_type_iteratively(ty);
        drop(provenance);
    }
}

fn discard_elaboration_task(task: ElaborationTask<'_>) {
    match task {
        ElaborationTask::Equation(_) => {}
        ElaborationTask::FinishCleanupAction(_) => {}
        ElaborationTask::ResourceBody { .. }
        | ElaborationTask::ProviderInstanceBody { .. }
        | ElaborationTask::FinishProviderInstance(_)
        | ElaborationTask::FinishCleanup { .. }
        | ElaborationTask::BeginCleanupBinding { .. }
        | ElaborationTask::FinishHookBody { .. }
        | ElaborationTask::FinishResource(_)
        | ElaborationTask::FinishPerform(_) => {}
        ElaborationTask::RetainLocalNewtype(_)
        | ElaborationTask::Synthesize { .. }
        | ElaborationTask::BeginRegistrationBinding { .. }
        | ElaborationTask::AfterApplicationFunction { .. }
        | ElaborationTask::FinishProviderStateAccess { .. }
        | ElaborationTask::AfterLeft { .. }
        | ElaborationTask::CheckRecursiveMember(_)
        | ElaborationTask::BeginRecursiveGroup(_)
        | ElaborationTask::FinishRecursiveGroup { .. }
        | ElaborationTask::FinishBlock { .. } => {}
        ElaborationTask::Check { expected, .. }
        | ElaborationTask::CheckBlock { expected, .. }
        | ElaborationTask::FinishCheck { expected, .. } => {
            discard_provenanced_type(expected);
        }
        ElaborationTask::CheckFunction {
            domain,
            codomain,
            function_type,
            presentation,
            ..
        } => {
            discard_provenanced_type(domain);
            discard_provenanced_type(codomain);
            discard_provenanced_type(function_type);
            discard_origin_iteratively(presentation);
        }
        ElaborationTask::FinishFunction {
            binder,
            pattern,
            domain,
            ty,
            origin,
            ..
        } => {
            binder.discard_metadata();
            if let Some(pattern) = pattern {
                pattern.discard_iteratively();
            }
            if let Some(domain) = domain {
                discard_type_iteratively(domain);
            }
            discard_type_iteratively(ty);
            discard_origin_iteratively(origin);
        }
        ElaborationTask::FinishApplication {
            function, codomain, ..
        } => {
            discard_typed_node(function);
            discard_provenanced_type(codomain);
        }
        ElaborationTask::AfterMatchScrutinee { expected, .. } => {
            if let Some((expected, _)) = expected {
                discard_provenanced_type(expected);
            }
        }
        ElaborationTask::FinishMatchArm { progress, row, .. } => {
            discard_match_progress(progress);
            for pattern in row {
                pattern.discard_iteratively();
            }
        }
        ElaborationTask::FinishMatch(progress) => discard_match_progress(progress),
        ElaborationTask::AfterRight { left, .. } => discard_typed_node(left),
        ElaborationTask::BeginBinding {
            expected,
            finish_expected,
            ..
        } => {
            if let Some(expected) = expected {
                discard_provenanced_type(expected);
            }
            if let Some(expected) = finish_expected {
                discard_provenanced_type(expected);
            }
        }
        ElaborationTask::FinishBinding { expected, .. } => {
            if let Some(expected) = expected {
                discard_provenanced_type(expected);
            }
        }
    }
}

fn discard_elaborated_declaration(declaration: ElaboratedDeclaration) {
    match declaration {
        ElaboratedDeclaration::Binding { binder, origin, .. } => {
            binder.discard_metadata();
            discard_origin_iteratively(origin);
        }
        ElaboratedDeclaration::PatternBinding {
            pattern, origin, ..
        } => {
            pattern.discard_iteratively();
            discard_origin_iteratively(origin);
        }
        ElaboratedDeclaration::Evidence {
            members, origin, ..
        }
        | ElaboratedDeclaration::Recursive {
            members, origin, ..
        } => {
            for (binder, _) in members {
                binder.discard_metadata();
            }
            discard_origin_iteratively(origin);
        }
        ElaboratedDeclaration::Newtype(_) => {}
    }
}

fn operational_domain(
    parameters: &[crate::resolved::ResolvedTypedPattern],
    span: Span,
    budget: &mut TypeWorkBudget,
) -> Result<ProvenancedType, TypeError> {
    match parameters {
        [] => Err(invalid_state()),
        [parameter] => ProvenancedType::from_resolved_with_budget(&parameter.annotation, budget),
        parameters => {
            budget
                .charge(2)
                .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
            for parameter in parameters {
                charge_type_cells(&parameter.annotation.ty, budget)
                    .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
            }
            let mut types = Vec::new();
            types
                .try_reserve(parameters.len())
                .map_err(|_| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
            types.extend(
                parameters
                    .iter()
                    .map(|parameter| zonk_type(&parameter.annotation.ty, &HashMap::new())),
            );
            let ty = Type::Tuple(types.into_boxed_slice());
            Ok(ProvenancedType {
                provenance: TypeProvenance::atom(Some(span)),
                ty,
            })
        }
    }
}

fn computation_nominal_identities(
    ty: &Type,
    effects: &EffectRow,
    budget: &mut TypeWorkBudget,
) -> Result<HashSet<NominalTypeId>, TypeError> {
    let mut identities = HashSet::new();
    collect_nominal_identities(ty, &mut identities, budget)
        .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
    budget
        .charge(1)
        .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
    if effects.tail().is_some() {
        budget
            .charge(1)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
    }
    for instance in effects
        .known()
        .iter()
        .chain(effects.tail().into_iter().flat_map(|tail| tail.lacks()))
    {
        budget
            .charge(1)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        for argument in instance.arguments() {
            crate::resolved::collect_argument_nominal_identities(argument, &mut identities, budget)
                .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        }
    }
    Ok(identities)
}

fn schedule_block<'a>(
    block: &'a ResolvedBlock,
    expected: Option<(ProvenancedType, CheckKind)>,
    synthesis_cause: Option<SynthesisCause>,
    tasks: &mut ElaborationTaskBuffer<'a>,
    declaration_start: usize,
    type_work: &mut TypeWorkBudget,
) -> Result<(), TypeError> {
    tasks.push(ElaborationTask::FinishBlock {
        declarations: &block.declarations,
        declaration_start,
        result_span: block.result.span,
    });
    if let Some((expected, kind)) = expected {
        tasks.push(ElaborationTask::Check {
            expression: &block.result,
            expected,
            kind,
        });
    } else {
        let result_cause = match synthesis_cause {
            Some(SynthesisCause::Binding(span)) => Some(SynthesisCause::NestedBinding(span)),
            cause => cause,
        };
        tasks.push(ElaborationTask::Synthesize {
            expression: &block.result,
            cause: result_cause,
        });
    }
    for declaration in block.declarations.iter().rev() {
        match declaration {
            ResolvedLocalDeclaration::Evidence(source) => {
                tasks.push(ElaborationTask::Equation(EquationTask::LexicalEvidence(
                    source,
                )));
            }
            ResolvedLocalDeclaration::Binding(binding) => {
                if binding.annotation.is_none()
                    && block.declarations.len() == 1
                    && let ResolvedExprKind::Cleanup(cleanup) = &block.result.kind
                    && matches!(&binding.pattern.kind, ResolvedPatternKind::Binder(binder) if binder.id == cleanup.callback)
                {
                    tasks.push(ElaborationTask::BeginCleanupBinding { binding });
                    continue;
                }
                if binding.annotation.is_none()
                    && matches!(binding.initializer.kind, ResolvedExprKind::Function(_))
                    && block.declarations.len() == 1
                    && let ResolvedExprKind::Handle(handler) = &block.result.kind
                    && handler.hook_registration.as_ref().is_some_and(|contract| {
                        matches!(&binding.pattern.kind, ResolvedPatternKind::Binder(binder)
                            if binder.id == contract.callback)
                    })
                {
                    tasks.push(ElaborationTask::BeginRegistrationBinding { binding, handler });
                    continue;
                }
                let expected = binding
                    .annotation
                    .as_ref()
                    .map(|annotation| {
                        ProvenancedType::from_resolved_with_budget(annotation, type_work)
                    })
                    .transpose()?
                    .map(ProvenancedTypeOwner::new);
                let finish_expected = expected
                    .as_ref()
                    .map(|expected| {
                        clone_type_with_budget(&expected.ty, type_work).map(|ty| ProvenancedType {
                            ty,
                            provenance: expected.provenance.clone(),
                        })
                    })
                    .transpose()
                    .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
                tasks.push(ElaborationTask::BeginBinding {
                    binding,
                    expected: expected.map(ProvenancedTypeOwner::into_inner),
                    finish_expected,
                });
            }
            ResolvedLocalDeclaration::Recursive(group) => {
                tasks.push(ElaborationTask::BeginRecursiveGroup(group));
            }
            ResolvedLocalDeclaration::Newtype(owner) => {
                tasks.push(ElaborationTask::RetainLocalNewtype(*owner));
            }
        }
    }
    Ok(())
}

fn check_mismatch(
    kind: CheckKind,
    span: Span,
    expected: Type,
    found: Type,
    expected_cause: Option<Span>,
    registry: &ResolvedRegistry,
) -> TypeError {
    let expected = IterativeTypeOwner::new(expected);
    let found = IterativeTypeOwner::new(found);
    match kind {
        CheckKind::General | CheckKind::CleanupAction(_) => TypeError::Mismatch(TypeMismatch {
            span,
            expected_display: registry.display_source_type(&expected),
            found_display: registry.display_source_type(&found),
            expected: Box::new(expected.into_inner()),
            found: Box::new(found.into_inner()),
        }),
        CheckKind::Argument {
            function_span,
            whole_span,
            recursive_call,
        } => {
            if recursive_call {
                let mut diagnostic = Diagnostic::new(
                    TypeReason::PolymorphicRecursion,
                    SourceLabel::new(
                        span,
                        "this recursive call requires a different type instantiation",
                    ),
                );
                diagnostic.related.push(SourceLabel::new(
                    function_span,
                    "this recursive function is checked monomorphically",
                ));
                diagnostic.expected = Some(registry.display_source_type(&expected));
                diagnostic.found = Some(registry.display_source_type(&found));
                return TypeError::Source(Box::new(TypeDiagnostic {
                    diagnostic,
                    context: TypeDiagnosticContext::PolymorphicRecursion([
                        Some(RecursionLabel::Function),
                        None,
                    ]),
                }));
            }
            let expected = registry.display_source_type(&expected);
            let found = registry.display_source_type(&found);
            let mut diagnostic = Diagnostic::new(
                TypeReason::Argument,
                SourceLabel::new(span, "this argument does not match the function domain"),
            );
            diagnostic.related.push(SourceLabel::new(
                expected_cause.unwrap_or(function_span),
                "the function domain is required here",
            ));
            if whole_span != span && whole_span != function_span {
                diagnostic.related.push(SourceLabel::new(
                    whole_span,
                    "this application supplies the argument",
                ));
            }
            diagnostic.expected = Some(expected);
            diagnostic.found = Some(found);
            TypeError::source(diagnostic)
        }
        CheckKind::Definition { result_cause } => {
            let expected = registry.display_source_type(&expected);
            let found = registry.display_source_type(&found);
            let mut diagnostic = Diagnostic::new(
                TypeReason::DefinitionResult,
                SourceLabel::new(span, "this function body has the wrong result type"),
            );
            diagnostic.related.push(SourceLabel::new(
                expected_cause.unwrap_or(result_cause),
                "the function interface requires this result type",
            ));
            diagnostic.expected = Some(expected);
            diagnostic.found = Some(found);
            TypeError::source(diagnostic)
        }
        CheckKind::BindingInitializer {
            initializer_span,
            annotation_span,
        } => {
            let expected = registry.display_source_type(&expected);
            let found = registry.display_source_type(&found);
            let mut diagnostic = Diagnostic::new(
                TypeReason::BindingInitializer,
                SourceLabel::new(
                    initializer_span,
                    format!("this initializer has type {found}"),
                ),
            );
            diagnostic.related.push(SourceLabel::new(
                annotation_span,
                format!("this binding annotation requires {expected}"),
            ));
            diagnostic.expected = Some(expected);
            diagnostic.found = Some(found);
            TypeError::source(diagnostic)
        }
    }
}

fn function_needs_context(span: Span, cause: Option<SynthesisCause>) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::FunctionNeedsContext,
        SourceLabel::new(
            span,
            "this anonymous function needs an expected function type",
        ),
    );
    if let Some(cause) = cause {
        let (span, message, help) = match cause {
            SynthesisCause::Binding(span) | SynthesisCause::NestedBinding(span) => (
                span,
                "this unannotated binding requires its initializer to synthesize a type",
                Some("add a function type annotation to this binding"),
            ),
            SynthesisCause::ProgramResult(span) => (
                span,
                "the program result requires this expression to synthesize a type",
                None,
            ),
            SynthesisCause::Application { whole_span, .. } => (
                whole_span,
                "this application requires its function position to synthesize a type",
                None,
            ),
            SynthesisCause::Operator(span) => (
                span,
                "this operator requires its operand to synthesize a type",
                None,
            ),
        };
        diagnostic.related.push(SourceLabel::new(span, message));
        diagnostic.help = help.map(str::to_owned);
    }
    TypeError::Source(Box::new(TypeDiagnostic {
        diagnostic,
        context: TypeDiagnosticContext::FunctionNeedsContext(cause),
    }))
}

fn not_applicable(
    function_span: Span,
    whole_span: Span,
    found: &Type,
    registry: &ResolvedRegistry,
) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::NotApplicable,
        SourceLabel::new(function_span, "this expression is not a function"),
    );
    diagnostic.related.push(SourceLabel::new(
        whole_span,
        "this application requires a function here",
    ));
    diagnostic.expected = Some("function".to_owned());
    diagnostic.found = Some(registry.display_source_type(found));
    TypeError::source(diagnostic)
}

fn equation_interface_not_function(
    annotation: &ResolvedType,
    equation_name: &crate::resolved::ResolvedEquationHead,
    registry: &ResolvedRegistry,
) -> TypeError {
    let found = registry.display_source_type(&annotation.ty);
    let mut diagnostic = Diagnostic::new(
        TypeReason::EquationInterfaceNotFunction,
        SourceLabel::new(
            annotation.span,
            "this equational interface does not declare a function",
        ),
    );
    diagnostic.related.push(SourceLabel::new(
        equation_name.origin.primary_span(),
        "this equation head requires one function domain",
    ));
    diagnostic.expected = Some("function".to_owned());
    diagnostic.found = Some(found);
    TypeError::source(diagnostic)
}

fn schedule_left<'a>(
    primitive: Primitive,
    whole_span: Span,
    binary: &'a crate::resolved::ResolvedBinaryExpr,
    tasks: &mut ElaborationTaskBuffer<'a>,
) {
    tasks.push(ElaborationTask::AfterLeft {
        primitive,
        whole_span,
        operator_span: binary.operator_span,
        right: &binary.right,
        left_span: binary.left.span,
    });
    tasks.push(ElaborationTask::Synthesize {
        expression: &binary.left,
        cause: Some(SynthesisCause::Operator(binary.operator_span)),
    });
}

/// Temporary frontend-only boundary: provider templates await lifecycle checking.
fn foreign_privilege_unavailable() -> TypeError {
    TypeError::Internal(ElaborationFailure::ForeignPrivilegeUnavailable)
}

fn unsupported_provider_resource() -> TypeError {
    TypeError::Internal(ElaborationFailure::InvalidState)
}

fn invalid_state() -> TypeError {
    TypeError::Internal(ElaborationFailure::InvalidState)
}

fn type_resource() -> TypeError {
    TypeError::Internal(ElaborationFailure::TypeResourceExhausted)
}

fn inference_registry_error(error: InferenceRegistryFailure) -> TypeError {
    match error {
        InferenceRegistryFailure::Resource => {
            TypeError::Internal(ElaborationFailure::TypeResourceExhausted)
        }
        InferenceRegistryFailure::Missing
        | InferenceRegistryFailure::Duplicate
        | InferenceRegistryFailure::Conflict => invalid_state(),
    }
}

fn generated_type_variable_registry_error(
    error: GeneratedTypeVariableRegistryFailure,
) -> TypeError {
    match error {
        GeneratedTypeVariableRegistryFailure::Resource => {
            TypeError::Internal(ElaborationFailure::TypeResourceExhausted)
        }
        GeneratedTypeVariableRegistryFailure::Missing
        | GeneratedTypeVariableRegistryFailure::Duplicate
        | GeneratedTypeVariableRegistryFailure::Conflict => invalid_state(),
    }
}

fn allocate_inference_variable(
    next_inference: &mut u32,
    variables: &mut InferenceVariableRegistry,
    budget: &mut TypeWorkBudget,
    kind: &Kind,
    origin: Span,
) -> Result<Type, TypeError> {
    if kind_mentions_effect_row(kind) {
        return Err(invalid_state());
    }
    let identity = InferenceVariableId::new(*next_inference);
    let next = next_inference.checked_add(1).ok_or_else(invalid_state)?;
    variables
        .insert(identity, kind, origin, budget)
        .map_err(inference_registry_error)?;
    *next_inference = next;
    Ok(Type::Inference(identity))
}

fn kind_mentions_effect_row(root: &Kind) -> bool {
    let mut work = vec![root];
    while let Some(kind) = work.pop() {
        match kind {
            Kind::Type => {}
            Kind::EffectRow => return true,
            Kind::Arrow(domain, codomain) => {
                work.push(codomain);
                work.push(domain);
            }
        }
    }
    false
}

fn allocate_row_inference_variable(
    next_inference: &mut u32,
    variables: &mut InferenceVariableRegistry,
    budget: &mut TypeWorkBudget,
    origin: Span,
) -> Result<InferenceVariableId, TypeError> {
    let identity = InferenceVariableId::new(*next_inference);
    let next = next_inference.checked_add(1).ok_or_else(invalid_state)?;
    variables
        .insert(identity, &Kind::EffectRow, origin, budget)
        .map_err(inference_registry_error)?;
    *next_inference = next;
    Ok(identity)
}

fn kind_failure_for_unification(failure: KindFailure) -> UnificationFailure {
    match failure {
        KindFailure::Resource(_) => UnificationFailure::Resource,
        failure => failure
            .internal_context()
            .map_or(UnificationFailure::Invariant, |context| {
                UnificationFailure::Kind {
                    context,
                    span: None,
                }
            }),
    }
}

fn inference_registry_failure_for_unification(
    failure: InferenceRegistryFailure,
) -> UnificationFailure {
    match failure {
        InferenceRegistryFailure::Resource => UnificationFailure::Resource,
        InferenceRegistryFailure::Missing
        | InferenceRegistryFailure::Duplicate
        | InferenceRegistryFailure::Conflict => UnificationFailure::Invariant,
    }
}

fn generated_type_variable_registry_failure_for_unification(
    failure: GeneratedTypeVariableRegistryFailure,
) -> UnificationFailure {
    match failure {
        GeneratedTypeVariableRegistryFailure::Resource => UnificationFailure::Resource,
        GeneratedTypeVariableRegistryFailure::Missing
        | GeneratedTypeVariableRegistryFailure::Duplicate
        | GeneratedTypeVariableRegistryFailure::Conflict => UnificationFailure::Invariant,
    }
}

fn candidate_kind_environment<'a>(
    candidate: &Type,
    registry: &'a ResolvedRegistry,
    generated_type_variables: &'a GeneratedTypeVariableRegistry,
    inference_variables: &'a InferenceVariableRegistry,
    span: Span,
    budget: &mut TypeWorkBudget,
) -> Result<KindEnvironments<'a>, UnificationFailure> {
    let mut environments = KindEnvironments::new_with_registry(registry);
    let meter = RefCell::new(budget);
    crate::types::visit_type_structure_with_budget(
        candidate,
        &mut |cells| {
            meter
                .borrow_mut()
                .charge(cells)
                .map_err(|()| UnificationFailure::Resource)
        },
        |node, _| {
            let mut borrowed = meter.borrow_mut();
            let budget = &mut **borrowed;
            let variable = match node {
                crate::types::TypeStructureNode::Type(Type::Variable(variable)) => {
                    Some(EffectRowVariable::Rigid(*variable))
                }
                crate::types::TypeStructureNode::Type(Type::Inference(variable)) => {
                    Some(EffectRowVariable::Inference(*variable))
                }
                crate::types::TypeStructureNode::Tail(tail) => Some(tail.variable()),
                _ => None,
            };
            if let Some(variable) = variable {
                match variable {
                    EffectRowVariable::Rigid(identity)
                        if !environments.contains_declared(identity) =>
                    {
                        match identity {
                            TypeVariableId::Resolved { .. } => {
                                let parameter = registry
                                    .type_variable(identity)
                                    .ok_or(UnificationFailure::Invariant)?;
                                environments
                                    .insert_declared(
                                        identity,
                                        &parameter.kind,
                                        parameter.origin.primary_span(),
                                        budget,
                                    )
                                    .map_err(kind_failure_for_unification)?;
                            }
                            TypeVariableId::Generated(_) => {
                                let fact =
                                    generated_type_variables.fact(identity, budget).map_err(
                                        generated_type_variable_registry_failure_for_unification,
                                    )?;
                                environments
                                    .insert_declared(identity, &fact.kind, fact.origin, budget)
                                    .map_err(kind_failure_for_unification)?;
                            }
                        }
                    }
                    EffectRowVariable::Inference(identity)
                        if !environments.contains_inference(identity) =>
                    {
                        let fact = inference_variables
                            .fact(identity, budget)
                            .map_err(inference_registry_failure_for_unification)?;
                        environments
                            .insert_inference(identity, &fact.kind, Some(fact.origin), budget, span)
                            .map_err(kind_failure_for_unification)?;
                    }
                    _ => {}
                }
            }
            match node {
                crate::types::TypeStructureNode::Type(Type::Nominal(identity))
                    if !environments.contains_nominal(*identity) =>
                {
                    match registry
                        .nominal_kind(*identity)
                        .ok_or(UnificationFailure::Invariant)?
                    {
                        CanonicalNominalKind::RowBearingResource { resource, origin } => {
                            let owner = crate::resolved::OwnerId::Resource(resource);
                            let parameters = registry
                                .defining_owner_parameters(owner)
                                .ok_or(UnificationFailure::Invariant)?;
                            registry
                                .authenticate_owner_signature(
                                    owner,
                                    Some(*identity),
                                    parameters,
                                    budget,
                                )
                                .map_err(|failure| {
                                    if failure.is_resource_exhaustion() {
                                        UnificationFailure::Resource
                                    } else {
                                        UnificationFailure::Invariant
                                    }
                                })?;
                            environments
                                .insert_row_resource_family(
                                    *identity, resource, parameters, origin, budget,
                                )
                                .map_err(kind_failure_for_unification)?;
                        }
                        CanonicalNominalKind::Parameters { parameters, origin } => environments
                            .insert_nominal(*identity, parameters, origin, budget)
                            .map_err(kind_failure_for_unification)?,
                        CanonicalNominalKind::Frozen { kind, origin } => environments
                            .insert_frozen_nominal(*identity, kind, origin, budget)
                            .map_err(kind_failure_for_unification)?,
                    }
                }
                crate::types::TypeStructureNode::Type(Type::Forall(_, _)) => {
                    return Err(UnificationFailure::Invariant);
                }
                _ => {}
            }
            Ok(false)
        },
    )?;
    Ok(environments)
}

fn authenticate_inference_solution_kind(
    variable: InferenceVariableId,
    candidate: &Type,
    registry: &ResolvedRegistry,
    generated_type_variables: &GeneratedTypeVariableRegistry,
    inference_variables: &InferenceVariableRegistry,
    budget: &mut TypeWorkBudget,
) -> Result<(), UnificationFailure> {
    #[cfg(test)]
    SOLUTION_KIND_AUTHENTICATIONS.with(|count| count.set(count.get().saturating_add(1)));
    let variable_fact = inference_variables
        .fact(variable, budget)
        .map_err(inference_registry_failure_for_unification)?;
    let environments = candidate_kind_environment(
        candidate,
        registry,
        generated_type_variables,
        inference_variables,
        variable_fact.origin,
        budget,
    )?;
    let candidate_kind = environments
        .synthesize_body_free_kind(candidate, variable_fact.origin, budget)
        .map_err(kind_failure_for_unification)?;
    let equal = same_kind_with_budget(&variable_fact.kind, candidate_kind, budget)
        .map_err(|()| UnificationFailure::Resource)?;
    if equal {
        Ok(())
    } else {
        Err(UnificationFailure::Mismatch)
    }
}

fn authenticate_zonk_inference_occurrence(
    identity: InferenceVariableId,
    inference_variables: &InferenceVariableRegistry,
    solutions: &HashMap<InferenceVariableId, Type>,
    authenticated_solutions: &HashSet<InferenceVariableId>,
    budget: &mut TypeWorkBudget,
) -> Result<(), UnificationFailure> {
    inference_variables
        .fact(identity, budget)
        .map_err(inference_registry_failure_for_unification)?;
    if solutions.contains_key(&identity) {
        budget
            .charge(1)
            .map_err(|()| UnificationFailure::Resource)?;
        if !authenticated_solutions.contains(&identity) {
            return Err(UnificationFailure::Invariant);
        }
    }
    Ok(())
}

fn zonk_core_type(
    ty: &Type,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    inference_variables: &InferenceVariableRegistry,
    authenticated_solutions: &HashSet<InferenceVariableId>,
    type_work: &mut TypeWorkBudget,
    strict: bool,
) -> Result<Type, BuildError> {
    let mut has_row_inference = false;
    let (zonked, mut unresolved, _) =
        zonk_type_with_status_and_inference_and_rows(ty, solutions, |work| match work {
            ZonkWork::TypeCells(cells) => type_work
                .charge(cells)
                .map_err(|()| BuildError::TypeWorkExceeded),
            ZonkWork::RowInference => {
                has_row_inference = true;
                Ok(())
            }
            ZonkWork::Inference(identity) => authenticate_zonk_inference_occurrence(
                identity,
                inference_variables,
                solutions,
                authenticated_solutions,
                type_work,
            )
            .map_err(|failure| match failure {
                UnificationFailure::Resource => BuildError::TypeWorkExceeded,
                _ => BuildError::InvalidPayload,
            }),
        })?;
    // The complete borrowed rebuild observes every row tail, including nested
    // argument and lacks payloads. Only row inference tails need a further
    // solution scan; nonempty substitution recomputes that observation.
    let zonked = if row_solutions.is_empty() {
        IterativeTypeOwner::new(zonked)
    } else {
        let after_rows = IterativeTypeOwner::new(
            zonk_owned_type_with_rows(zonked, &HashMap::new(), row_solutions, type_work)
                .map_err(|()| BuildError::TypeWorkExceeded)?,
        );
        has_row_inference = false;
        let (after_types, newly_unresolved, _) = zonk_type_with_status_and_inference_and_rows(
            &after_rows,
            solutions,
            |work| match work {
                ZonkWork::TypeCells(cells) => type_work
                    .charge(cells)
                    .map_err(|()| BuildError::TypeWorkExceeded),
                ZonkWork::RowInference => {
                    has_row_inference = true;
                    Ok(())
                }
                ZonkWork::Inference(identity) => authenticate_zonk_inference_occurrence(
                    identity,
                    inference_variables,
                    solutions,
                    authenticated_solutions,
                    type_work,
                )
                .map_err(|failure| match failure {
                    UnificationFailure::Resource => BuildError::TypeWorkExceeded,
                    _ => BuildError::InvalidPayload,
                }),
            },
        )?;
        unresolved |= newly_unresolved;
        IterativeTypeOwner::new(after_types)
    };
    if strict
        && (unresolved
            || (has_row_inference
                && type_contains_unsolved_row_inference(&zonked, row_solutions, type_work)
                    .map_err(|()| BuildError::TypeWorkExceeded)?))
    {
        drop(zonked);
        Err(BuildError::InvalidPayload)
    } else {
        Ok(zonked.into_inner())
    }
}

fn zonk_core_effect_row(
    row: &EffectRow,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    inference_variables: &InferenceVariableRegistry,
    authenticated_solutions: &HashSet<InferenceVariableId>,
    type_work: &mut TypeWorkBudget,
    strict: bool,
) -> Result<EffectRow, BuildError> {
    let row =
        clone_effect_row_with_budget(row, type_work).map_err(|()| BuildError::TypeWorkExceeded)?;
    let wrapper = IterativeTypeOwner::new(Type::function_computation(
        Type::Unit,
        ComputationType::new(Type::Unit, row),
    ));
    let zonked = zonk_core_type(
        &wrapper,
        solutions,
        row_solutions,
        inference_variables,
        authenticated_solutions,
        type_work,
        strict,
    )?;
    match zonked {
        Type::Function(_, _) => Ok(EffectRow::empty()),
        Type::EffectfulFunction(_, computation) => Ok(computation.effects),
        other => {
            discard_type_iteratively(other);
            Err(BuildError::InvalidPayload)
        }
    }
}

fn resolved_build_error(error: ResolvedBuildFailure) -> TypeError {
    match error {
        ResolvedBuildFailure::InvalidState => invalid_state(),
        ResolvedBuildFailure::Kind(context) => TypeError::Internal(ElaborationFailure::Kind {
            context,
            span: None,
        }),
        ResolvedBuildFailure::TypeResource => {
            TypeError::Internal(ElaborationFailure::TypeResourceExhausted)
        }
        ResolvedBuildFailure::ConstraintResource => constraint_resource(),
    }
}

fn pattern_mismatch(span: Span, expected: &Type, registry: &ResolvedRegistry) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::PatternMismatch,
        SourceLabel::new(span, "this pattern does not match its expected type"),
    );
    diagnostic.expected = Some(registry.display_source_type(expected));
    TypeError::source(diagnostic)
}

fn constructor_mismatch(span: Span) -> TypeError {
    TypeError::source(Diagnostic::new(
        TypeReason::ConstructorMismatch,
        SourceLabel::new(span, "this constructor has the wrong payload shape"),
    ))
}

fn handler_coverage_error(cause: HandlerCoverageCause, span: Span, message: &str) -> TypeError {
    TypeError::Source(Box::new(TypeDiagnostic {
        diagnostic: Diagnostic::new(TypeReason::HandlerCoverage, SourceLabel::new(span, message)),
        context: TypeDiagnosticContext::HandlerCoverage(cause),
    }))
}

fn completion_outside_error(operation: CompletionOperation, span: Span) -> TypeError {
    TypeError::Source(Box::new(TypeDiagnostic {
        diagnostic: Diagnostic::new(
            TypeReason::ResumeOutsideClause,
            SourceLabel::new(
                span,
                "resume and discard are available only inside an operation clause",
            ),
        ),
        context: TypeDiagnosticContext::CompletionOutside(operation),
    }))
}

fn equation_arity_error(cause: EquationArityCause, span: Span) -> TypeError {
    let message = match cause {
        EquationArityCause::PatternCount => {
            "equational clauses must have the same positive pattern count"
        }
        EquationArityCause::DeclaredArrows => {
            "the equation has more patterns than the declared arrows"
        }
    };
    TypeError::Source(Box::new(TypeDiagnostic {
        diagnostic: Diagnostic::new(TypeReason::EquationArity, SourceLabel::new(span, message)),
        context: TypeDiagnosticContext::EquationArity(cause),
    }))
}

fn case_error(
    reason: TypeReason,
    span: Span,
    message: &'static str,
    witness: Option<String>,
) -> TypeError {
    let mut diagnostic = Diagnostic::new(reason, SourceLabel::new(span, message));
    diagnostic.found = witness;
    TypeError::source(diagnostic)
}

fn binding_origin(binding: &ResolvedBinding) -> Origin {
    let mut related = vec![binding.initializer.span];
    if let Some(annotation) = &binding.annotation {
        related.push(annotation.span);
    }
    Origin::Generated {
        cause: Box::new(Origin::Related {
            primary: Box::new(Origin::Source(binding.span)),
            related,
        }),
        reason: GeneratedReason::BindingLowering,
    }
}

fn recursive_group_origin(group: &ResolvedRecursiveGroup) -> Origin {
    let related = group
        .members
        .iter()
        .flat_map(|member| [member.span, member.annotation.span, member.initializer.span])
        .collect();
    Origin::Generated {
        cause: Box::new(Origin::Related {
            primary: Box::new(Origin::Source(group.span)),
            related,
        }),
        reason: GeneratedReason::RecursiveBindingLowering,
    }
}

fn validate_recursive_member(
    group: &ResolvedRecursiveGroup,
    member: &crate::resolved::ResolvedRecursiveMember,
    registry: &ResolvedRegistry,
) -> Result<(), TypeError> {
    match &member.annotation.ty {
        Type::Function(_, _) | Type::EffectfulFunction(_, _)
            if matches!(member.initializer.kind, ResolvedExprKind::Function(_)) =>
        {
            Ok(())
        }
        Type::Function(_, _) | Type::EffectfulFunction(_, _) => {
            Err(unsafe_recursive_initializer(group, member))
        }
        ty if ty.outer_nominal().is_some() => {
            let owner = ty.outer_nominal().ok_or_else(invalid_state)?;
            let payload = match &member.initializer.kind {
                ResolvedExprKind::Constructor(occurrence) => {
                    let Some(constructor) = registry.constructor(occurrence.constructor) else {
                        return Err(invalid_state());
                    };
                    if constructor.owner != owner || constructor.payload.is_some() {
                        return Err(unsafe_recursive_root(group, member));
                    }
                    None
                }
                ResolvedExprKind::Apply(application) => {
                    let ResolvedExprKind::Constructor(occurrence) = &application.function.kind
                    else {
                        return Err(unsafe_recursive_root(group, member));
                    };
                    let Some(constructor) = registry.constructor(occurrence.constructor) else {
                        return Err(invalid_state());
                    };
                    if constructor.owner != owner || constructor.payload.is_none() {
                        return Err(unsafe_recursive_root(group, member));
                    }
                    Some(application.argument.as_ref())
                }
                _ => return Err(unsafe_recursive_root(group, member)),
            };
            if let Some(payload) = payload {
                let recursive = group
                    .members
                    .iter()
                    .map(|member| member.binder.id)
                    .collect::<HashSet<_>>();
                validate_guarded_payload(payload, &recursive, registry)?;
            }
            Ok(())
        }
        Type::Bytes
        | Type::String
        | Type::Int
        | Type::Bool
        | Type::Unit
        | Type::Tuple(_)
        | Type::Nominal(_)
        | Type::Application(_, _)
        | Type::Variable(_)
        | Type::Inference(_)
        | Type::Forall(_, _)
        | Type::ResourceApply(_, _) => Err(unsafe_recursive_root(group, member)),
    }
}

fn validate_guarded_payload(
    expression: &ResolvedExpr,
    recursive: &HashSet<BinderId>,
    registry: &ResolvedRegistry,
) -> Result<(), TypeError> {
    if !contains_recursive_occurrence(expression, recursive) {
        return Ok(());
    }
    match &expression.kind {
        ResolvedExprKind::Occurrence(occurrence)
            if occurrence
                .global_binder()
                .is_some_and(|binder| recursive.contains(&binder)) =>
        {
            Ok(())
        }
        ResolvedExprKind::Tuple(elements) => {
            for element in elements {
                validate_guarded_payload(element, recursive, registry)?;
            }
            Ok(())
        }
        ResolvedExprKind::Apply(application)
            if matches!(application.function.kind, ResolvedExprKind::Constructor(_)) =>
        {
            let ResolvedExprKind::Constructor(occurrence) = &application.function.kind else {
                return Err(invalid_state());
            };
            if registry.constructor(occurrence.constructor).is_none() {
                return Err(invalid_state());
            }
            validate_guarded_payload(&application.argument, recursive, registry)
        }
        ResolvedExprKind::Function(_) => Ok(()),
        _ => Err(unguarded_recursive_use(expression.span)),
    }
}

fn contains_recursive_occurrence(expression: &ResolvedExpr, recursive: &HashSet<BinderId>) -> bool {
    let mut work = vec![expression];
    while let Some(expression) = work.pop() {
        match &expression.kind {
            ResolvedExprKind::Occurrence(occurrence)
                if occurrence
                    .global_binder()
                    .is_some_and(|binder| recursive.contains(&binder)) =>
            {
                return true;
            }
            ResolvedExprKind::Apply(application) => {
                work.push(&application.argument);
                work.push(&application.function);
            }
            ResolvedExprKind::Add(binary)
            | ResolvedExprKind::Multiply(binary)
            | ResolvedExprKind::Equal(binary) => {
                work.push(&binary.right);
                work.push(&binary.left);
            }
            ResolvedExprKind::Tuple(elements) => work.extend(elements),
            ResolvedExprKind::Block(block) => {
                work.push(&block.result);
                for declaration in &block.declarations {
                    match declaration {
                        ResolvedLocalDeclaration::Evidence(source) => {
                            work.extend(source.method_groups.iter().flat_map(|group| {
                                group.equations.iter().map(|equation| &equation.body)
                            }));
                        }
                        ResolvedLocalDeclaration::Binding(binding) => {
                            work.push(&binding.initializer)
                        }
                        ResolvedLocalDeclaration::Recursive(group) => {
                            work.extend(group.members.iter().map(|member| &member.initializer));
                        }
                        ResolvedLocalDeclaration::Newtype(_) => {}
                    }
                }
            }
            ResolvedExprKind::Function(function) => {
                work.push(&function.body.result);
                for declaration in &function.body.declarations {
                    match declaration {
                        ResolvedLocalDeclaration::Evidence(source) => {
                            work.extend(source.method_groups.iter().flat_map(|group| {
                                group.equations.iter().map(|equation| &equation.body)
                            }));
                        }
                        ResolvedLocalDeclaration::Binding(binding) => {
                            work.push(&binding.initializer)
                        }
                        ResolvedLocalDeclaration::Recursive(group) => {
                            work.extend(group.members.iter().map(|member| &member.initializer));
                        }
                        ResolvedLocalDeclaration::Newtype(_) => {}
                    }
                }
            }
            ResolvedExprKind::Match(match_expression) => {
                work.push(&match_expression.scrutinee);
                work.extend(match_expression.arms.iter().map(|arm| &arm.body));
            }
            ResolvedExprKind::ProviderResource(resource) => {
                work.push(&resource.body);
                work.push(&resource.initializer);
            }
            ResolvedExprKind::Resource(resource) => {
                work.push(&resource.body);
                work.push(&resource.initializer);
            }
            ResolvedExprKind::Cleanup(cleanup) => {
                work.push(&cleanup.body);
                work.push(&cleanup.action);
            }
            ResolvedExprKind::Perform(request) => work.push(&request.operand),
            ResolvedExprKind::Handle(handler) => {
                work.push(&handler.body);
                work.extend(handler.clauses.iter().map(|clause| &clause.body));
            }
            ResolvedExprKind::Resume(resume) => work.push(&resume.value),
            ResolvedExprKind::Discard(_) => {}
            ResolvedExprKind::String(_)
            | ResolvedExprKind::Integer(_)
            | ResolvedExprKind::Boolean(_)
            | ResolvedExprKind::Unit
            | ResolvedExprKind::Constructor(_)
            | ResolvedExprKind::Occurrence(_) => {}
        }
    }
    false
}

fn unsafe_recursive_root(
    group: &ResolvedRecursiveGroup,
    member: &crate::resolved::ResolvedRecursiveMember,
) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::UnsafeRecursiveRoot,
        SourceLabel::new(
            member.initializer.span,
            "this recursive data initializer has no fully applied constructor root",
        ),
    );
    diagnostic.related.push(SourceLabel::new(
        group.span,
        "this declaration is a simultaneous recursive group",
    ));
    diagnostic.related.push(SourceLabel::new(
        member.annotation.span,
        "this is the member's declared nominal type",
    ));
    TypeError::source(diagnostic)
}

fn unguarded_recursive_use(span: Span) -> TypeError {
    TypeError::source(Diagnostic::new(
        TypeReason::UnguardedRecursiveUse,
        SourceLabel::new(
            span,
            "a recursive occurrence crosses a forcing or transporting expression",
        ),
    ))
}

fn unsafe_recursive_initializer(
    group: &ResolvedRecursiveGroup,
    member: &crate::resolved::ResolvedRecursiveMember,
) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::UnsafeRecursiveInitializer,
        SourceLabel::new(
            member.initializer.span,
            "this recursive initializer is not a direct anonymous function",
        ),
    );
    diagnostic.related.push(SourceLabel::new(
        group.span,
        "this declaration is a simultaneous recursive group",
    ));
    diagnostic.related.push(SourceLabel::new(
        member.annotation.span,
        "this is the member's declared type",
    ));
    diagnostic.expected = Some("a direct `fn` initializer".into());
    diagnostic.help = Some("initialize the recursive member directly with `fn`".into());
    TypeError::source(diagnostic)
}

fn equational_origin(
    definition_span: Span,
    equational: &crate::resolved::ResolvedEquationalGlobal,
) -> Origin {
    let first = equational.equations.first();
    Origin::Related {
        primary: Box::new(Origin::Source(
            first.map_or(definition_span, |equation| equation.span),
        )),
        related: [
            definition_span,
            equational.interface.span,
            equational.interface.annotation.span,
        ]
        .into_iter()
        .chain(first.map(|equation| equation.body.span))
        .collect(),
    }
}

fn implementation_method_origin(
    implementation: &crate::resolved::ResolvedImplementation,
    group: &crate::resolved::ResolvedImplementationMethodGroup,
    method_span: Span,
    annotation_span: Span,
) -> Origin {
    let first = group.equations.first();
    Origin::Related {
        primary: Box::new(Origin::Source(
            first.map_or(group.span, |equation| equation.span),
        )),
        related: [
            implementation.span,
            group.span,
            method_span,
            annotation_span,
        ]
        .into_iter()
        .chain(first.map(|equation| equation.body.span))
        .collect(),
    }
}

fn implementation_method_core_origin(method: &CheckedImplementationMethodFact) -> Origin {
    // Linked evidence has already authenticated the complete cross-module
    // relation. Core retains only the implementation-local primary cause.
    Origin::Source(method.origin.primary_span())
}

fn operational_origin(
    definition_span: Span,
    operational: &crate::resolved::ResolvedInlineOperationalGlobal,
) -> Origin {
    Origin::Related {
        primary: Box::new(Origin::Source(definition_span)),
        related: vec![
            operational.header.span,
            operational
                .header
                .parameters
                .first()
                .map_or(operational.header.span, |parameter| {
                    parameter.annotation.span
                }),
            operational.header.result_type.span,
            operational.body.span,
        ],
    }
}

fn anonymous_function_origin(
    expression_span: Span,
    function: &crate::resolved::ResolvedFunctionExpr,
) -> Origin {
    Origin::Related {
        primary: Box::new(Origin::Source(expression_span)),
        related: vec![function.pattern.span, function.body.span],
    }
}

/// Applies the structural type-equality rule without inference or coercion.
#[must_use]
pub fn structurally_equal(left: &Type, right: &Type) -> bool {
    same_type(left, right)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PublicTypeAdmissionError {
    Invalid,
    Resource,
}

fn validate_and_charge_public_monotype(
    ty: &Type,
    registry: &ResolvedRegistry,
    budget: &mut TypeWorkBudget,
) -> Result<(), PublicTypeAdmissionError> {
    enum Task<'a> {
        Visit(&'a Type, usize, usize),
        Sequence(std::slice::Iter<'a, Type>, usize),
        Argument(&'a crate::types::KindedArgument, usize),
        Row(&'a EffectRow, usize),
    }
    fn push<'a>(
        work: &mut Vec<Task<'a>>,
        task: Task<'a>,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), PublicTypeAdmissionError> {
        budget
            .charge(1)
            .map_err(|()| PublicTypeAdmissionError::Resource)?;
        work.try_reserve(1)
            .map_err(|_| PublicTypeAdmissionError::Resource)?;
        work.push(task);
        Ok(())
    }
    let mut work = Vec::new();
    push(&mut work, Task::Visit(ty, 0, 0), budget)?;
    while let Some(task) = work.pop() {
        let (ty, depth, applied_arguments) = match task {
            Task::Visit(ty, depth, applied) => (ty, depth, applied),
            Task::Sequence(mut remaining, depth) => {
                if let Some(ty) = remaining.next() {
                    push(&mut work, Task::Sequence(remaining, depth), budget)?;
                    push(&mut work, Task::Visit(ty, depth, 0), budget)?;
                }
                continue;
            }
            Task::Argument(crate::types::KindedArgument::TypeArg(ty), depth) => {
                push(&mut work, Task::Visit(ty, depth, 0), budget)?;
                continue;
            }
            Task::Argument(crate::types::KindedArgument::RowArg(row), depth) => {
                push(&mut work, Task::Row(row, depth), budget)?;
                continue;
            }
            Task::Row(row, depth) => {
                if matches!(
                    row.tail().map(|tail| tail.variable()),
                    Some(EffectRowVariable::Inference(_))
                ) {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                for instance in row
                    .known()
                    .iter()
                    .chain(row.tail().into_iter().flat_map(|tail| tail.lacks()))
                {
                    for argument in instance.arguments().iter().rev() {
                        push(&mut work, Task::Argument(argument, depth), budget)?;
                    }
                }
                continue;
            }
        };
        let child_depth = depth
            .checked_add(1)
            .ok_or(PublicTypeAdmissionError::Invalid)?;
        match ty {
            Type::Tuple(elements) if applied_arguments == 0 => {
                if child_depth > CORE_PAYLOAD_DEPTH_LIMIT {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                push(
                    &mut work,
                    Task::Sequence(elements.iter(), child_depth),
                    budget,
                )?;
            }
            Type::ResourceApply(resource, arguments) if applied_arguments == 0 => {
                if child_depth > CORE_PAYLOAD_DEPTH_LIMIT {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                let signature = registry
                    .owner_signature(crate::resolved::OwnerId::Resource(*resource))
                    .ok_or(PublicTypeAdmissionError::Invalid)?;
                if signature.parameters.len() != arguments.len() {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                for (parameter, argument) in signature.parameters.iter().zip(arguments.iter()).rev()
                {
                    let parameter = registry
                        .type_variable(*parameter)
                        .ok_or(PublicTypeAdmissionError::Invalid)?;
                    if matches!(parameter.kind, Kind::EffectRow)
                        != matches!(argument, crate::types::KindedArgument::RowArg(_))
                    {
                        return Err(PublicTypeAdmissionError::Invalid);
                    }
                    push(&mut work, Task::Argument(argument, child_depth), budget)?;
                }
            }
            Type::Application(function, argument) => {
                if child_depth > CORE_PAYLOAD_DEPTH_LIMIT {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                push(&mut work, Task::Visit(argument, child_depth, 0), budget)?;
                push(
                    &mut work,
                    Task::Visit(
                        function,
                        depth,
                        applied_arguments
                            .checked_add(1)
                            .ok_or(PublicTypeAdmissionError::Invalid)?,
                    ),
                    budget,
                )?;
            }
            Type::Function(domain, codomain) if applied_arguments == 0 => {
                if child_depth > CORE_PAYLOAD_DEPTH_LIMIT {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                push(&mut work, Task::Visit(codomain, child_depth, 0), budget)?;
                push(&mut work, Task::Visit(domain, child_depth, 0), budget)?;
            }
            Type::EffectfulFunction(domain, codomain) if applied_arguments == 0 => {
                if child_depth > CORE_PAYLOAD_DEPTH_LIMIT {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
                push(
                    &mut work,
                    Task::Row(codomain.effects(), child_depth),
                    budget,
                )?;
                push(
                    &mut work,
                    Task::Visit(codomain.value(), child_depth, 0),
                    budget,
                )?;
                push(&mut work, Task::Visit(domain, child_depth, 0), budget)?;
            }
            Type::Tuple(_)
            | Type::ResourceApply(_, _)
            | Type::Function(_, _)
            | Type::EffectfulFunction(_, _)
            | Type::Inference(_)
            | Type::Forall(_, _) => return Err(PublicTypeAdmissionError::Invalid),
            Type::Nominal(id) => {
                let parameters = registry
                    .nominal_parameters(*id)
                    .ok_or(PublicTypeAdmissionError::Invalid)?;
                if parameters.len() != applied_arguments {
                    return Err(PublicTypeAdmissionError::Invalid);
                }
            }
            Type::Bytes
            | Type::String
            | Type::Int
            | Type::Bool
            | Type::Unit
            | Type::Variable(_)
                if applied_arguments == 0 => {}
            Type::Bytes
            | Type::String
            | Type::Int
            | Type::Bool
            | Type::Unit
            | Type::Variable(_) => {
                return Err(PublicTypeAdmissionError::Invalid);
            }
        }
    }
    Ok(())
}

fn clone_type_with_budget<B: crate::types::TypeWorkMeter>(
    ty: &Type,
    budget: &mut B,
) -> Result<Type, B::Error> {
    crate::types::clone_type_with_budget(ty, budget)
}

fn retain_implementation_capture_type(
    body_type: Type,
    parameters: &[(TypeVariableId, Kind)],
    budget: &mut TypeWorkBudget,
) -> Result<Type, TypeError> {
    let body_type = IterativeTypeOwner::new(body_type);
    let quantified = clone_kinded_type_parameters_with_budget(parameters, budget)
        .map_err(|()| type_resource())?;
    Ok(Type::Forall(
        quantified.into_boxed_slice(),
        Box::new(body_type.into_inner()),
    ))
}

fn retain_method_occurrence_parameters(
    interface_parameters: &[(TypeVariableId, Kind)],
    method_parameters: &[(TypeVariableId, Kind)],
    budget: &mut TypeWorkBudget,
) -> Result<(KindedTypeParameters, KindedTypeParameters), ()> {
    let parameter_count = interface_parameters
        .len()
        .checked_add(method_parameters.len())
        .ok_or(())?;
    budget.charge(parameter_count)?;
    let mut fact_parameters = Vec::new();
    fact_parameters
        .try_reserve(parameter_count)
        .map_err(|_| ())?;
    for (identity, kind) in interface_parameters {
        fact_parameters.push((*identity, clone_kind_with_budget(kind, budget)?));
    }
    for (identity, kind) in method_parameters {
        fact_parameters.push((*identity, clone_kind_with_budget(kind, budget)?));
    }

    // The Core scheme retains a distinct Forall wrapper, binder record, and
    // Kind copy from the elaboration fact above.
    budget.charge(parameter_count.checked_add(1).ok_or(())?)?;
    let mut scheme_parameters = Vec::new();
    scheme_parameters
        .try_reserve(parameter_count)
        .map_err(|_| ())?;
    for (identity, kind) in interface_parameters {
        scheme_parameters.push((*identity, clone_kind_with_budget(kind, budget)?));
    }
    for (identity, kind) in method_parameters {
        scheme_parameters.push((*identity, clone_kind_with_budget(kind, budget)?));
    }

    Ok((
        fact_parameters.into_boxed_slice(),
        scheme_parameters.into_boxed_slice(),
    ))
}

fn same_interface_application_with_budget(
    left: &InterfaceApplication,
    right: &InterfaceApplication,
    budget: &mut TypeWorkBudget,
) -> Result<bool, TypeError> {
    if left.interface() != right.interface() || left.arguments().len() != right.arguments().len() {
        return Ok(false);
    }
    for (left, right) in left.arguments().iter().zip(right.arguments()) {
        let same = match (left, right) {
            (
                crate::types::KindedArgument::TypeArg(left),
                crate::types::KindedArgument::TypeArg(right),
            ) => same_type_with_budget(left, right, budget),
            _ => crate::types::same_kinded_argument_with_budget(left, right, budget),
        }
        .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        if !same {
            return Ok(false);
        }
    }
    Ok(true)
}

fn charge_pattern_binder_storage(ty: &Type, budget: &mut TypeWorkBudget) -> Result<(), ()> {
    charge_type_cells(ty, budget)?;
    charge_type_cells(ty, budget)?;
    charge_type_provenance_nodes(ty, budget)?;
    budget.charge(2)?;
    Ok(())
}

fn reserve_context_entry(context: &mut TypeContext, budget: &mut TypeWorkBudget) -> Result<(), ()> {
    budget.charge(1)?;
    context.binders.try_reserve(1).map_err(|_| ())
}

fn charge_type_provenance_nodes(ty: &Type, budget: &mut TypeWorkBudget) -> Result<(), ()> {
    let mut work = vec![ty];
    while let Some(ty) = work.pop() {
        budget.charge(1)?;
        match ty {
            Type::Function(domain, codomain) | Type::Application(domain, codomain) => {
                work.push(codomain);
                work.push(domain);
            }
            _ => {}
        }
    }
    Ok(())
}

fn unknown_provenance_with_budget(
    ty: &Type,
    budget: &mut TypeWorkBudget,
) -> Result<TypeProvenance, ()> {
    charge_type_provenance_nodes(ty, budget)?;
    Ok(TypeProvenance::unknown(ty))
}

fn at_span_provenance_with_budget(
    ty: &Type,
    span: Span,
    budget: &mut TypeWorkBudget,
) -> Result<TypeProvenance, ()> {
    charge_type_provenance_nodes(ty, budget)?;
    Ok(TypeProvenance::at_span(ty, span))
}

fn constructor_replacements_with_budget(
    parameters: &[crate::resolved::ResolvedTypeVariable],
    arguments: &[&Type],
    budget: &mut TypeWorkBudget,
) -> Result<TypeReplacementBuffer, ()> {
    if parameters.len() != arguments.len() {
        return Err(());
    }
    budget.charge(arguments.len())?;
    for argument in arguments {
        charge_type_cells(argument, budget)?;
    }
    let mut replacements = TypeReplacementBuffer::new();
    replacements.try_reserve(arguments.len()).map_err(|_| ())?;
    for (parameter, argument) in parameters.iter().zip(arguments) {
        replacements.try_insert_unique(parameter.id, zonk_type(argument, &HashMap::new()))?;
    }
    Ok(replacements)
}

fn compare_concrete_types(
    left: &Type,
    right: &Type,
    budget: &mut TypeWorkBudget,
) -> Result<Option<bool>, ()> {
    // None here requests structural traversal; Some(None) leaves normalization
    // to the shared Type/argument/row engine. Leaf pairs need no work storage.
    fn classify(left: &Type, right: &Type) -> Option<Option<bool>> {
        match (left, right) {
            (Type::Inference(_) | Type::Forall(_, _), _)
            | (_, Type::Inference(_) | Type::Forall(_, _))
            | (Type::EffectfulFunction(_, _) | Type::ResourceApply(_, _), _)
            | (_, Type::EffectfulFunction(_, _) | Type::ResourceApply(_, _)) => Some(None),
            (Type::Bytes, Type::Bytes)
            | (Type::String, Type::String)
            | (Type::Int, Type::Int)
            | (Type::Bool, Type::Bool)
            | (Type::Unit, Type::Unit) => Some(Some(true)),
            (Type::Nominal(left), Type::Nominal(right)) => Some(Some(left == right)),
            (Type::Variable(left), Type::Variable(right)) => Some(Some(left == right)),
            (Type::Tuple(left), Type::Tuple(right)) if left.len() == right.len() => None,
            (Type::Application(_, _), Type::Application(_, _))
            | (Type::Function(_, _), Type::Function(_, _)) => None,
            _ => Some(Some(false)),
        }
    }
    enum Task<'a> {
        Pair(&'a Type, &'a Type),
        Sequence(std::slice::Iter<'a, Type>, std::slice::Iter<'a, Type>),
    }

    budget.charge(2)?;
    if let Some(result) = classify(left, right) {
        return Ok(result);
    }
    let mut work = Vec::new();
    work.try_reserve(1).map_err(|_| ())?;
    work.push(Task::Pair(left, right));
    let mut first_pair = true;
    while let Some(task) = work.pop() {
        let (left, right) = match task {
            Task::Pair(left, right) => {
                if first_pair {
                    first_pair = false;
                } else {
                    budget.charge(2)?;
                }
                (left, right)
            }
            Task::Sequence(mut left_types, mut right_types) => {
                match (left_types.next(), right_types.next()) {
                    (Some(left), Some(right)) => {
                        // The tuple pair, then each preceding charged child
                        // pair, admits these two bounded successor slots.
                        work.try_reserve(2).map_err(|_| ())?;
                        work.push(Task::Sequence(left_types, right_types));
                        work.push(Task::Pair(left, right));
                        continue;
                    }
                    (None, None) => continue,
                    _ => return Ok(Some(false)),
                }
            }
        };
        if let Some(result) = classify(left, right) {
            match result {
                Some(true) => continue,
                other => return Ok(other),
            }
        }
        // Two admitted operand cells cover at most two retained successor
        // tasks. Every allocation remains fallible without charging twice.
        match (left, right) {
            (Type::Tuple(left), Type::Tuple(right)) => {
                work.try_reserve(1).map_err(|_| ())?;
                work.push(Task::Sequence(left.iter(), right.iter()));
            }
            (
                Type::Application(left_function, left_argument),
                Type::Application(right_function, right_argument),
            ) => {
                work.try_reserve(2).map_err(|_| ())?;
                work.push(Task::Pair(left_argument, right_argument));
                work.push(Task::Pair(left_function, right_function));
            }
            (
                Type::Function(left_domain, left_codomain),
                Type::Function(right_domain, right_codomain),
            ) => {
                work.try_reserve(2).map_err(|_| ())?;
                work.push(Task::Pair(left_codomain, right_codomain));
                work.push(Task::Pair(left_domain, right_domain));
            }
            _ => unreachable!("only structural concrete pairs request traversal"),
        }
    }
    Ok(Some(true))
}

fn clone_function_parts_with_budget(
    ty: &Type,
    budget: &mut TypeWorkBudget,
) -> Result<(Type, Type), ()> {
    let function = ty.function_view().ok_or(())?;
    let domain = function.domain();
    let codomain = function.value();
    charge_type_cells(domain, budget)?;
    charge_type_cells(codomain, budget)?;
    let solutions = HashMap::new();
    Ok((
        zonk_type(domain, &solutions),
        zonk_type(codomain, &solutions),
    ))
}

fn unification_type_error(error: TypeError) -> UnificationFailure {
    match error {
        TypeError::Internal(ElaborationFailure::TypeResourceExhausted) => {
            UnificationFailure::Resource
        }
        TypeError::Internal(ElaborationFailure::Kind { context, span }) => {
            UnificationFailure::Kind { context, span }
        }
        _ => UnificationFailure::Invariant,
    }
}

/// Owned roots entering the same alternating unification work stack.
/// Only the ordinary Type entry has already compared and normalized its roots.
enum OwnedUnificationEntry {
    Arguments(
        crate::types::IterativeArgumentOwner,
        crate::types::IterativeArgumentOwner,
    ),
    ComparedTypes(IterativeTypeOwner, IterativeTypeOwner),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum UnificationFailure {
    Mismatch,
    RowExclusion,
    Infinite,
    Resource,
    Invariant,
    Kind {
        context: crate::kind::KindFailureContext,
        span: Option<Span>,
    },
}

#[cfg(test)]
std::thread_local! {
    static ZONK_REBUILD_PENDING_PEAK: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static OCCURS_PENDING_PEAK: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static SOLUTION_KIND_AUTHENTICATIONS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static TEST_INITIAL_TYPED_NODES: std::cell::RefCell<Vec<TypedNode>> = const {
        std::cell::RefCell::new(Vec::new())
    };
}

#[cfg(test)]
fn record_zonk_rebuild_pending(pending: usize) {
    ZONK_REBUILD_PENDING_PEAK.with(|peak| peak.set(peak.get().max(pending)));
}

#[cfg(test)]
fn record_occurs_pending(pending: usize) {
    OCCURS_PENDING_PEAK.with(|peak| peak.set(peak.get().max(pending)));
}

enum ZonkWork {
    TypeCells(usize),
    Inference(InferenceVariableId),
    RowInference,
}

#[cfg(test)]
fn zonk_type_with_status<E>(
    ty: &Type,
    solutions: &HashMap<InferenceVariableId, Type>,
    mut charge: impl FnMut(usize) -> Result<(), E>,
) -> Result<(Type, bool), E> {
    zonk_type_with_status_and_inference(ty, solutions, |work| match work {
        ZonkWork::TypeCells(cells) => charge(cells),
        ZonkWork::Inference(_) | ZonkWork::RowInference => Ok(()),
    })
}

fn zonk_selection_argument(
    argument: crate::types::KindedArgument,
    solutions: &HashMap<InferenceVariableId, Type>,
    rows: &HashMap<InferenceVariableId, EffectRow>,
    inference_variables: &InferenceVariableRegistry,
    authenticated_solutions: &HashSet<InferenceVariableId>,
    budget: &mut TypeWorkBudget,
) -> Result<crate::types::KindedArgument, SelectionFailure> {
    let argument = crate::types::IterativeArgumentOwner::new(argument);
    let mut charge = |work| match work {
        ZonkWork::TypeCells(cells) => budget
            .charge(cells)
            .map_err(|()| SelectionFailure::TypeResource),
        ZonkWork::RowInference => Ok(()),
        ZonkWork::Inference(identity) => authenticate_zonk_inference_occurrence(
            identity,
            inference_variables,
            solutions,
            authenticated_solutions,
            budget,
        )
        .map_err(|failure| match failure {
            UnificationFailure::Kind { context, span } => SelectionFailure::Kind { context, span },
            UnificationFailure::Resource => SelectionFailure::TypeResource,
            _ => SelectionFailure::InvalidState,
        }),
    };
    let (root, _, _) = zonk_root_with_status_and_inference_and_rows(
        BorrowedZonkRoot::Argument(&argument),
        solutions,
        &mut charge,
    )?;
    // The shared borrowed rebuild already normalizes every row's known and
    // lacks members and authenticates each Type inference occurrence. Without
    // row solutions, substitution cannot expose another Type occurrence.
    if rows.is_empty() {
        return match root {
            OwnedZonkRoot::Argument(argument) => Ok(argument),
            OwnedZonkRoot::Type(ty) => {
                drop(IterativeTypeOwner::new(ty));
                Err(SelectionFailure::InvalidState)
            }
        };
    }
    let root = zonk_owned_root_with_rows(root, &HashMap::new(), rows, &mut |cells| {
        charge(ZonkWork::TypeCells(cells))
    })?;
    let argument = match root {
        OwnedZonkRoot::Argument(argument) => crate::types::IterativeArgumentOwner::new(argument),
        OwnedZonkRoot::Type(ty) => {
            drop(IterativeTypeOwner::new(ty));
            return Err(SelectionFailure::InvalidState);
        }
    };
    let (root, _, _) = zonk_root_with_status_and_inference_and_rows(
        BorrowedZonkRoot::Argument(&argument),
        solutions,
        charge,
    )?;
    match root {
        OwnedZonkRoot::Argument(argument) => Ok(argument),
        OwnedZonkRoot::Type(ty) => {
            drop(IterativeTypeOwner::new(ty));
            Err(SelectionFailure::InvalidState)
        }
    }
}

#[cfg(test)]
fn zonk_type_with_status_and_inference<E>(
    ty: &Type,
    solutions: &HashMap<InferenceVariableId, Type>,
    work_charge: impl FnMut(ZonkWork) -> Result<(), E>,
) -> Result<(Type, bool), E> {
    let (ty, unresolved, _) =
        zonk_type_with_status_and_inference_and_rows(ty, solutions, work_charge)?;
    Ok((ty, unresolved))
}

#[derive(Clone, Copy)]
enum BorrowedZonkRoot<'a> {
    Type(&'a Type),
    Argument(&'a crate::types::KindedArgument),
}

fn zonk_type_with_status_and_inference_and_rows<E>(
    ty: &Type,
    solutions: &HashMap<InferenceVariableId, Type>,
    work_charge: impl FnMut(ZonkWork) -> Result<(), E>,
) -> Result<(Type, bool, bool), E> {
    let (root, unresolved, has_rows) = zonk_root_with_status_and_inference_and_rows(
        BorrowedZonkRoot::Type(ty),
        solutions,
        work_charge,
    )?;
    match root {
        OwnedZonkRoot::Type(ty) => Ok((ty, unresolved, has_rows)),
        OwnedZonkRoot::Argument(argument) => {
            drop(crate::types::IterativeArgumentOwner::new(argument));
            unreachable!("zonk root preserves its Type tag")
        }
    }
}

fn zonk_root_with_status_and_inference_and_rows<E>(
    root: BorrowedZonkRoot<'_>,
    solutions: &HashMap<InferenceVariableId, Type>,
    mut work_charge: impl FnMut(ZonkWork) -> Result<(), E>,
) -> Result<(OwnedZonkRoot, bool, bool), E> {
    // Transparent inference aliases and scalar leaves need no reconstruction
    // storage. Authenticate every alias in the same order as the worklist,
    // keeping its larger compound frame off bounded pattern/body call stacks.
    let mut root = root;
    if let BorrowedZonkRoot::Type(mut ty) = root {
        loop {
            if let Type::Inference(identity) = ty {
                if let Some(solution) = solutions.get(identity) {
                    #[cfg(test)]
                    record_zonk_rebuild_pending(1);
                    work_charge(ZonkWork::Inference(*identity))?;
                    ty = solution;
                    continue;
                }
                work_charge(ZonkWork::TypeCells(1))?;
                #[cfg(test)]
                record_zonk_rebuild_pending(1);
                work_charge(ZonkWork::Inference(*identity))?;
                return Ok((OwnedZonkRoot::Type(Type::Inference(*identity)), true, false));
            }
            let leaf = match ty {
                Type::Bytes => Some(Type::Bytes),
                Type::String => Some(Type::String),
                Type::Int => Some(Type::Int),
                Type::Bool => Some(Type::Bool),
                Type::Unit => Some(Type::Unit),
                Type::Nominal(id) => Some(Type::Nominal(*id)),
                Type::Variable(id) => Some(Type::Variable(*id)),
                _ => None,
            };
            if let Some(leaf) = leaf {
                work_charge(ZonkWork::TypeCells(1))?;
                #[cfg(test)]
                record_zonk_rebuild_pending(1);
                return Ok((OwnedZonkRoot::Type(leaf), false, false));
            }
            root = BorrowedZonkRoot::Type(ty);
            break;
        }
    }
    zonk_compound_root_with_status_and_inference_and_rows(root, solutions, work_charge)
}

#[inline(never)]
fn zonk_compound_root_with_status_and_inference_and_rows<E>(
    root: BorrowedZonkRoot<'_>,
    solutions: &HashMap<InferenceVariableId, Type>,
    mut work_charge: impl FnMut(ZonkWork) -> Result<(), E>,
) -> Result<(OwnedZonkRoot, bool, bool), E> {
    use crate::types::{IterativeArgumentOwner, KindedArgument};
    enum Value {
        Type(IterativeTypeOwner),
        Argument(IterativeArgumentOwner),
        Row(EffectRow),
        Instance(EffectInstance),
    }
    impl Value {
        fn ty(ty: Type) -> Self {
            Self::Type(IterativeTypeOwner::new(ty))
        }
        fn into_type(self) -> Type {
            match self {
                Self::Type(ty) => ty.into_inner(),
                _ => unreachable!("zonk Type result"),
            }
        }
        fn into_argument(self) -> KindedArgument {
            match self {
                Self::Argument(arg) => arg.into_inner(),
                _ => unreachable!("zonk argument result"),
            }
        }
        fn into_row(self) -> EffectRow {
            match self {
                Self::Row(row) => row,
                _ => unreachable!("zonk row result"),
            }
        }
        fn into_instance(self) -> EffectInstance {
            match self {
                Self::Instance(instance) => instance,
                _ => unreachable!("zonk instance result"),
            }
        }
    }
    struct Parameters(Option<Box<[(TypeVariableId, Kind)]>>);
    impl Drop for Parameters {
        fn drop(&mut self) {
            if let Some(parameters) = self.0.take() {
                for (_, kind) in parameters.into_vec() {
                    drop(kind);
                }
            }
        }
    }
    enum Task<'a> {
        Type(&'a Type),
        Argument(&'a KindedArgument),
        Row(&'a EffectRow),
        Instance(&'a EffectInstance),
        Types(std::slice::Iter<'a, Type>),
        Arguments(std::slice::Iter<'a, KindedArgument>),
        Instances(std::slice::Iter<'a, EffectInstance>),
        Tuple(usize),
        Resource(crate::types::ResourceDefinitionId, usize),
        InstanceResult(crate::types::EffectId, usize),
        Application,
        Function,
        EffectfulFunction,
        TypeArgument,
        RowArgument,
        RowResult(usize, Option<(EffectRowVariable, usize)>),
        Forall(Parameters),
    }
    fn allocation<E>(charge: &mut impl FnMut(ZonkWork) -> Result<(), E>) -> E {
        crate::types::allocation_error(&mut |cells| charge(ZonkWork::TypeCells(cells)))
    }
    fn schedule<'a, E>(
        work: &mut Vec<Task<'a>>,
        task: Task<'a>,
        charge: &mut impl FnMut(ZonkWork) -> Result<(), E>,
    ) -> Result<(), E> {
        work.try_reserve(1).map_err(|_| allocation(charge))?;
        work.push(task);
        Ok(())
    }
    fn retain<E>(
        values: &mut Vec<Value>,
        value: Value,
        charge: &mut impl FnMut(ZonkWork) -> Result<(), E>,
    ) -> Result<(), E> {
        values.try_reserve(1).map_err(|_| allocation(charge))?;
        values.push(value);
        Ok(())
    }
    fn suffix<E>(
        values: &mut Vec<Value>,
        count: usize,
        charge: &mut impl FnMut(ZonkWork) -> Result<(), E>,
    ) -> Result<Vec<Value>, E> {
        let mut result = Vec::new();
        result
            .try_reserve_exact(count)
            .map_err(|_| allocation(charge))?;
        result.extend(values.drain(values.len().checked_sub(count).expect("zonk child count")..));
        Ok(result)
    }
    fn clone_kind<E>(
        root: &Kind,
        charge: &mut impl FnMut(ZonkWork) -> Result<(), E>,
    ) -> Result<Kind, E> {
        enum KindTask<'a> {
            Visit(&'a Kind),
            Arrow,
        }
        let mut work = Vec::new();
        let mut values = Vec::new();
        work.try_reserve(1).map_err(|_| allocation(charge))?;
        work.push(KindTask::Visit(root));
        while let Some(task) = work.pop() {
            if matches!(task, KindTask::Visit(_)) {
                charge(ZonkWork::TypeCells(1))?;
            }
            match task {
                KindTask::Visit(Kind::Arrow(domain, value)) => {
                    work.try_reserve(3).map_err(|_| allocation(charge))?;
                    work.push(KindTask::Arrow);
                    work.push(KindTask::Visit(value));
                    work.push(KindTask::Visit(domain));
                }
                KindTask::Visit(kind) => {
                    values.try_reserve(1).map_err(|_| allocation(charge))?;
                    values.push(match kind {
                        Kind::Type => Kind::Type,
                        Kind::EffectRow => Kind::EffectRow,
                        _ => unreachable!(),
                    });
                }
                KindTask::Arrow => {
                    let value = values.pop().expect("Kind codomain");
                    let domain = values.pop().expect("Kind domain");
                    values.try_reserve(1).map_err(|_| allocation(charge))?;
                    values.push(Kind::Arrow(Box::new(domain), Box::new(value)));
                }
            }
        }
        Ok(values.pop().expect("Kind root"))
    }
    let mut work = Vec::new();
    let mut values = Vec::new();
    schedule(
        &mut work,
        match root {
            BorrowedZonkRoot::Type(ty) => Task::Type(ty),
            BorrowedZonkRoot::Argument(arg) => Task::Argument(arg),
        },
        &mut work_charge,
    )?;
    let mut unresolved = false;
    let mut has_rows = false;
    while let Some(task) = work.pop() {
        // One expanded graph cell pays its constant number of fallible task
        // and result slots. Sequence frames reuse that admission; collection
        // storage is bounded by the already charged child cells. Solved Type
        // aliases use their inference authentication charge and the expanded
        // solution's cells, preserving the ordinary Type accounting contract.
        match &task {
            Task::Type(Type::Inference(identity)) if solutions.contains_key(identity) => {}
            Task::Type(_) | Task::Argument(_) | Task::Row(_) | Task::Instance(_) => {
                work_charge(ZonkWork::TypeCells(1))?
            }
            _ => {}
        }
        #[cfg(test)]
        record_zonk_rebuild_pending(work.len().saturating_add(1));
        match task {
            Task::Type(Type::Inference(identity)) => {
                work_charge(ZonkWork::Inference(*identity))?;
                if let Some(solution) = solutions.get(identity) {
                    schedule(&mut work, Task::Type(solution), &mut work_charge)?;
                } else {
                    unresolved = true;
                    retain(
                        &mut values,
                        Value::ty(Type::Inference(*identity)),
                        &mut work_charge,
                    )?;
                }
            }
            Task::Type(Type::Bytes) => {
                retain(&mut values, Value::ty(Type::Bytes), &mut work_charge)?
            }
            Task::Type(Type::String) => {
                retain(&mut values, Value::ty(Type::String), &mut work_charge)?
            }
            Task::Type(Type::Int) => retain(&mut values, Value::ty(Type::Int), &mut work_charge)?,
            Task::Type(Type::Bool) => retain(&mut values, Value::ty(Type::Bool), &mut work_charge)?,
            Task::Type(Type::Unit) => retain(&mut values, Value::ty(Type::Unit), &mut work_charge)?,
            Task::Type(Type::Nominal(id)) => {
                retain(&mut values, Value::ty(Type::Nominal(*id)), &mut work_charge)?
            }
            Task::Type(Type::Variable(id)) => retain(
                &mut values,
                Value::ty(Type::Variable(*id)),
                &mut work_charge,
            )?,
            Task::Type(Type::Tuple(elements)) => {
                schedule(&mut work, Task::Tuple(elements.len()), &mut work_charge)?;
                schedule(&mut work, Task::Types(elements.iter()), &mut work_charge)?;
            }
            Task::Type(Type::ResourceApply(id, arguments)) => {
                schedule(
                    &mut work,
                    Task::Resource(*id, arguments.len()),
                    &mut work_charge,
                )?;
                schedule(
                    &mut work,
                    Task::Arguments(arguments.iter()),
                    &mut work_charge,
                )?;
            }
            Task::Type(Type::Application(function, argument)) => {
                schedule(&mut work, Task::Application, &mut work_charge)?;
                schedule(&mut work, Task::Type(argument), &mut work_charge)?;
                schedule(&mut work, Task::Type(function), &mut work_charge)?;
            }
            Task::Type(Type::Function(domain, value)) => {
                schedule(&mut work, Task::Function, &mut work_charge)?;
                schedule(&mut work, Task::Type(value), &mut work_charge)?;
                schedule(&mut work, Task::Type(domain), &mut work_charge)?;
            }
            Task::Type(Type::EffectfulFunction(domain, computation)) => {
                schedule(&mut work, Task::EffectfulFunction, &mut work_charge)?;
                schedule(
                    &mut work,
                    Task::Row(computation.effects()),
                    &mut work_charge,
                )?;
                schedule(&mut work, Task::Type(computation.value()), &mut work_charge)?;
                schedule(&mut work, Task::Type(domain), &mut work_charge)?;
            }
            Task::Type(Type::Forall(parameters, body)) => {
                work_charge(ZonkWork::TypeCells(parameters.len()))?;
                let mut copied = Vec::new();
                copied
                    .try_reserve_exact(parameters.len())
                    .map_err(|_| allocation(&mut work_charge))?;
                for (id, kind) in parameters {
                    copied.push((*id, clone_kind(kind, &mut work_charge)?));
                }
                let parameters = Parameters(Some(copied.into_boxed_slice()));
                schedule(&mut work, Task::Forall(parameters), &mut work_charge)?;
                schedule(&mut work, Task::Type(body), &mut work_charge)?;
            }
            Task::Argument(KindedArgument::TypeArg(ty)) => {
                schedule(&mut work, Task::TypeArgument, &mut work_charge)?;
                schedule(&mut work, Task::Type(ty), &mut work_charge)?;
            }
            Task::Argument(KindedArgument::RowArg(row)) => {
                schedule(&mut work, Task::RowArgument, &mut work_charge)?;
                schedule(&mut work, Task::Row(row), &mut work_charge)?;
            }
            Task::Instance(instance) => {
                schedule(
                    &mut work,
                    Task::InstanceResult(instance.effect(), instance.arguments().len()),
                    &mut work_charge,
                )?;
                schedule(
                    &mut work,
                    Task::Arguments(instance.arguments().iter()),
                    &mut work_charge,
                )?;
            }
            Task::Row(row) => {
                has_rows = true;
                if row
                    .tail()
                    .is_some_and(|tail| matches!(tail.variable(), EffectRowVariable::Inference(_)))
                {
                    work_charge(ZonkWork::RowInference)?;
                }
                if row.tail().is_some() {
                    work_charge(ZonkWork::TypeCells(1))?;
                }
                schedule(
                    &mut work,
                    Task::RowResult(
                        row.known().len(),
                        row.tail().map(|tail| (tail.variable(), tail.lacks().len())),
                    ),
                    &mut work_charge,
                )?;
                if let Some(tail) = row.tail() {
                    schedule(
                        &mut work,
                        Task::Instances(tail.lacks().iter()),
                        &mut work_charge,
                    )?;
                }
                schedule(
                    &mut work,
                    Task::Instances(row.known().iter()),
                    &mut work_charge,
                )?;
            }
            Task::Types(mut sequence) => {
                if let Some(ty) = sequence.next() {
                    schedule(&mut work, Task::Types(sequence), &mut work_charge)?;
                    schedule(&mut work, Task::Type(ty), &mut work_charge)?;
                }
            }
            Task::Arguments(mut sequence) => {
                if let Some(arg) = sequence.next() {
                    schedule(&mut work, Task::Arguments(sequence), &mut work_charge)?;
                    schedule(&mut work, Task::Argument(arg), &mut work_charge)?;
                }
            }
            Task::Instances(mut sequence) => {
                if let Some(instance) = sequence.next() {
                    schedule(&mut work, Task::Instances(sequence), &mut work_charge)?;
                    schedule(&mut work, Task::Instance(instance), &mut work_charge)?;
                }
            }
            Task::Application | Task::Function => {
                let right = values.pop().expect("zonk right child");
                let left = values.pop().expect("zonk left child");
                let ty = if matches!(task, Task::Application) {
                    Type::Application(Box::new(left.into_type()), Box::new(right.into_type()))
                } else {
                    Type::Function(Box::new(left.into_type()), Box::new(right.into_type()))
                };
                retain(&mut values, Value::ty(ty), &mut work_charge)?;
            }
            Task::EffectfulFunction => {
                let row = values.pop().expect("zonk effects").into_row();
                let value = values.pop().expect("zonk value");
                let domain = values.pop().expect("zonk domain");
                retain(
                    &mut values,
                    Value::ty(Type::function_computation(
                        domain.into_type(),
                        ComputationType::new(value.into_type(), row),
                    )),
                    &mut work_charge,
                )?;
            }
            Task::TypeArgument => {
                let ty = values.pop().expect("zonk TypeArg").into_type();
                retain(
                    &mut values,
                    Value::Argument(IterativeArgumentOwner::new(KindedArgument::TypeArg(ty))),
                    &mut work_charge,
                )?;
            }
            Task::RowArgument => {
                let row = values.pop().expect("zonk RowArg").into_row();
                retain(
                    &mut values,
                    Value::Argument(IterativeArgumentOwner::new(KindedArgument::RowArg(row))),
                    &mut work_charge,
                )?;
            }
            Task::Tuple(count) => {
                let staged = suffix(&mut values, count, &mut work_charge)?;
                let mut elements = Vec::new();
                elements
                    .try_reserve_exact(count)
                    .map_err(|_| allocation(&mut work_charge))?;
                elements.extend(staged.into_iter().map(Value::into_type));
                retain(
                    &mut values,
                    Value::ty(Type::Tuple(elements.into_boxed_slice())),
                    &mut work_charge,
                )?;
            }
            Task::Resource(id, count) => {
                let staged = suffix(&mut values, count, &mut work_charge)?;
                let mut arguments = Vec::new();
                arguments
                    .try_reserve_exact(count)
                    .map_err(|_| allocation(&mut work_charge))?;
                arguments.extend(staged.into_iter().map(Value::into_argument));
                retain(
                    &mut values,
                    Value::ty(Type::ResourceApply(id, arguments.into_boxed_slice())),
                    &mut work_charge,
                )?;
            }
            Task::InstanceResult(id, count) => {
                let staged = suffix(&mut values, count, &mut work_charge)?;
                let mut arguments = Vec::new();
                arguments
                    .try_reserve_exact(count)
                    .map_err(|_| allocation(&mut work_charge))?;
                arguments.extend(staged.into_iter().map(Value::into_argument));
                retain(
                    &mut values,
                    Value::Instance(EffectInstance::new_kinded(id, arguments.into_boxed_slice())),
                    &mut work_charge,
                )?;
            }

            Task::RowResult(known, tail) => {
                let count = known
                    .checked_add(tail.map_or(0, |(_, n)| n))
                    .ok_or_else(|| allocation(&mut work_charge))?;
                let staged = suffix(&mut values, count, &mut work_charge)?;
                let mut instances = Vec::new();
                instances
                    .try_reserve_exact(count)
                    .map_err(|_| allocation(&mut work_charge))?;
                instances.extend(staged.into_iter().map(Value::into_instance));
                let lacks_count = count - known;
                let mut lacks = Vec::new();
                lacks
                    .try_reserve_exact(lacks_count)
                    .map_err(|_| allocation(&mut work_charge))?;
                lacks.extend(instances.drain(known..));
                let row = effect_row_from_owned_parts_with_budget(
                    instances,
                    tail.map(|(variable, _)| (variable, lacks)),
                    &mut |cells| work_charge(ZonkWork::TypeCells(cells)),
                )?;
                retain(&mut values, Value::Row(row), &mut work_charge)?;
            }
            Task::Forall(mut parameters) => {
                let body = values.pop().expect("zonk forall body");
                retain(
                    &mut values,
                    Value::ty(Type::Forall(
                        parameters.0.take().expect("parameters transfer once"),
                        Box::new(body.into_type()),
                    )),
                    &mut work_charge,
                )?;
            }
        }
    }
    let root = match values.pop().expect("zonk root result") {
        Value::Type(ty) => OwnedZonkRoot::Type(ty.into_inner()),
        Value::Argument(arg) => OwnedZonkRoot::Argument(arg.into_inner()),
        _ => unreachable!("zonk root preserves category"),
    };
    assert!(values.is_empty(), "one zonk root result");
    Ok((root, unresolved, has_rows))
}

fn zonk_type(ty: &Type, solutions: &HashMap<InferenceVariableId, Type>) -> Type {
    let mut budget = TypeWorkBudget::unbounded();
    let owned = clone_type_with_budget(ty, &mut budget)
        .expect("an in-memory type can be cloned under an unbounded ledger");
    zonk_owned_type_with_rows(owned, solutions, &HashMap::new(), &mut budget)
        .expect("an in-memory type can be zonked under an unbounded ledger")
}

enum OwnedZonkRoot {
    Type(Type),
    Argument(crate::types::KindedArgument),
}

fn zonk_owned_type_with_rows(
    ty: Type,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    budget: &mut TypeWorkBudget,
) -> Result<Type, ()> {
    match zonk_owned_root_with_rows(OwnedZonkRoot::Type(ty), solutions, row_solutions, budget)? {
        OwnedZonkRoot::Type(ty) => Ok(ty),
        OwnedZonkRoot::Argument(argument) => {
            drop(crate::types::IterativeArgumentOwner::new(argument));
            Err(())
        }
    }
}

fn zonk_owned_argument_with_rows(
    argument: crate::types::KindedArgument,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    budget: &mut TypeWorkBudget,
) -> Result<crate::types::KindedArgument, ()> {
    match zonk_owned_root_with_rows(
        OwnedZonkRoot::Argument(argument),
        solutions,
        row_solutions,
        budget,
    )? {
        OwnedZonkRoot::Argument(argument) => Ok(argument),
        OwnedZonkRoot::Type(ty) => {
            drop(IterativeTypeOwner::new(ty));
            Err(())
        }
    }
}

#[allow(
    clippy::type_complexity,
    reason = "the local traversal shape mirrors the effect-row carrier without a public alias"
)]
fn zonk_owned_root_with_rows<B: crate::types::TypeWorkMeter>(
    root: OwnedZonkRoot,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    budget: &mut B,
) -> Result<OwnedZonkRoot, B::Error> {
    enum Value {
        Type(IterativeTypeOwner),
        Argument(crate::types::IterativeArgumentOwner),
        Row(EffectRow),
    }
    impl Value {
        fn ty(ty: Type) -> Self {
            Self::Type(IterativeTypeOwner::new(ty))
        }
        fn argument(argument: crate::types::KindedArgument) -> Self {
            Self::Argument(crate::types::IterativeArgumentOwner::new(argument))
        }
        fn into_type(self) -> Type {
            match self {
                Self::Type(ty) => ty.into_inner(),
                _ => panic!("zonk Type shape"),
            }
        }
        fn into_argument(self) -> crate::types::KindedArgument {
            match self {
                Self::Argument(argument) => argument.into_inner(),
                _ => panic!("zonk argument shape"),
            }
        }
        fn into_row(self) -> EffectRow {
            match self {
                Self::Row(row) => row,
                _ => panic!("zonk row shape"),
            }
        }
    }
    struct RowShape {
        known: Vec<(crate::types::EffectId, usize)>,
        tail: Option<(EffectRowVariable, Vec<(crate::types::EffectId, usize)>)>,
        arguments: usize,
    }
    enum Task {
        Visit(Value),
        Sequence(std::vec::IntoIter<Value>),
        Tuple(usize),
        Application,
        Function,
        EffectfulFunction,
        Resource(crate::types::ResourceDefinitionId, usize),
        TypeArgument,
        RowArgument,
        Row(RowShape),
        Forall(Box<[(TypeVariableId, Kind)]>),
    }
    fn schedule<B: crate::types::TypeWorkMeter>(
        work: &mut Vec<Task>,
        task: Task,
        budget: &mut B,
    ) -> Result<(), B::Error> {
        // Task owns guarded fragments even when either admission refuses.
        budget.charge(1)?;
        work.try_reserve(1)
            .map_err(|_| crate::types::allocation_error(budget))?;
        work.push(task);
        Ok(())
    }
    fn retain<B: crate::types::TypeWorkMeter>(
        values: &mut Vec<Value>,
        value: Value,
        budget: &mut B,
    ) -> Result<(), B::Error> {
        budget.charge(1)?;
        values
            .try_reserve(1)
            .map_err(|_| crate::types::allocation_error(budget))?;
        values.push(value);
        Ok(())
    }
    fn suffix<B: crate::types::TypeWorkMeter>(
        values: &mut Vec<Value>,
        count: usize,
        budget: &mut B,
    ) -> Result<Vec<Value>, B::Error> {
        if count > values.len() {
            return Err(crate::types::allocation_error(budget));
        }
        budget.charge(count)?;
        let mut result = Vec::new();
        result
            .try_reserve_exact(count)
            .map_err(|_| crate::types::allocation_error(budget))?;
        result.extend(values.drain(values.len() - count..));
        Ok(result)
    }
    fn type_sequence<B: crate::types::TypeWorkMeter>(
        elements: Box<[Type]>,
        budget: &mut B,
    ) -> Result<Vec<Value>, B::Error> {
        let elements = OwnedTypeBuffer(elements.into_vec());
        budget.charge(elements.len())?;
        let mut values = Vec::new();
        values
            .try_reserve_exact(elements.len())
            .map_err(|_| crate::types::allocation_error(budget))?;
        values.extend(elements.into_vec().into_iter().map(Value::ty));
        Ok(values)
    }
    fn argument_sequence<B: crate::types::TypeWorkMeter>(
        arguments: Box<[crate::types::KindedArgument]>,
        budget: &mut B,
    ) -> Result<Vec<Value>, B::Error> {
        // Stage guards before a fallible admission of the retained Value buffer.
        struct Arguments(Option<Box<[crate::types::KindedArgument]>>);
        impl Drop for Arguments {
            fn drop(&mut self) {
                if let Some(arguments) = self.0.take() {
                    for argument in arguments.into_vec() {
                        drop(crate::types::IterativeArgumentOwner::new(argument));
                    }
                }
            }
        }
        let mut arguments = Arguments(Some(arguments));
        let count = arguments
            .0
            .as_ref()
            .expect("guarded argument sequence")
            .len();
        budget.charge(count)?;
        let mut values = Vec::new();
        values
            .try_reserve_exact(count)
            .map_err(|_| crate::types::allocation_error(budget))?;
        values.extend(
            arguments
                .0
                .take()
                .expect("argument sequence transfers once")
                .into_vec()
                .into_iter()
                .map(Value::argument),
        );
        Ok(values)
    }
    fn rebuild_instances<B: crate::types::TypeWorkMeter>(
        shapes: Vec<(crate::types::EffectId, usize)>,
        arguments: &mut Vec<Value>,
        budget: &mut B,
    ) -> Result<Vec<EffectInstance>, B::Error> {
        budget.charge(shapes.len())?;
        let mut instances = Vec::new();
        instances
            .try_reserve_exact(shapes.len())
            .map_err(|_| crate::types::allocation_error(budget))?;
        for (effect, count) in shapes.into_iter().rev() {
            let suffix = suffix(arguments, count, budget)?;
            budget.charge(count)?;
            let mut retained = Vec::new();
            retained
                .try_reserve_exact(count)
                .map_err(|_| crate::types::allocation_error(budget))?;
            retained.extend(suffix.into_iter().map(Value::into_argument));
            instances.push(EffectInstance::new_kinded(
                effect,
                retained.into_boxed_slice(),
            ));
        }
        instances.reverse();
        Ok(instances)
    }
    let mut work = Vec::new();
    let root = match root {
        OwnedZonkRoot::Type(ty) => Value::ty(ty),
        OwnedZonkRoot::Argument(argument) => Value::argument(argument),
    };
    schedule(&mut work, Task::Visit(root), budget)?;
    let mut values = Vec::new();
    while let Some(task) = work.pop() {
        #[cfg(test)]
        record_zonk_rebuild_pending(work.len().saturating_add(1));
        match task {
            Task::Visit(Value::Type(ty)) => match ty.into_inner() {
                Type::Inference(identity) if solutions.contains_key(&identity) => {
                    let replacement =
                        Value::ty(clone_type_with_budget(&solutions[&identity], budget)?);
                    schedule(&mut work, Task::Visit(replacement), budget)?;
                }
                Type::Tuple(elements) => {
                    let count = elements.len();
                    let elements = type_sequence(elements, budget)?;
                    schedule(&mut work, Task::Tuple(count), budget)?;
                    schedule(&mut work, Task::Sequence(elements.into_iter()), budget)?;
                }
                Type::ResourceApply(owner, arguments) => {
                    let count = arguments.len();
                    let arguments = argument_sequence(arguments, budget)?;
                    schedule(&mut work, Task::Resource(owner, count), budget)?;
                    schedule(&mut work, Task::Sequence(arguments.into_iter()), budget)?;
                }
                Type::Application(function, argument) => {
                    let function = Value::ty(*function);
                    let argument = Value::ty(*argument);
                    schedule(&mut work, Task::Application, budget)?;
                    schedule(&mut work, Task::Visit(argument), budget)?;
                    schedule(&mut work, Task::Visit(function), budget)?;
                }
                Type::Function(domain, codomain) => {
                    let domain = Value::ty(*domain);
                    let codomain = Value::ty(*codomain);
                    schedule(&mut work, Task::Function, budget)?;
                    schedule(&mut work, Task::Visit(codomain), budget)?;
                    schedule(&mut work, Task::Visit(domain), budget)?;
                }
                Type::EffectfulFunction(domain, codomain) => {
                    let ComputationType { value, effects } = *codomain;
                    let domain = Value::ty(*domain);
                    let value = Value::ty(value);
                    let effects = Value::Row(effects);
                    schedule(&mut work, Task::EffectfulFunction, budget)?;
                    schedule(&mut work, Task::Visit(effects), budget)?;
                    schedule(&mut work, Task::Visit(value), budget)?;
                    schedule(&mut work, Task::Visit(domain), budget)?;
                }
                Type::Forall(parameters, body) => {
                    let body = Value::ty(*body);
                    schedule(&mut work, Task::Forall(parameters), budget)?;
                    schedule(&mut work, Task::Visit(body), budget)?;
                }
                leaf @ (Type::Bytes
                | Type::String
                | Type::Int
                | Type::Bool
                | Type::Unit
                | Type::Nominal(_)
                | Type::Variable(_)
                | Type::Inference(_)) => retain(&mut values, Value::ty(leaf), budget)?,
            },
            Task::Visit(Value::Argument(argument)) => match argument.into_inner() {
                crate::types::KindedArgument::TypeArg(ty) => {
                    let ty = Value::ty(ty);
                    schedule(&mut work, Task::TypeArgument, budget)?;
                    schedule(&mut work, Task::Visit(ty), budget)?;
                }
                crate::types::KindedArgument::RowArg(row) => {
                    schedule(&mut work, Task::RowArgument, budget)?;
                    schedule(&mut work, Task::Visit(Value::Row(row)), budget)?;
                }
            },
            Task::Visit(Value::Row(mut row)) => {
                let mut visited = HashSet::new();
                while let Some(tail) = row.tail() {
                    let EffectRowVariable::Inference(identity) = tail.variable() else {
                        break;
                    };
                    let Some(solution) = row_solutions.get(&identity) else {
                        break;
                    };
                    budget.charge(1)?;
                    visited
                        .try_reserve(1)
                        .map_err(|_| crate::types::allocation_error(budget))?;
                    if !visited.insert(identity) {
                        break;
                    }
                    row = row
                        .substitute_tail_once_with_budget(
                            EffectRowVariable::inference(identity),
                            solution,
                            budget,
                        )?
                        .expect("authenticated row solutions preserve lacks and occurs");
                }
                let (known, tail) = row.into_parts();
                let mut arguments = Vec::new();
                fn flatten<B: crate::types::TypeWorkMeter>(
                    instances: Box<[EffectInstance]>,
                    arguments: &mut Vec<Value>,
                    budget: &mut B,
                ) -> Result<Vec<(crate::types::EffectId, usize)>, B::Error> {
                    budget.charge(instances.len())?;
                    let mut shapes = Vec::new();
                    shapes
                        .try_reserve_exact(instances.len())
                        .map_err(|_| crate::types::allocation_error(budget))?;
                    for instance in instances.into_vec() {
                        let (effect, actuals) = instance.into_parts();
                        let staged = argument_sequence(actuals, budget)?;
                        budget.charge(staged.len())?;
                        arguments
                            .try_reserve(staged.len())
                            .map_err(|_| crate::types::allocation_error(budget))?;
                        shapes.push((effect, staged.len()));
                        arguments.extend(staged);
                    }
                    Ok(shapes)
                }
                let known = flatten(known, &mut arguments, budget)?;
                let tail = match tail {
                    Some((variable, lacks)) => {
                        Some((variable, flatten(lacks, &mut arguments, budget)?))
                    }
                    None => None,
                };
                let count = arguments.len();
                schedule(
                    &mut work,
                    Task::Row(RowShape {
                        known,
                        tail,
                        arguments: count,
                    }),
                    budget,
                )?;
                schedule(&mut work, Task::Sequence(arguments.into_iter()), budget)?;
            }
            Task::Sequence(mut remaining) => {
                if let Some(next) = remaining.next() {
                    schedule(&mut work, Task::Sequence(remaining), budget)?;
                    schedule(&mut work, Task::Visit(next), budget)?;
                }
            }
            Task::TypeArgument => {
                let ty = values.pop().expect("zonked TypeArg payload").into_type();
                retain(
                    &mut values,
                    Value::argument(crate::types::KindedArgument::TypeArg(ty)),
                    budget,
                )?;
            }
            Task::RowArgument => {
                let row = values.pop().expect("zonked RowArg payload").into_row();
                retain(
                    &mut values,
                    Value::argument(crate::types::KindedArgument::RowArg(row)),
                    budget,
                )?;
            }
            Task::Tuple(count) => {
                let staged = suffix(&mut values, count, budget)?;
                budget.charge(count)?;
                let mut elements = Vec::new();
                elements
                    .try_reserve_exact(count)
                    .map_err(|_| crate::types::allocation_error(budget))?;
                elements.extend(staged.into_iter().map(Value::into_type));
                retain(
                    &mut values,
                    Value::ty(Type::Tuple(elements.into_boxed_slice())),
                    budget,
                )?;
            }
            Task::Resource(owner, count) => {
                let staged = suffix(&mut values, count, budget)?;
                budget.charge(count)?;
                let mut arguments = Vec::new();
                arguments
                    .try_reserve_exact(count)
                    .map_err(|_| crate::types::allocation_error(budget))?;
                arguments.extend(staged.into_iter().map(Value::into_argument));
                retain(
                    &mut values,
                    Value::ty(Type::ResourceApply(owner, arguments.into_boxed_slice())),
                    budget,
                )?;
            }
            Task::Application | Task::Function => {
                let right = values.pop().expect("zonked right child");
                let left = values.pop().expect("zonked left child");
                let ty = if matches!(task, Task::Application) {
                    Type::Application(Box::new(left.into_type()), Box::new(right.into_type()))
                } else {
                    Type::Function(Box::new(left.into_type()), Box::new(right.into_type()))
                };
                retain(&mut values, Value::ty(ty), budget)?;
            }
            Task::EffectfulFunction => {
                let row = values.pop().expect("zonked effects").into_row();
                let value = values.pop().expect("zonked value");
                let domain = values.pop().expect("zonked domain");
                retain(
                    &mut values,
                    Value::ty(Type::function_computation(
                        domain.into_type(),
                        ComputationType::new(value.into_type(), row),
                    )),
                    budget,
                )?;
            }
            Task::Row(shape) => {
                let mut arguments = suffix(&mut values, shape.arguments, budget)?;
                let tail = match shape.tail {
                    Some((variable, lacks)) => {
                        Some((variable, rebuild_instances(lacks, &mut arguments, budget)?))
                    }
                    None => None,
                };
                let known = rebuild_instances(shape.known, &mut arguments, budget)?;
                if !arguments.is_empty() {
                    return Err(crate::types::allocation_error(budget));
                }
                let row = effect_row_from_owned_parts_with_budget(known, tail, budget)?;
                retain(&mut values, Value::Row(row), budget)?;
            }
            Task::Forall(parameters) => {
                let body = values.pop().expect("zonked forall body");
                retain(
                    &mut values,
                    Value::ty(Type::Forall(parameters, Box::new(body.into_type()))),
                    budget,
                )?;
            }
        }
    }
    if values.len() != 1 {
        return Err(crate::types::allocation_error(budget));
    }
    match values.pop().expect("one zonked root") {
        Value::Type(ty) => Ok(OwnedZonkRoot::Type(ty.into_inner())),
        Value::Argument(argument) => Ok(OwnedZonkRoot::Argument(argument.into_inner())),
        Value::Row(_) => Err(crate::types::allocation_error(budget)),
    }
}
enum InferenceOccurrenceRoot<'a> {
    Type(&'a Type),
    Row(&'a EffectRow),
}

#[cfg(test)]
fn type_contains_inference(
    ty: &Type,
    needle: InferenceVariableId,
    solutions: &HashMap<InferenceVariableId, Type>,
    registry: &ResolvedRegistry,
    generated_type_variables: &GeneratedTypeVariableRegistry,
    inference_variables: &InferenceVariableRegistry,
    budget: &mut TypeWorkBudget,
) -> Result<bool, UnificationFailure> {
    inference_occurs_in_owner_graph(
        InferenceOccurrenceRoot::Type(ty),
        needle,
        solutions,
        &HashMap::new(),
        registry,
        generated_type_variables,
        inference_variables,
        budget,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "one kind-preserving occurs traversal shares the actual Type and row solution graph"
)]
fn inference_occurs_in_owner_graph(
    root: InferenceOccurrenceRoot<'_>,
    needle: InferenceVariableId,
    solutions: &HashMap<InferenceVariableId, Type>,
    row_solutions: &HashMap<InferenceVariableId, EffectRow>,
    registry: &ResolvedRegistry,
    generated_type_variables: &GeneratedTypeVariableRegistry,
    inference_variables: &InferenceVariableRegistry,
    budget: &mut TypeWorkBudget,
) -> Result<bool, UnificationFailure> {
    enum Task<'a> {
        Visit(&'a Type),
        Sequence(std::slice::Iter<'a, Type>),
        Argument(&'a crate::types::KindedArgument),
        Row(&'a EffectRow),
    }

    let mut work = Vec::new();
    let mut visited = HashSet::new();
    let mut visited_rows = HashSet::new();

    macro_rules! schedule {
        ($task:expr) => {{
            budget
                .charge(1)
                .map_err(|()| UnificationFailure::Resource)?;
            work.try_reserve(1)
                .map_err(|_| UnificationFailure::Resource)?;
            work.push($task);
        }};
    }

    match root {
        InferenceOccurrenceRoot::Type(ty) => schedule!(Task::Visit(ty)),
        InferenceOccurrenceRoot::Row(row) => schedule!(Task::Row(row)),
    }
    while let Some(task) = work.pop() {
        #[cfg(test)]
        record_occurs_pending(work.len().saturating_add(1));
        let ty = match task {
            Task::Visit(ty) => ty,
            Task::Argument(crate::types::KindedArgument::TypeArg(ty)) => ty,
            Task::Argument(crate::types::KindedArgument::RowArg(row)) => {
                schedule!(Task::Row(row));
                continue;
            }
            Task::Row(row) => {
                if let Some(tail) = row.tail()
                    && let EffectRowVariable::Inference(identity) = tail.variable()
                {
                    let fact = inference_variables
                        .fact(identity, budget)
                        .map_err(inference_registry_failure_for_unification)?;
                    if !same_kind_with_budget(&fact.kind, &Kind::EffectRow, budget)
                        .map_err(|()| UnificationFailure::Resource)?
                    {
                        return Err(UnificationFailure::Mismatch);
                    }
                    if identity == needle {
                        return Ok(true);
                    }
                    if !visited_rows.contains(&identity) {
                        budget
                            .charge(1)
                            .map_err(|()| UnificationFailure::Resource)?;
                        visited_rows
                            .try_reserve(1)
                            .map_err(|_| UnificationFailure::Resource)?;
                        visited_rows.insert(identity);
                        if let Some(solution) = row_solutions.get(&identity) {
                            schedule!(Task::Row(solution));
                        }
                    }
                }
                for instance in row
                    .known()
                    .iter()
                    .chain(row.tail().into_iter().flat_map(|tail| tail.lacks().iter()))
                {
                    budget
                        .charge(1)
                        .map_err(|()| UnificationFailure::Resource)?;
                    for argument in instance.arguments() {
                        schedule!(Task::Argument(argument));
                    }
                }
                continue;
            }
            Task::Sequence(mut remaining) => {
                if let Some(next) = remaining.next() {
                    schedule!(Task::Sequence(remaining));
                    schedule!(Task::Visit(next));
                }
                continue;
            }
        };
        match ty {
            Type::Inference(identity) => {
                inference_variables
                    .fact(*identity, budget)
                    .map_err(inference_registry_failure_for_unification)?;
                if *identity == needle {
                    return Ok(true);
                }
                budget
                    .charge(1)
                    .map_err(|()| UnificationFailure::Resource)?;
                visited
                    .try_reserve(1)
                    .map_err(|_| UnificationFailure::Resource)?;
                if !visited.insert(*identity) {
                    continue;
                }
                if let Some(solution) = solutions.get(identity) {
                    authenticate_inference_solution_kind(
                        *identity,
                        solution,
                        registry,
                        generated_type_variables,
                        inference_variables,
                        budget,
                    )?;
                    schedule!(Task::Visit(solution));
                }
            }
            Type::Tuple(elements) => {
                schedule!(Task::Sequence(elements.iter()));
            }
            Type::Application(function, argument) => {
                schedule!(Task::Visit(argument));
                schedule!(Task::Visit(function));
            }
            Type::Function(domain, codomain) => {
                schedule!(Task::Visit(codomain));
                schedule!(Task::Visit(domain));
            }
            Type::ResourceApply(_, arguments) => {
                for argument in arguments {
                    schedule!(Task::Argument(argument));
                }
            }
            Type::EffectfulFunction(domain, codomain) => {
                for argument in codomain.effect_arguments() {
                    schedule!(Task::Argument(argument));
                }
                schedule!(Task::Visit(codomain.value()));
                schedule!(Task::Visit(domain));
            }
            Type::Forall(_, _) => return Err(UnificationFailure::Invariant),
            Type::Bytes
            | Type::String
            | Type::Int
            | Type::Bool
            | Type::Unit
            | Type::Nominal(_)
            | Type::Variable(_) => {}
        }
    }
    Ok(false)
}

fn collect_unsolved_inference(
    ty: &Type,
    budget: &mut TypeWorkBudget,
) -> Result<Vec<InferenceVariableId>, ()> {
    enum Task<'a> {
        Type(&'a Type),
        Sequence(std::slice::Iter<'a, Type>),
        Argument(&'a crate::types::KindedArgument),
        Row(&'a EffectRow),
    }
    fn schedule<'a>(
        work: &mut Vec<Task<'a>>,
        task: Task<'a>,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        let task = match task {
            Task::Argument(crate::types::KindedArgument::TypeArg(ty)) => Task::Type(ty),
            Task::Argument(crate::types::KindedArgument::RowArg(row)) => Task::Row(row),
            task => task,
        };
        // Sequence continuation reuses an admitted token; its child Type
        // nodes and every new row record are charged before retention.
        if !matches!(task, Task::Sequence(_)) {
            budget.charge(1)?;
        }
        work.try_reserve(1).map_err(|_| ())?;
        work.push(task);
        Ok(())
    }
    fn retain(
        identity: InferenceVariableId,
        seen: &mut HashSet<InferenceVariableId>,
        found: &mut Vec<InferenceVariableId>,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        if !seen.contains(&identity) {
            budget.charge(2)?;
            seen.try_reserve(1).map_err(|_| ())?;
            found.try_reserve(1).map_err(|_| ())?;
            seen.insert(identity);
            found.push(identity);
        }
        Ok(())
    }
    let mut work = Vec::new();
    schedule(&mut work, Task::Type(ty), budget)?;
    let mut seen = HashSet::new();
    let mut found = Vec::new();
    while let Some(task) = work.pop() {
        match task {
            Task::Type(Type::Inference(identity)) => {
                retain(*identity, &mut seen, &mut found, budget)?
            }
            Task::Type(Type::Tuple(elements)) => {
                schedule(&mut work, Task::Sequence(elements.iter()), budget)?
            }
            Task::Sequence(mut remaining) => {
                if let Some(next) = remaining.next() {
                    schedule(&mut work, Task::Sequence(remaining), budget)?;
                    schedule(&mut work, Task::Type(next), budget)?;
                }
            }
            Task::Type(
                Type::Application(function, argument) | Type::Function(function, argument),
            ) => {
                schedule(&mut work, Task::Type(argument), budget)?;
                schedule(&mut work, Task::Type(function), budget)?;
            }
            Task::Type(Type::ResourceApply(_, arguments)) => {
                for argument in arguments {
                    schedule(&mut work, Task::Argument(argument), budget)?;
                }
            }
            Task::Type(Type::EffectfulFunction(domain, codomain)) => {
                schedule(&mut work, Task::Row(codomain.effects()), budget)?;
                schedule(&mut work, Task::Type(codomain.value()), budget)?;
                schedule(&mut work, Task::Type(domain), budget)?;
            }
            Task::Row(row) => {
                if let Some(tail) = row.tail()
                    && let EffectRowVariable::Inference(identity) = tail.variable()
                {
                    retain(identity, &mut seen, &mut found, budget)?;
                }
                for instance in row
                    .known()
                    .iter()
                    .chain(row.tail().into_iter().flat_map(|tail| tail.lacks().iter()))
                {
                    budget.charge(1)?;
                    for argument in instance.arguments() {
                        schedule(&mut work, Task::Argument(argument), budget)?;
                    }
                }
            }
            Task::Type(Type::Forall(_, body)) => schedule(&mut work, Task::Type(body), budget)?,
            Task::Type(
                Type::Bytes
                | Type::String
                | Type::Int
                | Type::Bool
                | Type::Unit
                | Type::Nominal(_)
                | Type::Variable(_),
            ) => {}
            Task::Argument(_) => unreachable!("argument tasks normalize before retention"),
        }
    }
    Ok(found)
}

fn type_contains_unsolved_row_inference(
    ty: &Type,
    solutions: &HashMap<InferenceVariableId, EffectRow>,
    budget: &mut TypeWorkBudget,
) -> Result<bool, ()> {
    enum Task<'a> {
        Type(&'a Type),
        Argument(&'a crate::types::KindedArgument),
        Row(&'a EffectRow),
    }
    fn schedule<'a>(
        work: &mut Vec<Task<'a>>,
        task: Task<'a>,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        // Preserve the Type-only argument path's node cost; new Row records
        // have their own admitted work and storage.
        let task = match task {
            Task::Argument(crate::types::KindedArgument::TypeArg(ty)) => Task::Type(ty),
            Task::Argument(crate::types::KindedArgument::RowArg(row)) => Task::Row(row),
            task => task,
        };
        budget.charge(1)?;
        work.try_reserve(1).map_err(|_| ())?;
        work.push(task);
        Ok(())
    }
    let mut work = Vec::new();
    schedule(&mut work, Task::Type(ty), budget)?;
    let mut visited = HashSet::new();
    while let Some(task) = work.pop() {
        match task {
            Task::Type(Type::Tuple(elements)) => {
                for element in elements {
                    schedule(&mut work, Task::Type(element), budget)?;
                }
            }
            Task::Type(
                Type::Application(function, argument) | Type::Function(function, argument),
            ) => {
                schedule(&mut work, Task::Type(argument), budget)?;
                schedule(&mut work, Task::Type(function), budget)?;
            }
            Task::Type(Type::ResourceApply(_, arguments)) => {
                for argument in arguments {
                    schedule(&mut work, Task::Argument(argument), budget)?;
                }
            }
            Task::Type(Type::EffectfulFunction(domain, codomain)) => {
                schedule(&mut work, Task::Row(codomain.effects()), budget)?;
                schedule(&mut work, Task::Type(codomain.value()), budget)?;
                schedule(&mut work, Task::Type(domain), budget)?;
            }
            Task::Row(row) => {
                if let Some(tail) = row.tail()
                    && let EffectRowVariable::Inference(identity) = tail.variable()
                {
                    let Some(solution) = solutions.get(&identity) else {
                        return Ok(true);
                    };
                    if !visited.contains(&identity) {
                        budget.charge(1)?;
                        visited.try_reserve(1).map_err(|_| ())?;
                        visited.insert(identity);
                        schedule(&mut work, Task::Row(solution), budget)?;
                    }
                }
                for member in row
                    .known()
                    .iter()
                    .chain(row.tail().into_iter().flat_map(|tail| tail.lacks().iter()))
                {
                    budget.charge(1)?;
                    for argument in member.arguments() {
                        schedule(&mut work, Task::Argument(argument), budget)?;
                    }
                }
            }
            Task::Type(Type::Forall(_, body)) => schedule(&mut work, Task::Type(body), budget)?,
            Task::Type(
                Type::Bytes
                | Type::String
                | Type::Int
                | Type::Bool
                | Type::Unit
                | Type::Nominal(_)
                | Type::Variable(_)
                | Type::Inference(_),
            ) => {}
            Task::Argument(_) => unreachable!("argument tasks normalize before retention"),
        }
    }
    Ok(false)
}

fn row_exclusion_error(span: Span, contract: Option<Span>) -> TypeError {
    let mut diagnostic = Diagnostic::new(
        TypeReason::EffectRowExclusion,
        SourceLabel::new(
            span,
            "this computation requires an effect excluded from the row tail",
        ),
    );
    if let Some(contract) = contract {
        diagnostic.related.push(SourceLabel::new(
            contract,
            "this type requires the row-tail exclusion",
        ));
    }
    TypeError::source(diagnostic)
}

fn effect_row_failure(cause: EffectRowCause, span: Span, message: &str) -> TypeError {
    TypeError::Source(Box::new(TypeDiagnostic {
        diagnostic: Diagnostic::new(
            TypeReason::AmbiguousEffectRow,
            SourceLabel::new(span, message),
        ),
        context: TypeDiagnosticContext::EffectRow(cause),
    }))
}

fn inference_failure(reason: TypeReason, span: Span, message: &str) -> TypeError {
    TypeError::source(Diagnostic::new(reason, SourceLabel::new(span, message)))
}

fn capture_failure(
    failure: crate::core::capture::Failure,
    budget: &mut TypeWorkBudget,
) -> TypeError {
    use crate::core::capture::Failure;
    match failure {
        Failure::CleanupRow { source, .. } => effect_row_failure(
            EffectRowCause::DiscardCleanup,
            source,
            "discard effects differ from its owned cleanup actions",
        ),
        Failure::CleanupContext {
            discard,
            action,
            handler,
        } => {
            if budget.charge(3).is_err() {
                return type_resource();
            }
            let mut diagnostic = Diagnostic::new(
                TypeReason::CleanupContext,
                SourceLabel::new(
                    discard,
                    "discard removes an interpreter required by cleanup",
                ),
            );
            if diagnostic.related.try_reserve_exact(2).is_err() {
                return type_resource();
            }
            diagnostic.related.push(SourceLabel::new(
                action,
                "this cleanup action requires the interpreter",
            ));
            diagnostic.related.push(SourceLabel::new(
                handler,
                "this nearest matching handler is abandoned",
            ));
            TypeError::source(diagnostic)
        }
        Failure::Invalid => invalid_state(),
        Failure::Resource => type_resource(),
        Failure::Escape {
            source,
            acquisition,
        } => {
            if budget.charge(2).is_err() {
                return type_resource();
            }
            let mut diagnostic = Diagnostic::new(
                TypeReason::ResourceEscape,
                SourceLabel::new(
                    source,
                    "this value retains a dependency on the closing resource",
                ),
            );
            if diagnostic.related.try_reserve_exact(1).is_err() {
                return type_resource();
            }
            diagnostic.related.push(SourceLabel::new(
                acquisition,
                "this resource is acquired here",
            ));
            TypeError::source(diagnostic)
        }
        Failure::Unsafe(unsafe_discard) => {
            let related_count = 1 + usize::from(unsafe_discard.owner.is_some());
            if budget.charge(1 + related_count).is_err() {
                return type_resource();
            }
            let mut diagnostic = Diagnostic::new(
                TypeReason::DiscardUnsafe,
                SourceLabel::new(
                    unsafe_discard.discard,
                    "discard requires proof that the captured continuation has no unfinished obligations",
                ),
            );
            if diagnostic.related.try_reserve_exact(related_count).is_err() {
                return type_resource();
            }
            diagnostic.related.push(SourceLabel::new(
                unsafe_discard.request,
                "this request or call can capture the continuation",
            ));
            if let Some(owner) = unsafe_discard.owner {
                let (owner, message) = match owner {
                    crate::core::capture::CompletionOwner::Clause(span) => (
                        span,
                        "this clause still has an unfinished completion capability",
                    ),
                    crate::core::capture::CompletionOwner::Cleanup(span) => {
                        (span, "this cleanup action must complete")
                    }
                };
                diagnostic.related.push(SourceLabel::new(owner, message));
            }
            TypeError::Source(Box::new(TypeDiagnostic {
                diagnostic,
                context: TypeDiagnosticContext::DiscardUnsafe(unsafe_discard.owner),
            }))
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ResumeUsage {
    Available,
    Consumed,
}

fn check_clause_resume_usage(
    expression: &ResolvedExpr,
    owner: ResumeId,
    budget: &mut TypeWorkBudget,
) -> Result<(), TypeError> {
    match resume_usage_with_budget(expression, owner, ResumeUsage::Available, budget)? {
        ResumeUsage::Consumed => Ok(()),
        ResumeUsage::Available => Err(inference_failure(
            TypeReason::ResumeNotConsumed,
            expression.span,
            "this operation clause can complete without resuming or discarding",
        )),
    }
}

fn resume_usage_with_budget(
    expression: &ResolvedExpr,
    owner: ResumeId,
    mut state: ResumeUsage,
    budget: &mut TypeWorkBudget,
) -> Result<ResumeUsage, TypeError> {
    enum Task<'a> {
        Visit(&'a ResolvedExpr),
        Consume(Option<ResumeId>, Span),
        BeginMatch(&'a [crate::resolved::ResolvedMatchArm]),
        FinishMatchArm {
            arms: &'a [crate::resolved::ResolvedMatchArm],
            next: usize,
            incoming: ResumeUsage,
            outgoing: Option<ResumeUsage>,
        },
        CheckRecursive(&'a ResolvedRecursiveGroup),
        CheckFunction(&'a crate::resolved::ResolvedFunctionExpr, Span),
        CheckHandlerClauses(&'a [crate::resolved::ResolvedHandlerClause], Span),
    }

    fn push<'a>(
        tasks: &mut Vec<Task<'a>>,
        task: Task<'a>,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), TypeError> {
        budget
            .charge(1)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        tasks
            .try_reserve(1)
            .map_err(|_| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        tasks.push(task);
        Ok(())
    }

    let mut tasks = Vec::new();
    push(&mut tasks, Task::Visit(expression), budget)?;
    while let Some(task) = tasks.pop() {
        match task {
            Task::Visit(expression) => match &expression.kind {
                ResolvedExprKind::String(_)
                | ResolvedExprKind::Integer(_)
                | ResolvedExprKind::Boolean(_)
                | ResolvedExprKind::Unit
                | ResolvedExprKind::Occurrence(_)
                | ResolvedExprKind::Constructor(_) => {}
                ResolvedExprKind::Tuple(elements) => {
                    for element in elements.iter().rev() {
                        push(&mut tasks, Task::Visit(element), budget)?;
                    }
                }
                ResolvedExprKind::Apply(application) => {
                    push(&mut tasks, Task::Visit(&application.argument), budget)?;
                    push(&mut tasks, Task::Visit(&application.function), budget)?;
                }
                ResolvedExprKind::Add(binary)
                | ResolvedExprKind::Multiply(binary)
                | ResolvedExprKind::Equal(binary) => {
                    push(&mut tasks, Task::Visit(&binary.right), budget)?;
                    push(&mut tasks, Task::Visit(&binary.left), budget)?;
                }
                ResolvedExprKind::Block(block) => {
                    push(&mut tasks, Task::Visit(&block.result), budget)?;
                    for declaration in block.declarations.iter().rev() {
                        match declaration {
                            ResolvedLocalDeclaration::Evidence(source) => {
                                for equation in source
                                    .method_groups
                                    .iter()
                                    .flat_map(|group| &group.equations)
                                {
                                    if contains_resume_owner_with_budget(
                                        &equation.body,
                                        owner,
                                        budget,
                                    )? {
                                        return Err(inference_failure(
                                            TypeReason::ResumeCapture,
                                            equation.body.span,
                                            "a supplied method cannot capture the clause completion capability",
                                        ));
                                    }
                                }
                            }
                            ResolvedLocalDeclaration::Binding(binding) => {
                                push(&mut tasks, Task::Visit(&binding.initializer), budget)?
                            }
                            ResolvedLocalDeclaration::Recursive(group) => {
                                push(&mut tasks, Task::CheckRecursive(group), budget)?;
                            }
                            ResolvedLocalDeclaration::Newtype(_) => {}
                        }
                    }
                }
                ResolvedExprKind::Function(function) => {
                    push(
                        &mut tasks,
                        Task::CheckFunction(function, expression.span),
                        budget,
                    )?;
                }
                ResolvedExprKind::Match(matched) => {
                    push(&mut tasks, Task::BeginMatch(&matched.arms), budget)?;
                    push(&mut tasks, Task::Visit(&matched.scrutinee), budget)?;
                }
                ResolvedExprKind::ProviderResource(resource) => {
                    push(&mut tasks, Task::Visit(&resource.body), budget)?;
                    push(&mut tasks, Task::Visit(&resource.initializer), budget)?;
                }
                ResolvedExprKind::Resource(resource) => {
                    push(&mut tasks, Task::Visit(&resource.body), budget)?;
                    push(&mut tasks, Task::Visit(&resource.initializer), budget)?;
                }
                ResolvedExprKind::Cleanup(cleanup) => {
                    push(&mut tasks, Task::Visit(&cleanup.action), budget)?;
                    push(&mut tasks, Task::Visit(&cleanup.body), budget)?;
                }
                ResolvedExprKind::Perform(request) => {
                    push(&mut tasks, Task::Visit(&request.operand), budget)?;
                }
                ResolvedExprKind::Handle(handler) => {
                    push(&mut tasks, Task::Visit(&handler.body), budget)?;
                    push(
                        &mut tasks,
                        Task::CheckHandlerClauses(&handler.clauses, expression.span),
                        budget,
                    )?;
                }
                ResolvedExprKind::Resume(resume) => {
                    push(
                        &mut tasks,
                        Task::Consume(resume.owner, expression.span),
                        budget,
                    )?;
                    push(&mut tasks, Task::Visit(&resume.value), budget)?;
                }
                ResolvedExprKind::Discard(discard) => {
                    push(
                        &mut tasks,
                        Task::Consume(discard.owner, expression.span),
                        budget,
                    )?;
                }
            },
            Task::Consume(resume_owner, span) => {
                if resume_owner == Some(owner) {
                    state = match state {
                        ResumeUsage::Available => ResumeUsage::Consumed,
                        ResumeUsage::Consumed => {
                            return Err(inference_failure(
                                TypeReason::ResumeAlreadyConsumed,
                                span,
                                "this control-flow path already consumed the completion capability",
                            ));
                        }
                    };
                }
            }
            Task::BeginMatch(arms) => {
                if let Some(first) = arms.first() {
                    let incoming = state;
                    push(
                        &mut tasks,
                        Task::FinishMatchArm {
                            arms,
                            next: 1,
                            incoming,
                            outgoing: None,
                        },
                        budget,
                    )?;
                    push(&mut tasks, Task::Visit(&first.body), budget)?;
                }
            }
            Task::FinishMatchArm {
                arms,
                next,
                incoming,
                outgoing,
            } => {
                if outgoing.is_some_and(|previous| previous != state) {
                    let span = arms.get(next - 1).ok_or_else(invalid_state)?.span;
                    return Err(inference_failure(
                        TypeReason::ResumeNotConsumed,
                        span,
                        "every match branch must leave the same completion usage state",
                    ));
                }
                let outgoing = Some(state);
                if let Some(arm) = arms.get(next) {
                    state = incoming;
                    push(
                        &mut tasks,
                        Task::FinishMatchArm {
                            arms,
                            next: next + 1,
                            incoming,
                            outgoing,
                        },
                        budget,
                    )?;
                    push(&mut tasks, Task::Visit(&arm.body), budget)?;
                }
            }
            Task::CheckRecursive(group) => {
                for member in &group.members {
                    if contains_resume_owner_with_budget(&member.initializer, owner, budget)? {
                        return Err(inference_failure(
                            TypeReason::ResumeCapture,
                            group.span,
                            "a recursive member cannot capture the clause completion capability",
                        ));
                    }
                }
            }
            Task::CheckFunction(function, span) => {
                if block_contains_resume_owner_with_budget(&function.body, owner, budget)? {
                    return Err(inference_failure(
                        TypeReason::ResumeCapture,
                        span,
                        "a nested function cannot capture the clause completion capability",
                    ));
                }
            }
            Task::CheckHandlerClauses(clauses, span) => {
                for clause in clauses {
                    if contains_resume_owner_with_budget(&clause.body, owner, budget)? {
                        return Err(inference_failure(
                            TypeReason::ResumeCapture,
                            span,
                            "a nested handler clause cannot capture the outer completion capability",
                        ));
                    }
                }
            }
        }
    }
    Ok(state)
}

fn block_contains_resume_owner_with_budget(
    block: &ResolvedBlock,
    owner: ResumeId,
    budget: &mut TypeWorkBudget,
) -> Result<bool, TypeError> {
    if contains_resume_owner_with_budget(&block.result, owner, budget)? {
        return Ok(true);
    }
    for declaration in &block.declarations {
        match declaration {
            ResolvedLocalDeclaration::Evidence(source) => {
                for equation in source
                    .method_groups
                    .iter()
                    .flat_map(|group| &group.equations)
                {
                    if contains_resume_owner_with_budget(&equation.body, owner, budget)? {
                        return Ok(true);
                    }
                }
            }
            ResolvedLocalDeclaration::Binding(binding) => {
                if contains_resume_owner_with_budget(&binding.initializer, owner, budget)? {
                    return Ok(true);
                }
            }
            ResolvedLocalDeclaration::Recursive(group) => {
                for member in &group.members {
                    if contains_resume_owner_with_budget(&member.initializer, owner, budget)? {
                        return Ok(true);
                    }
                }
            }
            ResolvedLocalDeclaration::Newtype(_) => {}
        }
    }
    Ok(false)
}

fn contains_resume_owner_with_budget(
    expression: &ResolvedExpr,
    owner: ResumeId,
    budget: &mut TypeWorkBudget,
) -> Result<bool, TypeError> {
    fn schedule<'a>(
        pending: &mut Vec<&'a ResolvedExpr>,
        expression: &'a ResolvedExpr,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), TypeError> {
        budget
            .charge(1)
            .map_err(|()| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        pending
            .try_reserve(1)
            .map_err(|_| TypeError::Internal(ElaborationFailure::TypeResourceExhausted))?;
        pending.push(expression);
        Ok(())
    }

    let mut pending = Vec::new();
    schedule(&mut pending, expression, budget)?;
    while let Some(expression) = pending.pop() {
        match &expression.kind {
            ResolvedExprKind::Resume(resume) => {
                if resume.owner == Some(owner) {
                    return Ok(true);
                }
                schedule(&mut pending, &resume.value, budget)?;
            }
            ResolvedExprKind::Discard(discard) => {
                if discard.owner == Some(owner) {
                    return Ok(true);
                }
            }
            ResolvedExprKind::ProviderResource(resource) => {
                schedule(&mut pending, &resource.body, budget)?;
                schedule(&mut pending, &resource.initializer, budget)?;
            }
            ResolvedExprKind::Resource(resource) => {
                schedule(&mut pending, &resource.body, budget)?;
                schedule(&mut pending, &resource.initializer, budget)?;
            }
            ResolvedExprKind::Cleanup(cleanup) => {
                schedule(&mut pending, &cleanup.body, budget)?;
                schedule(&mut pending, &cleanup.action, budget)?;
            }
            ResolvedExprKind::Tuple(elements) => {
                for element in elements {
                    schedule(&mut pending, element, budget)?;
                }
            }
            ResolvedExprKind::Apply(application) => {
                schedule(&mut pending, &application.argument, budget)?;
                schedule(&mut pending, &application.function, budget)?;
            }
            ResolvedExprKind::Add(binary)
            | ResolvedExprKind::Multiply(binary)
            | ResolvedExprKind::Equal(binary) => {
                schedule(&mut pending, &binary.right, budget)?;
                schedule(&mut pending, &binary.left, budget)?;
            }
            ResolvedExprKind::Block(block) => {
                schedule(&mut pending, &block.result, budget)?;
                for declaration in &block.declarations {
                    match declaration {
                        ResolvedLocalDeclaration::Evidence(source) => {
                            for equation in source
                                .method_groups
                                .iter()
                                .flat_map(|group| &group.equations)
                            {
                                schedule(&mut pending, &equation.body, budget)?;
                            }
                        }
                        ResolvedLocalDeclaration::Binding(binding) => {
                            schedule(&mut pending, &binding.initializer, budget)?;
                        }
                        ResolvedLocalDeclaration::Recursive(group) => {
                            for member in &group.members {
                                schedule(&mut pending, &member.initializer, budget)?;
                            }
                        }
                        ResolvedLocalDeclaration::Newtype(_) => {}
                    }
                }
            }
            ResolvedExprKind::Function(function) => {
                schedule(&mut pending, &function.body.result, budget)?;
                for declaration in &function.body.declarations {
                    match declaration {
                        ResolvedLocalDeclaration::Evidence(source) => {
                            for equation in source
                                .method_groups
                                .iter()
                                .flat_map(|group| &group.equations)
                            {
                                schedule(&mut pending, &equation.body, budget)?;
                            }
                        }
                        ResolvedLocalDeclaration::Binding(binding) => {
                            schedule(&mut pending, &binding.initializer, budget)?;
                        }
                        ResolvedLocalDeclaration::Recursive(group) => {
                            for member in &group.members {
                                schedule(&mut pending, &member.initializer, budget)?;
                            }
                        }
                        ResolvedLocalDeclaration::Newtype(_) => {}
                    }
                }
            }
            ResolvedExprKind::Match(matched) => {
                schedule(&mut pending, &matched.scrutinee, budget)?;
                for arm in &matched.arms {
                    schedule(&mut pending, &arm.body, budget)?;
                }
            }
            ResolvedExprKind::Perform(request) => {
                schedule(&mut pending, &request.operand, budget)?;
            }
            ResolvedExprKind::Handle(handler) => {
                schedule(&mut pending, &handler.body, budget)?;
                for clause in &handler.clauses {
                    schedule(&mut pending, &clause.body, budget)?;
                }
            }
            ResolvedExprKind::String(_)
            | ResolvedExprKind::Integer(_)
            | ResolvedExprKind::Boolean(_)
            | ResolvedExprKind::Unit
            | ResolvedExprKind::Occurrence(_)
            | ResolvedExprKind::Constructor(_) => {}
        }
    }
    Ok(false)
}

pub(crate) fn checked_program_contains_effect_syntax(
    program: &ValidatedInterfaceProgram,
    budget: &mut TypeWorkBudget,
) -> Result<bool, TypeError> {
    fn resource() -> TypeError {
        TypeError::Internal(ElaborationFailure::TypeResourceExhausted)
    }

    fn schedule<'a>(
        work: &mut Vec<&'a ResolvedExpr>,
        expression: &'a ResolvedExpr,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), TypeError> {
        budget.charge(1).map_err(|()| resource())?;
        work.try_reserve(1).map_err(|_| resource())?;
        work.push(expression);
        Ok(())
    }

    fn schedule_declaration<'a>(
        work: &mut Vec<&'a ResolvedExpr>,
        declaration: &'a ResolvedLocalDeclaration,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), TypeError> {
        match declaration {
            ResolvedLocalDeclaration::Evidence(source) => {
                for equation in source
                    .method_groups
                    .iter()
                    .flat_map(|group| &group.equations)
                {
                    schedule(work, &equation.body, budget)?;
                }
                Ok(())
            }
            ResolvedLocalDeclaration::Binding(binding) => {
                schedule(work, &binding.initializer, budget)
            }
            ResolvedLocalDeclaration::Recursive(group) => {
                for member in &group.members {
                    schedule(work, &member.initializer, budget)?;
                }
                Ok(())
            }
            ResolvedLocalDeclaration::Newtype(_) => Ok(()),
        }
    }

    fn schedule_block<'a>(
        work: &mut Vec<&'a ResolvedExpr>,
        block: &'a ResolvedBlock,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), TypeError> {
        schedule(work, &block.result, budget)?;
        for declaration in &block.declarations {
            schedule_declaration(work, declaration, budget)?;
        }
        Ok(())
    }

    fn type_requires_effect_core<'a>(
        parameter_count: usize,
        mut parameters: impl Iterator<Item = &'a Kind>,
        value_type: &Type,
        budget: &mut TypeWorkBudget,
    ) -> Result<bool, TypeError> {
        budget.charge(parameter_count).map_err(|()| resource())?;
        if parameters.any(|kind| matches!(kind, Kind::EffectRow)) {
            return Ok(true);
        }
        requires_pure_core_projection(value_type, Some(budget)).map_err(|()| resource())
    }

    let registry = program.registry();
    for nominal in registry
        .nominals()
        .iter()
        .chain(registry.lexical_nominals())
    {
        let parameters = registry
            .nominal_parameters(nominal.id)
            .ok_or_else(resource)?;
        if let Some(representation) = &nominal.representation
            && type_requires_effect_core(
                parameters.len(),
                parameters.iter().map(|parameter| &parameter.kind),
                representation,
                budget,
            )?
        {
            return Ok(true);
        }
        for constructor in &nominal.constructors {
            let constructor = registry.constructor(*constructor).ok_or_else(resource)?;
            if let Some(payload) = &constructor.payload
                && type_requires_effect_core(
                    parameters.len(),
                    parameters.iter().map(|parameter| &parameter.kind),
                    payload,
                    budget,
                )?
            {
                return Ok(true);
            }
        }
    }

    let mut work = Vec::new();
    for group in program.groups() {
        for scheme in group.schemes() {
            if type_requires_effect_core(
                scheme.scheme.type_parameters.len(),
                scheme.scheme.type_parameters.iter().map(|(_, kind)| kind),
                scheme.scheme.value_type(),
                budget,
            )? {
                return Ok(true);
            }
        }
        for interface in group.interface_facts() {
            for method in &interface.methods {
                let parameters = interface
                    .parameters
                    .iter()
                    .chain(method.type_parameters.iter())
                    .map(|parameter| &parameter.kind);
                let parameter_count = interface
                    .parameters
                    .len()
                    .checked_add(method.type_parameters.len())
                    .ok_or_else(resource)?;
                if type_requires_effect_core(
                    parameter_count,
                    parameters,
                    &method.value_type,
                    budget,
                )? {
                    return Ok(true);
                }
            }
        }
        for implementation in group.implementation_facts() {
            for method in &implementation.methods {
                if type_requires_effect_core(
                    method.scheme.type_parameters.len(),
                    method.scheme.type_parameters.iter().map(|(_, kind)| kind),
                    method.scheme.value_type(),
                    budget,
                )? {
                    return Ok(true);
                }
            }
        }
        for definition in group.definitions() {
            match definition.kind() {
                ResolvedDefinitionKind::Equational(global) => {
                    for equation in &global.equations {
                        schedule(&mut work, &equation.body, budget)?;
                    }
                }
                ResolvedDefinitionKind::InlineOperational(global) => {
                    schedule_block(&mut work, &global.body, budget)?;
                }
            }
        }
        for implementation in group.implementations() {
            for method_group in implementation.method_groups() {
                for equation in &method_group.equations {
                    schedule(&mut work, &equation.body, budget)?;
                }
            }
        }
    }

    while let Some(expression) = work.pop() {
        match &expression.kind {
            ResolvedExprKind::Cleanup(_)
            | ResolvedExprKind::ProviderResource(_)
            | ResolvedExprKind::Resource(_)
            | ResolvedExprKind::Perform(_)
            | ResolvedExprKind::Handle(_)
            | ResolvedExprKind::Resume(_)
            | ResolvedExprKind::Discard(_) => return Ok(true),
            ResolvedExprKind::Tuple(elements) => {
                for element in elements {
                    schedule(&mut work, element, budget)?;
                }
            }
            ResolvedExprKind::Apply(application) => {
                schedule(&mut work, &application.argument, budget)?;
                schedule(&mut work, &application.function, budget)?;
            }
            ResolvedExprKind::Add(binary)
            | ResolvedExprKind::Multiply(binary)
            | ResolvedExprKind::Equal(binary) => {
                schedule(&mut work, &binary.right, budget)?;
                schedule(&mut work, &binary.left, budget)?;
            }
            ResolvedExprKind::Block(block) => schedule_block(&mut work, block, budget)?,
            ResolvedExprKind::Function(function) => {
                schedule_block(&mut work, &function.body, budget)?;
            }
            ResolvedExprKind::Match(matched) => {
                for arm in &matched.arms {
                    schedule(&mut work, &arm.body, budget)?;
                }
                schedule(&mut work, &matched.scrutinee, budget)?;
            }
            ResolvedExprKind::String(_)
            | ResolvedExprKind::Integer(_)
            | ResolvedExprKind::Boolean(_)
            | ResolvedExprKind::Unit
            | ResolvedExprKind::Occurrence(_)
            | ResolvedExprKind::Constructor(_) => {}
        }
    }
    Ok(false)
}

fn first_invalid_handler_operation_with_budget(
    owner: crate::types::EffectId,
    operation_count: usize,
    operations: impl ExactSizeIterator<Item = crate::types::OperationId>,
    budget: &mut TypeWorkBudget,
) -> Result<Option<(usize, HandlerCoverageCause)>, ()> {
    budget.charge(operation_count)?;
    let mut seen = Vec::new();
    seen.try_reserve(operation_count).map_err(|_| ())?;
    seen.resize(operation_count, false);

    budget.charge(operations.len())?;
    for (clause_index, operation) in operations.enumerate() {
        let Ok(index) = usize::try_from(operation.operation()) else {
            return Ok(Some((clause_index, HandlerCoverageCause::OperationIndex)));
        };
        let Some(slot) = seen.get_mut(index) else {
            return Ok(Some((clause_index, HandlerCoverageCause::OperationIndex)));
        };
        if operation.owner() != owner {
            return Ok(Some((clause_index, HandlerCoverageCause::OperationOwner)));
        }
        if std::mem::replace(slot, true) {
            return Ok(Some((
                clause_index,
                HandlerCoverageCause::DuplicateOperation,
            )));
        }
    }
    Ok(None)
}

fn resolved_module_binders(
    module: &ResolvedModule,
    charge: impl FnMut(usize) -> Result<(), BuildError>,
) -> Result<Vec<BinderId>, BuildError> {
    let mut binders = Vec::new();
    let mut expressions = Vec::new();
    for resource in module.resources() {
        binders.extend([
            resource.acquire_binder.id,
            resource.finish_binder.id,
            resource.handlers_binder.id,
        ]);
        expressions.extend([&resource.acquire, &resource.finish]);
        for clause in &resource.handlers {
            collect_pattern_binders(&clause.pattern, &mut binders);
            expressions.push(&clause.body);
        }
    }
    collect_definition_binders(module.definitions(), &mut binders, &mut expressions);
    collect_implementation_binders(module.implementations(), &mut binders, &mut expressions);
    collect_expression_binders(&mut binders, expressions, charge)?;
    Ok(binders)
}

fn collect_implementation_binders<'a>(
    implementations: &'a [crate::resolved::ResolvedImplementation],
    binders: &mut Vec<BinderId>,
    expressions: &mut Vec<&'a ResolvedExpr>,
) {
    for implementation in implementations {
        for group in &implementation.method_groups {
            binders.push(group.binder.id);
            for equation in &group.equations {
                for pattern in &equation.patterns {
                    collect_pattern_binders(pattern, binders);
                }
                expressions.push(&equation.body);
            }
        }
    }
}

fn collect_definition_binders<'a>(
    definitions: &'a [crate::resolved::ResolvedDefinition],
    binders: &mut Vec<BinderId>,
    expressions: &mut Vec<&'a ResolvedExpr>,
) {
    for definition in definitions {
        collect_definition_kind_binders(&definition.kind, binders, expressions);
    }
}

fn collect_definition_kind_binders<'a>(
    kind: &'a ResolvedDefinitionKind,
    binders: &mut Vec<BinderId>,
    expressions: &mut Vec<&'a ResolvedExpr>,
) {
    match kind {
        ResolvedDefinitionKind::Equational(equational) => {
            binders.push(equational.interface.name.id);
            for equation in &equational.equations {
                for pattern in &equation.patterns {
                    collect_pattern_binders(pattern, binders);
                }
                expressions.push(&equation.body);
            }
        }
        ResolvedDefinitionKind::InlineOperational(operational) => {
            binders.push(operational.header.name.id);
            for parameter in &operational.header.parameters {
                collect_pattern_binders(&parameter.pattern, binders);
            }
            expressions.push(&operational.body.result);
            for declaration in &operational.body.declarations {
                collect_resolved_declaration(declaration, binders, expressions);
            }
        }
    }
}

fn collect_expression_binders(
    binders: &mut Vec<BinderId>,
    mut expressions: Vec<&ResolvedExpr>,
    mut charge: impl FnMut(usize) -> Result<(), BuildError>,
) -> Result<(), BuildError> {
    while let Some(expression) = expressions.pop() {
        match &expression.kind {
            ResolvedExprKind::Apply(application) => {
                expressions.push(&application.argument);
                expressions.push(&application.function);
            }
            ResolvedExprKind::Add(binary)
            | ResolvedExprKind::Multiply(binary)
            | ResolvedExprKind::Equal(binary) => {
                expressions.push(&binary.right);
                expressions.push(&binary.left);
            }
            ResolvedExprKind::Block(block) => {
                expressions.push(&block.result);
                for declaration in &block.declarations {
                    collect_resolved_declaration(declaration, binders, &mut expressions);
                }
            }
            ResolvedExprKind::Function(function) => {
                collect_pattern_binders(&function.pattern, binders);
                expressions.push(&function.body.result);
                for declaration in &function.body.declarations {
                    collect_resolved_declaration(declaration, binders, &mut expressions);
                }
            }
            ResolvedExprKind::Tuple(elements) => expressions.extend(elements),
            ResolvedExprKind::Match(match_expression) => {
                expressions.push(&match_expression.scrutinee);
                for arm in &match_expression.arms {
                    collect_pattern_binders(&arm.pattern, binders);
                    expressions.push(&arm.body);
                }
            }
            ResolvedExprKind::ProviderResource(resource) => {
                let count = resource
                    .forwarding
                    .len()
                    .checked_mul(2)
                    .ok_or(BuildError::TypeWorkExceeded)?;
                charge(count)?;
                binders
                    .try_reserve(count.checked_add(1).ok_or(BuildError::TypeWorkExceeded)?)
                    .map_err(|_| BuildError::TypeWorkExceeded)?;
                for method in &resource.forwarding {
                    binders.push(method.binder.id);
                    binders.push(method.parameter.id);
                }
                binders.push(resource.handle.id);
                expressions.push(&resource.body);
                expressions.push(&resource.initializer);
            }
            ResolvedExprKind::Resource(resource) => {
                binders.push(resource.handle.id);
                expressions.push(&resource.body);
                expressions.push(&resource.initializer);
            }
            ResolvedExprKind::Cleanup(cleanup) => {
                expressions.push(&cleanup.body);
                expressions.push(&cleanup.action);
            }
            ResolvedExprKind::Perform(request) => expressions.push(&request.operand),
            ResolvedExprKind::Handle(handler) => {
                expressions.push(&handler.body);
                for clause in &handler.clauses {
                    collect_pattern_binders(&clause.pattern, binders);
                    expressions.push(&clause.body);
                }
            }
            ResolvedExprKind::Resume(resume) => expressions.push(&resume.value),
            ResolvedExprKind::Discard(_) => {}
            ResolvedExprKind::String(_)
            | ResolvedExprKind::Integer(_)
            | ResolvedExprKind::Boolean(_)
            | ResolvedExprKind::Unit
            | ResolvedExprKind::Occurrence(_)
            | ResolvedExprKind::Constructor(_) => {}
        }
    }
    Ok(())
}

fn collect_resolved_declaration<'a>(
    declaration: &'a ResolvedLocalDeclaration,
    binders: &mut Vec<BinderId>,
    expressions: &mut Vec<&'a ResolvedExpr>,
) {
    match declaration {
        ResolvedLocalDeclaration::Evidence(source) => {
            for group in &source.method_groups {
                binders.push(group.binder.id);
                for equation in &group.equations {
                    for pattern in &equation.patterns {
                        collect_pattern_binders(pattern, binders);
                    }
                    expressions.push(&equation.body);
                }
            }
        }
        ResolvedLocalDeclaration::Binding(binding) => {
            collect_pattern_binders(&binding.pattern, binders);
            expressions.push(&binding.initializer);
        }
        ResolvedLocalDeclaration::Recursive(group) => {
            for member in &group.members {
                binders.push(member.binder.id);
                expressions.push(&member.initializer);
            }
        }
        ResolvedLocalDeclaration::Newtype(_) => {}
    }
}

fn collect_pattern_binders(
    pattern: &crate::resolved::ResolvedPattern,
    binders: &mut Vec<BinderId>,
) {
    let mut patterns = vec![pattern];
    while let Some(pattern) = patterns.pop() {
        match &pattern.kind {
            crate::resolved::ResolvedPatternKind::Binder(binder) => binders.push(binder.id),
            crate::resolved::ResolvedPatternKind::Tuple(elements) => patterns.extend(elements),
            crate::resolved::ResolvedPatternKind::Constructor { payload, .. } => {
                if let Some(payload) = payload {
                    patterns.push(payload);
                }
            }
            crate::resolved::ResolvedPatternKind::Wildcard
            | crate::resolved::ResolvedPatternKind::Boolean(_)
            | crate::resolved::ResolvedPatternKind::Unit => {}
        }
    }
}

