    #[test]
    fn family_core_scheme_projection_preserves_pure_erasure_and_effect_rows() {
        const PURE_WORK: usize = 11;
        const EFFECT_WORK: usize = 21;

        let pure = TypeFact {
            ty: Type::Tuple(vec![Type::Int, Type::Bool, Type::Unit].into_boxed_slice()),
            provenance: TypeProvenance::unknown(&Type::Unit),
            quantified: vec![
                (TypeVariableId::new(0), Kind::Type),
                (TypeVariableId::new(1), Kind::Type),
                (TypeVariableId::new(2), Kind::Type),
            ]
            .into_boxed_slice(),
        };
        let mut pure_short = Elaborator::new();
        pure_short.type_work = TypeWorkBudget::with_limit(PURE_WORK - 1);
        assert_eq!(
            pure_short.pure_core_scheme(&pure),
            Err(TypeError::Internal(
                ElaborationFailure::TypeResourceExhausted
            ))
        );
        assert_eq!(pure_short.type_work.used(), PURE_WORK - 1);
        let mut pure_exact = Elaborator::new();
        pure_exact.type_work = TypeWorkBudget::with_limit(PURE_WORK);
        assert!(matches!(
            pure_exact.pure_core_scheme(&pure),
            Ok(Type::Forall(_, _))
        ));
        assert_eq!(pure_exact.type_work.used(), PURE_WORK);

        let row = TypeVariableId::new(9);
        let source_effects = EffectRow::open(
            EffectRowVariable::rigid(row),
            Box::new([row_test_effect("pure-core-scheme-effect.ash")]),
        );
        let effectful = TypeFact {
            ty: Type::function_computation(
                Type::Unit,
                ComputationType::new(Type::Int, source_effects),
            ),
            provenance: TypeProvenance::unknown(&Type::Unit),
            quantified: vec![(row, Kind::EffectRow)].into_boxed_slice(),
        };
        let mut effect_short = Elaborator::new();
        effect_short.type_work = TypeWorkBudget::with_limit(EFFECT_WORK - 1);
        assert_eq!(
            effect_short.pure_core_scheme(&effectful),
            Err(TypeError::Internal(
                ElaborationFailure::TypeResourceExhausted
            ))
        );
        assert_eq!(effect_short.type_work.used(), EFFECT_WORK - 1);
        assert!(matches!(effectful.ty, Type::EffectfulFunction(_, _)));
        assert_eq!(effectful.quantified.as_ref(), [(row, Kind::EffectRow)]);

        let mut effect_exact = Elaborator::new();
        effect_exact.type_work = TypeWorkBudget::with_limit(EFFECT_WORK);
        let projected = effect_exact
            .pure_core_scheme(&effectful)
            .expect("a fresh exact retry should project the complete scheme");
        assert_eq!(projected, Type::function(Type::Unit, Type::Int));
        assert_eq!(effect_exact.type_work.used(), EFFECT_WORK);
        assert!(matches!(effectful.ty, Type::EffectfulFunction(_, _)));
        assert_eq!(effectful.quantified.as_ref(), [(row, Kind::EffectRow)]);

        let retained = EffectElaborator::new()
            .pure_core_scheme(&effectful)
            .expect("Effect Core should retain the checked computation scheme");
        let Type::Forall(parameters, body) = retained else {
            panic!("Effect Core should retain the row binder");
        };
        assert_eq!(parameters.as_ref(), [(row, Kind::EffectRow)]);
        assert!(matches!(*body, Type::EffectfulFunction(_, _)));
    }

    #[test]
    fn effect_core_selection_scan_is_exact_retryable_and_stack_safe() {
        const DEPTH: usize = 96;

        let mut body = "{\n".repeat(DEPTH);
        body.push_str("()");
        body.push_str(&"\n}".repeat(DEPTH));
        let resolved = resolved_module_fixture("deep-effect-selection.ash", "", "Unit", &body);
        let module = resolved.module();
        let checked = check_module(resolved).expect("the deep selection fixture should check");
        let linked =
            link_modules(vec![checked], module).expect("the deep selection fixture should link");
        let program = crate::evidence_validation::validate_interface_evidence(linked)
            .expect("the deep selection fixture evidence should validate");

        std::thread::Builder::new()
            .name("effect-core-selection-budget".to_owned())
            .stack_size(64 * 1024)
            .spawn(move || {
                let mut calibration = TypeWorkBudget::unbounded();
                assert_eq!(
                    checked_program_contains_effect_syntax(&program, &mut calibration),
                    Ok(false)
                );
                let exact_work = calibration.used();
                assert!(exact_work > DEPTH);

                let mut one_short = TypeWorkBudget::with_limit(exact_work - 1);
                assert_eq!(
                    checked_program_contains_effect_syntax(&program, &mut one_short),
                    Err(TypeError::Internal(
                        ElaborationFailure::TypeResourceExhausted
                    ))
                );
                assert_eq!(one_short.used(), exact_work - 1);

                for _ in 0..2 {
                    let mut exact = TypeWorkBudget::with_limit(exact_work);
                    assert_eq!(
                        checked_program_contains_effect_syntax(&program, &mut exact),
                        Ok(false)
                    );
                    assert_eq!(exact.used(), exact_work);
                }
            })
            .expect("the small-stack selection worker should start")
            .join()
            .expect("the selection scan and fixture disposal should remain stack safe");
    }

    #[test]
    fn resolved_application_clone_discards_a_deep_first_argument_when_the_second_is_one_short() {
        const DEPTH: usize = 16_384;
        const DEEP_ARGUMENT_CELLS: usize = 1 + 2 * DEPTH;
        // Two staging/retained slots per argument, deep Type nodes and
        // the final Bool payload. Copy admission normalizes each tag to
        // its payload root; the argument slots account for retained tags.
        const EXACT_TYPE_WORK: usize = DEEP_ARGUMENT_CELLS + 5;

        std::thread::Builder::new()
            .name("resolved-application-partial-clone-owner".to_owned())
            .stack_size(256 * 1024)
            .spawn(|| {
                let source = SourceFile::new("resolved-application-clone.ash", "Pair")
                    .expect("the application fixture should fit");
                let span = source
                    .span(ByteRange::new(0, 4).expect("the fixture range is ordered"))
                    .expect("the fixture span should fit");
                let module = ModuleId::from(source.id());
                let interface = InterfaceId::new(module, 0);
                struct Application(Option<crate::resolved::ResolvedInterfaceApplication>);
                impl Drop for Application {
                    fn drop(&mut self) {
                        if let Some(application) = self.0.take() {
                            discard_origin_iteratively(application.interface.origin);
                            for argument in application.arguments {
                                argument.discard_iteratively();
                            }
                        }
                    }
                }
                let owned = Application(Some(crate::resolved::ResolvedInterfaceApplication {
                    interface: crate::resolved::ResolvedInterfaceOccurrence {
                        id: interface,
                        spelling: "Pair".to_owned(),
                        origin: Origin::Source(span),
                    },
                    arguments: Box::new([
                        ResolvedType {
                            ty: deep_application_type(DEPTH),
                            provenance: ResolvedTypeProvenance::new(
                                vec![ResolvedTypeProvenanceNode::Fact(span)],
                                0,
                            ),
                            origin: Origin::Source(span),
                            span,
                        }
                        .into(),
                        ResolvedType {
                            ty: Type::Bool,
                            provenance: ResolvedTypeProvenance::new(
                                vec![ResolvedTypeProvenanceNode::Fact(span)],
                                0,
                            ),
                            origin: Origin::Source(span),
                            span,
                        }
                        .into(),
                    ]),
                    span,
                }));
                let application = owned.0.as_ref().unwrap();

                let mut elaborator = Elaborator::new();
                elaborator.type_work = TypeWorkBudget::with_limit(EXACT_TYPE_WORK - 1);
                assert!(matches!(
                    elaborator.clone_resolved_interface_application(application),
                    Err(TypeError::Internal(
                        ElaborationFailure::TypeResourceExhausted
                    )),
                ));
                assert_eq!(elaborator.type_work.used(), EXACT_TYPE_WORK - 1);

                elaborator.type_work = TypeWorkBudget::with_limit(EXACT_TYPE_WORK);
                let cloned = elaborator
                    .clone_resolved_interface_application(application)
                    .expect("a fresh exact clone budget should retain both arguments");
                assert_eq!(cloned.arguments().len(), 2);
                assert_eq!(elaborator.type_work.used(), EXACT_TYPE_WORK);
                drop(cloned);
            })
            .expect("the small-stack clone worker should start")
            .join()
            .expect("partial and complete application clones must dismantle iteratively");
    }

    #[test]
    fn checked_parameter_clone_discards_a_deep_origin_on_partial_failure_and_exact_retry() {
        const DEPTH: usize = 16_384;
        // Vector records, spelling plus record, two cells per provenance node,
        // and the Type-kind node. The prefix retains only the deep first clone.
        const FIRST_PARAMETER_PREFIX: usize = 2 + 5 + 2 * (DEPTH + 1) + 1;
        const EXACT_TYPE_WORK: usize = FIRST_PARAMETER_PREFIX + 6 + 1;

        std::thread::Builder::new()
            .name("checked-parameter-partial-clone-owner".to_owned())
            .stack_size(256 * 1024)
            .spawn(|| {
                let source = SourceFile::new("checked-parameter-clone.ash", "Pair")
                    .expect("the parameter fixture should fit");
                let span = source
                    .span(ByteRange::new(0, 4).expect("the fixture range is ordered"))
                    .expect("the fixture span should fit");
                let module = ModuleId::from(source.id());
                let parameters = CheckedTypeVariableBuffer(vec![
                    ResolvedTypeVariable {
                        id: TypeVariableId::resolved(module, 0),
                        spelling: "Left".to_owned(),
                        kind: Kind::Type,
                        origin: deep_generated_origin(DEPTH, span),
                    },
                    ResolvedTypeVariable {
                        id: TypeVariableId::resolved(module, 1),
                        spelling: "Right".to_owned(),
                        kind: Kind::Type,
                        origin: Origin::Source(span),
                    },
                ]);

                let mut one_short = TypeWorkBudget::with_limit(FIRST_PARAMETER_PREFIX);
                assert!(matches!(
                    clone_checked_type_variables(&parameters.0, &mut one_short),
                    Err(TypeError::Internal(
                        ElaborationFailure::TypeResourceExhausted
                    )),
                ));
                assert_eq!(one_short.used(), FIRST_PARAMETER_PREFIX);

                let mut exact = TypeWorkBudget::with_limit(EXACT_TYPE_WORK);
                let cloned = clone_checked_type_variables(&parameters.0, &mut exact)
                    .expect("a fresh exact parameter budget should retain both records");
                assert_eq!(cloned.len(), 2);
                assert_eq!(exact.used(), EXACT_TYPE_WORK);
                let fact = CheckedInterfaceFact::without_methods_for_test(
                    InterfaceId::new(module, 0),
                    "Pair".to_owned(),
                    cloned.into_boxed_slice(),
                    Origin::Source(span),
                    span,
                );
                drop(fact);
                drop(parameters);
            })
            .expect("the small-stack parameter worker should start")
            .join()
            .expect("partial and complete parameter clones must dismantle origins iteratively");
    }

    #[test]
    fn scoped_evidence_binders_dispose_deep_interface_arguments_on_success_and_failure() {
        const DEPTH: usize = 32_768;
        for accepted in [false, true] {
            std::thread::Builder::new()
                .name(format!("scoped-evidence-disposal-{accepted}"))
                .stack_size(256 * 1024)
                .spawn(move || {
                    let source = SourceFile::new("scoped-evidence.ash", "()")
                        .expect("the fixture should fit");
                    let span = source
                        .span(ByteRange::new(0, 2).expect("the range is ordered"))
                        .expect("the span belongs to the fixture");
                    let origin = Origin::Source(span);
                    let module = ModuleId::new(0);
                    let owner = BinderId::resolved(module, 0);
                    let interface = InterfaceId::new(module, 0);
                    let method = MethodId::new(interface, 0);
                    let requirement = RequirementId::new(RequirementOwner::Global(owner), 0);
                    let mut builder = CoreBuilder::new();
                    let binder = builder
                        .binder(Type::Unit, origin)
                        .expect("the evidence binder should fit");
                    let mut interface_argument = Type::Unit;
                    for _ in 0..DEPTH {
                        interface_argument =
                            Type::Function(Box::new(Type::Unit), Box::new(interface_argument));
                    }
                    let scoped = vec![ScopedEvidenceBinder {
                        owner: MethodEvidenceOwner::Global(owner),
                        requirement,
                        method,
                        application: InterfaceApplication::new(
                            interface,
                            Box::new([interface_argument]),
                        ),
                        binder,
                    }];
                    let result = if accepted { Ok(scoped) } else { Err(scoped) };
                    drop(result);
                })
                .expect("the scoped-evidence worker should start")
                .join()
                .expect("both accepted and rejected scope owners must tear down iteratively");
        }
    }

