    #[test]
    fn row_exclusion_rechecks_solution_arguments_and_rolls_back_type_conflicts() {
        let span = row_test_span("row-exclusion-arguments.ash");
        let mut elaborator = Elaborator::new();
        let argument = elaborator.fresh_inference(&Kind::Type, span).unwrap();
        let open = elaborator.fresh_effect_row(span).unwrap();
        let effect = row_test_effect("row-exclusion-read.ash");
        let member = |ty| crate::types::EffectInstance::new(effect.effect(), Box::new([ty]));
        let constrained = EffectRow::with_tail(
            Box::new([]),
            open.tail().unwrap().variable(),
            Box::new([member(Type::Int)]),
        );
        let solution = EffectRow::singleton(member(argument.clone()));
        elaborator
            .unify_effect_rows(&constrained, &solution)
            .unwrap();
        assert!(matches!(
            elaborator.unify(&argument, &Type::Int),
            Err(UnificationFailure::RowExclusion)
        ));
        assert_eq!(elaborator.zonk(&argument).unwrap(), argument);
        elaborator.unify(&argument, &Type::Bool).unwrap();
        assert_eq!(
            elaborator.zonk_effect_row(&constrained).unwrap(),
            EffectRow::singleton(member(Type::Bool))
        );
    }

    #[test]
    fn retained_row_exclusion_validation_is_exact_atomic_and_retryable() {
        let span = row_test_span("row-exclusion-budget.ash");
        let member = |ty| {
            crate::types::EffectInstance::new(
                crate::types::EffectId::new(ModuleId::new(93), 0),
                Box::new([ty]),
            )
        };
        let fixture = || {
            let mut elaborator = Elaborator::new();
            let argument = elaborator.fresh_inference(&Kind::Type, span).unwrap();
            let open = elaborator.fresh_effect_row(span).unwrap();
            let constrained = EffectRow::with_tail(
                Box::new([]),
                open.tail().unwrap().variable(),
                Box::new([member(Type::Int)]),
            );
            let solution = EffectRow::singleton(member(argument.clone()));
            elaborator
                .unify_effect_rows(&constrained, &solution)
                .unwrap();
            (elaborator, argument, constrained)
        };
        let (mut calibration, argument, _) = fixture();
        calibration.type_work = TypeWorkBudget::unbounded();
        calibration.unify(&argument, &Type::Bool).unwrap();
        let exact = calibration.type_work.used();
        let (mut retry, argument, constrained) = fixture();
        retry.type_work = TypeWorkBudget::with_limit(exact - 1);
        assert_eq!(
            retry.unify(&argument, &Type::Bool),
            Err(UnificationFailure::Resource)
        );
        assert!(retry.inference_solutions.is_empty());
        assert_eq!(retry.row_inference_solutions.len(), 1);
        assert_eq!(retry.row_inference_obligations.len(), 1);
        retry.type_work = TypeWorkBudget::with_limit(exact);
        retry.unify(&argument, &Type::Bool).unwrap();
        assert_eq!(retry.type_work.used(), exact);
        retry.type_work = TypeWorkBudget::default();
        assert_eq!(
            retry.zonk_effect_row(&constrained).unwrap(),
            EffectRow::singleton(member(Type::Bool))
        );
    }

    #[test]
    fn row_inference_unifies_exact_members_and_rejects_occurs() {
        let span = row_test_span("row-unification.ash");
        let mut elaborator = Elaborator::new();
        let open = elaborator
            .fresh_effect_row(span)
            .expect("a row inference variable should fit");
        let variable = open.tail().expect("the row should be open").variable();
        let member = row_test_effect("row-unification-effect.ash");
        let closed = crate::types::EffectRow::singleton(member.clone());

        elaborator
            .unify_effect_rows(&open, &closed)
            .expect("an unconstrained row variable should solve to the closed row");
        assert_eq!(
            elaborator
                .zonk_effect_row(&open)
                .expect("the solved row should zonk"),
            closed,
        );

        let mut open_tails = Elaborator::new();
        let left_tail = open_tails
            .fresh_effect_row(span)
            .expect("the left row variable should fit")
            .tail()
            .expect("the left row should be open")
            .variable();
        let right_tail = open_tails
            .fresh_effect_row(span)
            .expect("the right row variable should fit")
            .tail()
            .expect("the right row should be open")
            .variable();
        let left = EffectRow::with_tail(
            Box::new([row_test_effect("left-open-member.ash")]),
            left_tail,
            Box::new([row_test_effect("left-open-lacks.ash")]),
        );
        let right = EffectRow::with_tail(
            Box::new([row_test_effect("right-open-member.ash")]),
            right_tail,
            Box::new([row_test_effect("right-open-lacks.ash")]),
        );
        open_tails
            .unify_effect_rows(&left, &right)
            .expect("two inference tails should share a fresh residual tail");
        assert_eq!(
            open_tails
                .zonk_effect_row(&left)
                .expect("the left row should zonk"),
            open_tails
                .zonk_effect_row(&right)
                .expect("the right row should zonk"),
        );
        open_tails
            .unify_effect_rows(&left, &right)
            .expect("the shared residual row should unify again");

        let recursive = crate::types::EffectRow::with_tail(
            Box::new([member.clone()]),
            variable,
            Box::new([member]),
        );
        let mut occurs = Elaborator::new();
        let occurs_open = occurs
            .fresh_effect_row(span)
            .expect("an occurs row variable should fit");
        let occurs_variable = occurs_open
            .tail()
            .expect("the occurs row should be open")
            .variable();
        let recursive = crate::types::EffectRow::with_tail(
            recursive.known().to_vec().into_boxed_slice(),
            occurs_variable,
            recursive.known().to_vec().into_boxed_slice(),
        );
        assert_eq!(
            occurs.unify_effect_rows(&occurs_open, &recursive),
            Err(UnificationFailure::Infinite),
        );
    }

    #[test]
    fn row_solver_refuses_nested_and_mutual_inference_cycles_before_publication() {
        use crate::types::{KindedArgument, ResourceDefinitionId};
        std::thread::Builder::new()
            .name("nested-row-occurs".to_owned())
            .stack_size(256 * 1024)
            .spawn(|| {
                let span = row_test_span("nested-row-occurs.ash");
                let mut elaborator = Elaborator::new();
                let x = elaborator.fresh_effect_row(span).expect("fresh X row");
                let y = elaborator.fresh_effect_row(span).expect("fresh Y row");
                let EffectRowVariable::Inference(x_id) = x.tail().expect("X tail").variable()
                else {
                    panic!("X inference");
                };
                let EffectRowVariable::Inference(y_id) = y.tail().expect("Y tail").variable()
                else {
                    panic!("Y inference");
                };
                let module = ModuleId::new(0);
                let effect = crate::types::EffectId::new(module, 0);
                let resource = ResourceDefinitionId::new(module, 0);
                let nested = |row| {
                    EffectRow::singleton(EffectInstance::new_kinded(
                        effect,
                        Box::new([KindedArgument::RowArg(row)]),
                    ))
                };
                // This raw structural fixture observes the actual private row
                // solution-publication seam. It does not establish source,
                // effect-signature or resource-category admission.
                let mut deep = x.clone();
                for _ in 0..2_048 {
                    deep = EffectRow::singleton(EffectInstance::new_kinded(
                        effect,
                        Box::new([KindedArgument::TypeArg(Type::ResourceApply(
                            resource,
                            Box::new([
                                KindedArgument::TypeArg(Type::Unit),
                                KindedArgument::RowArg(deep),
                            ]),
                        ))]),
                    ));
                }
                let mut inserted = Vec::new();
                assert_eq!(
                    elaborator.solve_effect_row_variable(x_id, &[], deep, &mut inserted),
                    Err(UnificationFailure::Infinite)
                );
                assert!(inserted.is_empty());
                assert!(elaborator.row_inference_solutions.is_empty());
                assert!(!elaborator.authenticated_inference_solutions.contains(&x_id));
                let lacks_only = EffectRow::open(
                    EffectRowVariable::rigid(TypeVariableId::generated(0)),
                    Box::new([EffectInstance::new_kinded(
                        effect,
                        Box::new([KindedArgument::RowArg(x.clone())]),
                    )]),
                );
                assert_eq!(
                    elaborator.solve_effect_row_variable(x_id, &[], lacks_only, &mut inserted),
                    Err(UnificationFailure::Infinite)
                );
                assert!(inserted.is_empty());
                elaborator
                    .solve_effect_row_variable(x_id, &[], nested(y.clone()), &mut inserted)
                    .expect("acyclic X depends on Y");
                assert_eq!(inserted, vec![x_id]);
                let before = elaborator
                    .row_inference_solutions
                    .get(&x_id)
                    .expect("original X solution")
                    .clone();
                assert_eq!(
                    elaborator.solve_effect_row_variable(
                        y_id,
                        &[],
                        nested(x.clone()),
                        &mut inserted
                    ),
                    Err(UnificationFailure::Infinite)
                );
                assert_eq!(inserted, vec![x_id]);
                assert_eq!(elaborator.row_inference_solutions.get(&x_id), Some(&before));
                assert!(!elaborator.row_inference_solutions.contains_key(&y_id));
                assert!(!elaborator.authenticated_inference_solutions.contains(&y_id));
                elaborator
                    .solve_effect_row_variable(y_id, &[], EffectRow::empty(), &mut inserted)
                    .expect("cycle refusal permits a later acyclic retry");
                assert_eq!(inserted, vec![x_id, y_id]);
            })
            .expect("spawn nested row occurs worker")
            .join()
            .expect("nested row occurs worker");
    }

